/* Mächte aus dem Super-Powers-Kompendium (SUP) */
(function(){
var H = SW_MH;
H.add([{"n": "Absorption", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Amorphe Form, Materie- oder Energiekontrolle, Phasenverschiebung, Magie", "b": ["Der Charakter kann eine bestimmte Art von Materie oder Energie absorbieren, neutralisieren und vielleicht sogar kanalisieren, die aus den Machttypen (S. 43) gewählt wird.", "Würde der Superheld eine oder mehrere Wunden von diesem Machttyp erleiden, erhält er einen kostenlosen Aufnehmen-Wurf mit Fokus statt Konstitution (alle Regeln, die für Konstitution beim Aufnehmen gelten, gelten auch für Fokus)."], "m": [["ACHILLESFERSE", "–1", "Dieser Modifikator darf nur mit der +4- oder +8-Version des Modifikators Zusätzliche Machttypen (siehe unten) genommen werden. Der Charakter kann zwei Machttypen aus seiner Liste absorbierbarer Typen nicht absorbieren. (Das Schwarze Loch kann zum Beispiel alle Energie absorbieren außer Magie und Mentales.)"], ["ZUSÄTZLICHE MACHTTYPEN", "+1/+2/+4/+8", "Dein Held kann zusätzliche Machttypen absorbieren. Für +1 Punkt wähle einen zusätzlichen Machttyp. Für +2 Punkte wähle bis zu drei zusätzliche Machttypen. Für +4 Punkte gilt die Absorption für alle Machttypen derselben Kategorie wie der ursprünglich gewählte (alle Materie oder alle Energie). Für +8 Punkte kann dein Charakter alle Machttypen absorbieren."], ["WACHSTUM", "+3", "Jede absorbierte Wunde erhöht die Größe des Helden um +1. Das erhöht Stärke und Robustheit um eine Stufe, als hätte er die Kraft Wachstum (S. 64). Der Effekt hält bis zum Ende der Begegnung oder bis der Held zu seiner normalen Größe zurückkehren will (freie Aktion)."], ["MEISTERSCHAFT", "+1", "Der Superheld addiert +2 auf den Fokuswurf, um einen bestimmten Machttyp zu absorbieren. Das kann mehrfach genommen werden, wenn du den Modifikator Zusätzliche Machttypen hast (einmal pro Typ)."], ["REFLEXION", "+2", "Der Charakter kann alle absorbierten Wunden auf einen beliebigen Feind innerhalb von 12“ (24 Metern) umleiten. Er darf absorbierte Wunden auf mögliche Ziele aufteilen, wenn er will. Diese Ziele dürfen wie üblich aufnehmen und können versuchen, sie ebenfalls zu absorbieren, wenn sie auch diese Kraft haben!"], ["ÜBERTRAGUNG", "+2", "Jedes Mal, wenn der Held eine Wunde absorbiert, darf er eine Eigenschaft um einen Würfeltyp erhöhen. Das hält fünf Runden an und hat ein Maximum von +4 Würfeltypen bei einer einzelnen Eigenschaft."], ["UMWANDLUNG", "+3", "Für jede aufgenommene Wunde erhält der Held einen „Umwandlungsmarker“. Diese Marker halten bis zum Ende der Szene und können als freie Aktion eingesetzt werden, um einen der folgenden Effekte auszulösen: Schaden: Addiere +1W6 pro Marker auf einen Schadenswurf (maximal drei Marker pro Schadenswurf). Robustheit: Erhöhe die Robustheit um +1 pro Marker bis zum Ende der Begegnung. Kraftkunststück: Führe ein Kraftkunststück (S. 30) genau so aus, als hättest du einen Benny ausgegeben."]], "s": ["SUP"], "p": 48}, {"n": "Zusätzliche Aktionen", "r": 5, "mp": "5/10/15", "rw": "", "wd": "", "au": "Supergeschwindigkeit, Adrenalinschub, überanalytischer Verstand, Zeitkontrolle, zusätzliche oder Roboter-Gliedmaßen", "b": ["Schnelle Helden, Schurken mit mehreren Armen oder Genies mit überanalytischem Verstand können unglaublich effizient arbeiten und in einem Zug mehr tun als andere.", "Für fünf Punkte verringert Zusätzliche Aktionen den gesamten Mehrfachaktionsabzug eines Charakters um zwei. Sie könnte zum Beispiel drei Aktionen mit je –2 oder zwei Aktionen ohne Abzug ausführen.", "Für zehn Punkte verringert die Kraft den gesamten Mehrfachaktionsabzug um vier. Sie kann drei verschiedene Aktionen ohne Abzug ausführen.", "Für 15 Punkte hat sie maximal vier Aktionen pro Zug statt drei. Das wendet einen Mehrfachaktionsabzug von insgesamt –6 an (für drei zusätzliche Aktionen), der aber um vier auf –2 verringert wird.", "Zusätzliche Aktionen ist mit allen anderen Talenten oder Kräften kumulativ, die den Mehrfachaktionsabzug verringern. Charaktere sind weiterhin auf drei Aktionen pro Zug beschränkt (oder vier, wenn sie die 15-Punkte-Option nehmen), und wie immer müssen alle Aktionen angesagt werden, bevor eine aufgelöst wird. Wird eine Aktion unmöglich, meist weil sie von einer vorherigen Aktion abhing, ist sie verloren."], "m": [["KONZENTRATION", "+2", "Führt der Held nur eine einzige Aktion aus, kann sie sich „konzentrieren“, um stattdessen +1 auf einen beliebigen Eigenschaftswurf in diesem Zug zu addieren. Hat sie 10 oder 15 Punkte in dieser Kraft und konzentriert sich in einem Zug auf nur zwei Aktionen, addiert sie +1 auf jede. Konzentriert sie sich auf eine einzige Aktion, addiert sie +2."], ["AUSWERTUNG", "+2", "Statt alle Aktionen gleichzeitig anzusagen, kann der Superheld jede einzeln abschließen und ihre Wirkung beurteilen, bevor er die nächste ansagt. Die Zahl der genutzten Aktionen muss trotzdem angesagt werden, bevor eine aufgelöst wird."], ["SCHNELLE AKTION", "+2", "Der Held kann längere Aufgaben schneller ausführen (wenn möglich, Entscheidung der SL). Jede Aufgabe, die weniger als eine Minute (zehn Runden) dauert, kann in einer einzigen Aktion ausgeführt werden. Aufgaben, die Minuten erfordern, sind in so vielen Runden erledigt, und Aufgaben, die Stunden erfordern, in so vielen Minuten."], ["NUR MENTAL", "–1", "Die Kraft wirkt nur, wenn alle Aktionen des Charakters mental oder spirituell sind (an Verstand oder Willenskraft gebunden)."], ["NUR KÖRPERLICH", "–1", "Die Kraft wirkt nur, wenn alle Aktionen des Charakters körperlich sind (an Geschicklichkeit oder Stärke gebunden)."]], "s": ["SUP"], "p": 48}, {"n": "Alterslos", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Unsterblichkeit, biologische Erneuerung, Körper aus exotischem Material oder Energie", "b": ["Der Held altert nie. Er bleibt dauerhaft in dem Alter, das der Spieler wählt.", "Alterslose Charaktere haben oft Superfertigkeiten oder Supertalente, die ihr langes Leben und ihre große Erfahrung widerspiegeln.", "Allgemeine Modifikatoren wie Bedingt oder Einschränkung dürfen nicht genommen werden, da sie keine unmittelbare Wirkung hätten."], "m": [["SEHR ALT", "+2", "Der Charakter ist bereits recht alt, auch wenn man es ihm nicht ansieht. Seine Lebenserfahrung gibt ihm +2 auf Verstand- und Allgemeinwissenwürfe."]], "s": ["SUP"], "p": 49}, {"n": "Veränderte Form", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Eine Energieform, ein Körper aus einer bestimmten Materie, Dehnbarkeit", "b": ["Der Held hat einen formbaren Körper aus einer bestimmten Art von Energie oder Materie. Das ist sein normaler Dauerzustand – nimm Aktivierung erforderlich, wenn er normalerweise menschlich ist und in seine veränderte Form wechseln muss.", "Der Gestaltwandler hat keine lebenswichtigen Organe (oder sie sind sehr widerstandsfähig, geschützt oder verborgen), daher haben Gezielte Angriffe keine Wirkung auf ihn. Er erleidet nur halben Schaden durch Stürze oder Kollisionen, und jeder Rückstoß gegen ihn wird halbiert.", "Zusätzliche Kräfte sind nötig, um bestimmte Formen darzustellen, etwa Absorption mit dem Modifikator Reflexion für einen dehnbaren Gummibandeffekt, Schadensfeld oder Gift, wenn die Form für andere gefährlich ist, oder Regeneration mit einem Modifikator Situativ, wenn er einen Machttyp absorbieren kann, um Wunden zu heilen."], "m": [["STURZSICHER", "+1", "Höhen sind für diesen Superhelden keine Gefahr. Seine formbare Gestalt erlaubt es ihm, zu fallen, zu hüpfen, zu gleiten oder Sturzschaden anderweitig zu ignorieren."], ["GREIFER", "+1", "Der Held kann seine Glieder leicht um Feinde schlingen, was ihm +2 auf Ringkampfangriffe gibt – oder darauf, sich aus Fesseln oder Verstrickung zu befreien."], ["REICHWEITE", "+1", "Der Superheld kann seine Glieder dehnen, was jedes Mal, wenn dieser Modifikator genommen wird, +1 Reichweite pro Punkt gibt."], ["AKTIVIERUNG ERFORDERLICH", "–1", "Der Held ist normalerweise menschlich und muss als Aktion einen Fokuswurf ablegen, um sich in seine veränderte Form zu verwandeln. Verliert er die Konzentration, fährt sie herunter und muss neu aktiviert werden (siehe S. 42)."], ["KLEBRIG", "+2", "Waffen oder Fäuste, die den Helden treffen, können in ihrer veränderten Form stecken bleiben. Wird der klebrige Held durch einen Angriff Angeschlagen oder Verwundet, ist der Angreifer in der Form des klebrigen Helden Verstrickt, als würde er festgehalten (wenn der Held das will)."], ["ZÄHFLÜSSIG", "+2", "Der Gestaltwandler kann seinen Körper durch die meisten kleinen Öffnungen pressen (Entscheidung der SL). Durch Gitter oder große Öffnungen zu sickern wird wie schwieriges Gelände behandelt. Papierdünne Ritzen und Ähnliches brauchen W6 Runden, wodurch der Held Verwundbar ist, bis er sich neu formt."], ["NACHGEBEN", "+1", "Hoher Schaden fährt durch die veränderte Form des Supers, oder seine Haut dehnt sich und schnappt sofort zurück, wodurch er immun gegen Rückstoß ist."]], "s": ["SUP"], "p": 49}, {"n": "Tiergefährte", "r": 5, "mp": "3 + Größe", "rw": "", "wd": "", "au": "Ein ausgebildeter Wolf, ein Geisterlöwe, ein Superhund", "b": ["Der Held hat einen treuen tierischen Gefährten. Die Kreatur ist ein Wildcard und kann Bennys mit ihrem Meister teilen und umgekehrt.", "Das Profil des Tiers entspricht dem einer normalen Kreatur, die im Kampagnen-Setting existiert, und seine Kosten in Super-Machtpunkten betragen 3 plus seine Größe. (Die Mindestkosten der Kraft betragen 1.)", "Tiergefährten steigen nicht auf. Sie haben ihre eigenen Persönlichkeiten und dieselben Schwächen und Wünsche wie andere ihrer Art.", "Tod: Wird ein Tiergefährte getötet, kann der Held ein anderes ausbilden oder anderweitig anziehen. Wie genau das geschieht und wie schnell, sollte mit der SL abgesprochen werden und eine Art Erzählung oder „Schnittszene“ zwischen Abenteuern haben, die erklärt, wie es dazu kam.", "Mehrere Gefährten: Diese Kraft kann mehr als einmal genommen werden, um verschiedene Gefährten zu erschaffen."], "m": [["INTELLIGENT", "+2", "Die Kreatur hat menschlichen Verstand statt „tierischem“ Verstand."], ["SPRECHEN", "+2", "Das Tier kann sprechen. Es könnte einen elektronischen „Übersetzer“ haben, der einfache Verständigung in menschliche Sprache umwandelt, oder, wenn intelligent, normal sprechen."], ["HERBEIRUFBAR", "+2", "Der Held kann einen Tiergefährten mit einem Fokuswurf herbeirufen. Bei Erfolg erscheint er irgendwo innerhalb von 12“ (24 Metern). Mit einer Steigerung beim Fokuswurf kann die Kreatur sofort handeln – sonst handelt sie auf der nächsten Aktionskarte des Beschwörers. Sie kann als begrenzte freie Aktion entlassen werden (kein Wurf nötig)."], ["SUPERKRÄFTE", "+3/+8", "Für +3 Punkte hat das Tier so viele Super-Machtpunkte wie das Machtlimit seines Meisters (hat selbst aber kein Limit). Für +8 Punkte hat der Gefährte so viele Super-Machtpunkte wie sein Meister. Das Tier muss das Machtlimit wie üblich beachten, also nutze Supertalent, um bei Bedarf das Talent „Der Beste“ zu nehmen. Supermächtige Tiergefährten haben die Fertigkeit Fokus auf W8."], ["TELEPATHISCHE VERBINDUNG", "+1", "Der Superheld und sein Gefährte können über Telepathie in einer Reichweite von 24“ (48 Metern) kommunizieren. Das ist eine begrenzte Version der Kraft Telepathie und gewährt keine ihrer anderen Fähigkeiten."]], "s": ["SUP"], "p": 50}, {"n": "Tierkontrolle", "r": 5, "mp": "Speziell", "rw": "", "wd": "", "au": "Dschungelvolk, tierische Merkmale, Hightech-Geräte, Talismane", "b": ["Der Champion kann Tiere ihrer Welt mental kontrollieren und mit ihnen kommunizieren. Je mehr Punkte ein Charakter in Tierkontrolle hat, desto mehr Bestien kann sie gleichzeitig befehligen. Das gewährt ihr kein Haustier (dafür nutze Tiergefährte), es erlaubt ihr nur, jene zu kontrollieren, denen sie begegnet.", "Die Größe eines Tiers entspricht den Punkten, die nötig sind, um es zu kontrollieren (Mindestkosten 1). Ein Löwe (Größe 1) braucht zum Beispiel 1 Punkt Tierkontrolle, ein Nashorn der Größe 5 braucht 5 Punkte.", "Ein Charakter kann so viele Tiere gleichzeitig kontrollieren, wie es seiner Stufe entspricht. Mit 8 Punkten in Tierkontrolle könnte sie zum Beispiel einen Löwen und ein Nashorn gleichzeitig kontrollieren.", "Die Reichweite beträgt 12“ (24 Meter), und die Kontrolle über beliebige oder alle Tiere in Reichweite zu übernehmen ist eine Aktion und ein Fokuswurf (mit –2, wenn das Tier feindselig, verletzt, verängstigt usw. ist).", "Der Charakter kann verbal mit den Tieren unter seinem Befehl kommunizieren, aber die Bestien verstehen nur einfache Befehle wie „greife diese Person an“ oder „bring mir diesen Schlüssel“. In einer Gruppe ähnlicher Bedrohungen zum Angreifen oder Objekten zum Holen können sie verwirrt werden.", "Schwärme: Ratten, Insekten und kleinere Kreaturen können als Schwärme kontrolliert werden. Ein großer Schwarm hat Größe 3, ein mittlerer Größe 2, ein kleiner Größe 1. So beschworene Schwärme teilen sich nie (siehe Schwärme in Savage Worlds).", "Rivalisierende Bestien: Wird eine Kreatur bereits von einem anderen kontrolliert (über die Kraft Tierkontrolle oder Tiergefährte oder das Talent Tiermeister), wird der Fokuswurf des Kontrolleurs stattdessen gegen den Fokus oder die Willenskraft des Gegners abgelegt (Wahl des Verteidigers)."], "m": [["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss ein Tier berühren, um es zu kontrollieren. Das darf nicht mit den Modifikatoren Reichweite oder Herbeirufbar kombiniert werden. Siehe S. 45 für weitere Informationen."], ["HERBEIRUFBAR", "+4", "Der Held kann Tiere mit einem Fokuswurf mit –2 und einer Aktion herbeirufen (das kontrolliert die Kreatur oder Kreaturen auch). Die Tiere erscheinen innerhalb von 12“ (24 Metern). Mit einer Steigerung beim Fokuswurf können sie sofort handeln – sonst handeln sie auf der nächsten Aktionskarte des Beschwörers. Wird eine beschworene Kreatur getötet, stehen die ihr zugewiesenen Super-Machtpunkte eine Stunde lang nicht zur Verfügung."], ["TELEPATHISCHE VERBINDUNG", "+1/+2", "Der Superheld kann mit Tieren unter seiner Kontrolle über Telepathie sprechen. Sie verstehen seine einfachen Anweisungen, und er kann ihre Hauptgefühle lesen. Die Reichweite beträgt 24“ (48 Metern) für einen Punkt oder eine Meile für 2 Punkte."]], "s": ["SUP"], "p": 51}, {"n": "Wasserlebewesen", "r": 5, "mp": "1/2", "rw": "", "wd": "", "au": "Atlantisches Erbe, amphibisch, versiegelte Systeme, Geräte", "b": ["Für einen Machtpunkt ist der Charakter halb wasserlebend und kann 15 Minuten die Luft anhalten, bevor er auf Ertrinken prüfen muss. Für zwei Punkte ist er im Wasser heimisch. Er kann in sauerstoffhaltiger Flüssigkeit nicht ertrinken und bewegt sich beim Schwimmen mit voller Bewegungsweite.", "Siehe S. 99 für Regeln zum Führen von Abenteuern im Stil von Comics unter Wasser."], "m": [["SCHNELLER SCHWIMMER", "+1/+2", "Der Charakter schwimmt mit seiner normalen Bewegungsweite +2 für einen Punkt oder Bewegungsweite +4 für zwei Punkte."]], "s": ["SUP"], "p": 52}, {"n": "Rüstung", "r": 5, "mp": "1/Stufe", "rw": "", "wd": "", "au": "Körperpanzer, gehärtete Haut, eine magische Schale, Kampfanzüge", "b": ["Ein Charakter erhält 2 Punkte Rüstung jedes Mal, wenn diese Kraft gekauft wird. Rüstung ist nicht kumulativ mit getragener Rüstung, aber kumulativ mit natürlicher Rüstung und der Kraft Robustheit (S. 88).", "Schwachstellen, kleine Lücken oder Gelenke können mit einem Gezielten Angriff mit –6 umgangen werden. Für 100 % Schutz nimm stattdessen Robustheit (S. 88).", "Maximale Robustheit: Der kombinierte Bonus aus den Kräften Robustheit und Rüstung darf das Machtlimit nicht überschreiten. Die gesamte Robustheit ist unbegrenzt (durch erhöhte Konstitution, Größe usw.). Ein Superheld der Stufe II hat zum Beispiel Machtlimit 10. Sie könnte 6 Punkte Rüstung und +4 Robustheit (S. 88) haben oder jede andere Kombination von insgesamt 10 Punkten oder weniger, die zu ihrer abgeleiteten Robustheit addiert werden."], "m": [["SCHWERE RÜSTUNG", "+4", "Ein Charakter muss mindestens 4 Punkte Rüstung haben, um diesen Modifikator zu nehmen. Die Rüstung gilt als Schwere Rüstung und kann nur durch Schwere Waffen beschädigt werden."], ["TEILSCHUTZ", "–1/–2", "Die Rüstung hat größere Lücken oder weniger Abdeckung als üblich. Für –1 Punkt werden Gezielte Angriffe, die die Rüstung umgehen, mit –4 statt –6 abgelegt. Für –2 Punkte beträgt der Abzug nur –2."], ["AKTIVIERUNG ERFORDERLICH", "–1", "Der Held muss als Aktion einen Fokuswurf zur Aktivierung ablegen. Verliert er die Konzentration, fährt sie herunter und muss neu aktiviert werden (siehe S. 42)."], ["VERSIEGELT", "+2", "Die Rüstung ist ein luftdichter Anzug oder eine Hülle (meist über den Modifikator Gerät). Sie bietet eine Stunde Sauerstoff und addiert +2 auf den Wurf des Trägers beim Widerstehen luftübertragener Giftstoffe oder ähnlicher Bedrohungen. (Für volle Immunität nimm Immun gegen Gift/Krankheit, S. 67.)"]], "s": ["SUP"], "p": 52, "k": [{"h": "Unsere Waffen haben keine Wirkung auf ihn!", "b": ["Zwischen Absorption, Rüstung und Robustheit scheinen manche Schurken (und Helden) für die meisten Angriffe nahezu unverwundbar. Was tust du, wenn du einem solchen Gegner gegenüberstehst?", "Zunächst: Das ist das täglich Brot von Comics. So soll es funktionieren! Das zwingt die Helden, sich Wege auszudenken, ihre Gegner zu besiegen, statt immer wieder zuzuschlagen und auf einen Glückstreffer zu hoffen.", "Manche Probleme lassen sich nicht mit rohem Schaden lösen. Suche nach Wegen, den besonderen Schutz einer Kraft zu umgehen. Absorption gilt nur für bestimmte Machttypen und kann auf eine Schwäche gegenüber dem entgegengesetzten Typ hinweisen. Kluge Nutzung der Umgebung oder ein gut durchdachtes Kraftkunststück kann ebenfalls die andere Energie erzeugen, die für maximale Wirkung nötig ist. Selbst wenn es nicht klappt, können kluge Ideen und ausrufende Dialoge die Bennys erzeugen, die nötig sind, um den Kampf anders zu beenden.", "Und wenn ein Gegner zu schwer zu treffen ist, weil er fliegt oder zu schnell rennt, denk daran, dass Flächenangriffe alles treffen, was darunter ist, unabhängig von Angriffsabzügen!", "Kombinierte Angriffe mit einem ganzen Team können ebenfalls massenhaft zusätzlichen Schaden erzeugen. Füge einen Gezielten Angriff hinzu, und kaum etwas hält stand! Für den letzten großen Angriff erwäge ein Kraftkunststück wie Alles auf eine Karte, um das Schadenspotenzial zu steigern.", "Wenn all das scheitert, liegt die Lösung vielleicht ganz woanders. Vielleicht kann der Gegner gefangen oder entmachtet werden. Oder die Gruppe kann mit ihm reden! Was will er? Was kann getan werden, um ihn daran zu hindern, sein Ziel zu erreichen, statt ihn direkt anzugreifen?", "Schließlich sollten die Helden manchmal scheitern. Das ist ab und zu ein großartiger Erzählmoment und zwingt sie, sich neu zu formieren, ihre Wunden zu lecken und sich für die nächste Begegnung etwas Kluges auszudenken."]}]}, {"n": "Wachsamkeit", "r": 5, "mp": "1/Stufe", "rw": "", "wd": "", "au": "Radar, Sonar, Zen-Training, vorausahnende Bewegung", "b": ["Der Krieger kann die Bewegungen seiner Feinde spüren und vorhersagen. Er ignoriert 1 Punkt Angriffsabzüge für jede Stufe in dieser Kraft.", "Angriffsabzüge sind alle Abzüge, die das Ziel den Angreifer von seinem Gesamtergebnis abziehen lässt, etwa das Talent Ausweichen oder die Kraft Ausweichen, Flug- oder Geschwindigkeitsabzüge (natürlich oder durch Kräfte) usw. Es hat keine Wirkung auf Parade oder das Talent Blocken, da dies keine tatsächlichen Abzüge sind.", "Wachsamkeit gleicht keine Abzüge aus, die durch die eigenen Zustände oder Handlungen des Angreifers entstehen (Abgelenkt, Erschöpfung, Wunden usw.) oder durch die Umgebung (Deckung, Beleuchtung usw.)."], "m": [["AKTIVIERUNG ERFORDERLICH", "–1", "Der Held muss als Aktion einen Fokuswurf ablegen, um diese Fähigkeit zu aktivieren. Verliert er die Konzentration, fährt sie herunter und muss neu aktiviert werden (siehe S. 42)."]], "s": ["SUP"], "p": 53}, {"n": "Blenden", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Helle oder flackernde Lichter, ein Strahl aus Sand oder feiner Materie, Gedankenkontrolle", "b": ["Verschleiern hüllt ein Gebiet in Dunkelheit, aber diese hinterhältige Kraft trifft direkt ein Ziel innerhalb von 12“ Reichweite und macht es kurzzeitig blind.", "Einen Gegner zu blenden ist ein Fokuswurf gegen die Konstitution des Ziels. Bei Erfolg erleidet das Opfer –2 auf alle Aktionen, die Sehen erfordern, oder –4 mit einer Steigerung.", "Das Opfer versucht automatisch, die Wirkung mit einem Konstitutionswurf als freie Aktion am Ende jedes seiner folgenden Züge abzuschütteln. Erfolg entfernt 2 Punkte Abzüge, eine Steigerung beseitigt die Wirkung ganz. Sobald ein Opfer sich befreit hat, kann es in derselben Begegnung nicht noch einmal durch Blenden beeinflusst werden (auch nicht von einer anderen Quelle)."], "m": [["FLÄCHENEFFEKT", "+2/+3", "Für +2 Punkte betrifft die Kraft alle in einer Mittleren Flächenschablone. Für +3 Punkte wird das Wirkungsgebiet auf eine Große Flächenschablone erhöht."], ["STARK", "+1", "Der Konstitutionswurf zum Abschütteln der Wirkung wird mit –2 abgelegt."]], "s": ["SUP"], "p": 53}, {"n": "Eigenschaft erhöhen/senken", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Karma, fließende Energie, Führungsstärke, chemische Verbesserungen, Nanotechnik, mentale Führung oder Manipulation", "b": ["Der Superheld kann vorübergehend eine Eigenschaft von sich selbst oder einem Verbündeten verbessern oder die eines Feindes senken!", "Wähle beim Erwerb dieser Kraft eine beliebige Fertigkeit oder Eigenschaft (Eigenschaft). Als Aktion wählt der Superheld ein Ziel innerhalb von 12“ (24 Metern) und legt einen Fokuswurf ab. Bei Erfolg erhöht oder senkt er die Eigenschaft des Ziels um einen Würfeltyp (zwei mit einer Steigerung, bis zu einem Minimum von W4 beim Senken). Das hält bis zum Ende des nächsten Zugs des Ziels.", "Die Eigenschaft eines Charakters darf nie um mehr als zwei Würfeltypen erhöht oder gesenkt werden, selbst wenn er von mehreren Charakteren mit Eigenschaft erhöhen/senken anvisiert wird.", "Abgeleitete Werte: Erhöhte Eigenschaften wie Konstitution oder Kämpfen beeinflussen auch abgeleitete Werte (wie Robustheit und Parade).", "Eine übliche Einschränkung für einen Punkt ist, Eigenschaften nur erhöhen oder nur senken zu können; oder den Modifikator Beliebige Eigenschaft unten zu nehmen, aber nur Fertigkeiten oder nur Attribute zu beeinflussen. Für eine Einschränkung von zwei Punkten könnten beide gelten – ein Charakter könnte nur Attribute erhöhen oder nur Fertigkeiten senken."], "m": [["ZUSÄTZLICHE EMPFÄNGER", "+1", "Der Superheld kann für je einen Super-Machtpunkt ein zusätzliches Ziel beeinflussen. Dieser Modifikator kann mehr als einmal genommen werden. Erhöhen und Senken sind zwei getrennte Anwendungen der Kraft und müssen als getrennte Aktionen erfolgen."], ["BELIEBIGE EIGENSCHAFT", "+2", "Der Charakter kann jedes Attribut oder jede Fertigkeit „spontan“ beeinflussen. Hat sie den Modifikator Zusätzliche Empfänger, kann sie für jedes Ziel eine andere Eigenschaft beeinflussen."], ["ABSAUGEN", "+2", "Beim Senken der Eigenschaft eines Feindes erhöht der Superheld seine eigene identische Eigenschaft um einen Würfeltyp bis zum Ende ihres nächsten Zugs. Sie darf weiterhin eine einzelne Eigenschaft nicht um mehr als zwei Würfeltypen erhöhen, könnte aber mehrere Eigenschaften erhöhen, wenn sie den Modifikator Zusätzliche Empfänger hat."], ["MACHT", "+2", "Ein verstärkter Verbündeter erhält einmal pro Runde einen kostenlosen Wiederholungswurf, oder einmal pro Aktion mit einer Steigerung beim Fokuswurf."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss seine Ziele berühren, um ihre Eigenschaft zu erhöhen oder zu senken. Das darf nicht mit dem Modifikator Reichweite kombiniert werden (siehe S. 45)."]], "s": ["SUP"], "p": 53, "k": [{"h": "Eigenschaft erhöhen außerhalb des Kampfes", "b": ["Eigenschaft erhöhen ist ein sehr kurzer Schub aus Inspiration, Stärke oder anderem Nutzen, daher hilft es nicht bei langen Aufgaben wie dem Recherchieren von Informationen, dem Schleichen über ein Feld usw. Nach Ermessen der SL kann ein Superheld mit dieser Kraft sie jedoch einen Wurf beeinflussen lassen, der zu einer längeren Aufgabe gehört, und im Grunde nach den kritischen Momenten Ausschau halten, die den Aufwand ausmachen, und im richtigen Moment verstärken."]}]}, {"n": "Rundfunk", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Hightech-Geräte, Maschinenmenschen, große Klammern", "b": ["Als Aktion kann der Held jedes Radio-, Fernseh- oder Internetsignal sehen und hören, solange er sich innerhalb von zehn Meilen von einem Anschluss (etwa einem anderen Radio, Mobilfunkmast usw.) befindet. Er kann sich auch mit einem beliebigen elektronischen Wiedergabegerät ohne physische Verbindung mit dem Netzwerk verbinden.", "Sich mit einer verschlüsselten Übertragung zu verbinden erfordert einen Fokuswurf mit –2 (–4 oder höher bei militärischer Verschlüsselung). Misslingt er, kann er dieses Signal nicht erneut versuchen, bis er seinen Fokus durch Aufstieg erhöht."], "m": [["KANALSURFER", "+1", "Der Charakter kann so viele Kanäle gleichzeitig anzapfen, wie er erkennen kann."], ["MANIPULATION", "+1/+3", "Für +1 Punkt kann der Charakter zuvor aufgezeichnetes Audio oder Video senden, solange auf die Aufzeichnung irgendwo zugegriffen werden kann. Für +3 Punkte kann er Ausschnitte aus früheren Audio-/Videoquellen zu völlig neuem Video zusammenschneiden. „Deep Fakes“ sind für Experten erkennbar, da sie manipulierte Daten enthalten, halten aber der Prüfung der meisten ungeschulten Betrachter stand."], ["REICHWEITE", "+1/+2", "Der Held kann Netzwerke bis zu 100 Meilen entfernt anzapfen, oder 1000 Meilen für +2 Punkte."]], "s": ["SUP"], "p": 54}, {"n": "Graben", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Erdkontrolle, ein Körper aus Sand oder Dreck, Charaktere nach dem Vorbild grabender Tiere", "b": ["Ein Superheld mit dieser Kraft kann unter der Erde tunneln, um ihre Feinde zu überraschen und aus dem Hinterhalt anzugreifen! Ein grabender Held kann als Aktion tunneln und sich pro Runde bis zur Hälfte ihrer üblichen Bewegungsweite unter relativ weicher Erde bewegen. Festes Gestein, Metall, Ziegel und Mörtel und andere harte Substanzen sowie Wasser stoppen den Tunnelbauer sofort.", "Tod von unten: Grabende Charaktere können unter ihren Gegnern hervorbrechen, um sie zu überraschen. War das Ziel sich der Anwesenheit des Gräbers nicht bewusst, legt sie einen vergleichenden Heimlichkeitswurf gegen die Wahrnehmung des Opfers ab. Gewinnt der Gräber, ist das Ziel nur ihr gegenüber Verwundbar. Mit einer Steigerung erhält der Gräber den Vorteil. Ziele in Bereitschaft können versuchen, den Angriff zu unterbrechen, bevor er stattfindet.", "Gräber können einen Feind meist nicht überraschen, sobald ihre Anwesenheit bekannt ist, können aber weiterhin zum Schutz und zur Mobilität graben."], "m": [["BLOCKBUSTER", "+1", "Der Gräber kann eine Aktion nutzen, um harte Substanzen zu durchbrechen, die seine Bewegung normalerweise blockieren würden. Er würfelt seinen Angriffsschaden, und übersteigt er die Härte des Hindernisses, bricht er pro Runde 1“ (2 Meter) der Substanz durch."], ["BEWEGUNGSWEITE", "+1", "Die Grabbewegungsweite des Gräbers entspricht seiner vollen normalen Laufbewegungsweite (statt der Hälfte)."], ["TUNNELBAUER", "+1", "Der Gräber kann einen Tunnel hinter sich lassen, damit andere folgen können. Die Größe ist relativ zum Gräber, aber im Allgemeinen groß genug, dass Menschen gebückt hindurchlaufen können."]], "s": ["SUP"], "p": 54}, {"n": "Chamäleon", "r": 5, "mp": "3", "rw": "", "wd": "", "au": "Formbare Gestalt, Hightech-Verkleidungsausrüstung", "b": ["Diese Kraft erlaubt es dem Charakter, das Aussehen eines anderen Wesens oder Tiers anzunehmen, das er gesehen oder studiert hat. Der Charakter kann niemanden nachahmen, der mehr als zwei Größenstufen von ihm abweicht.", "Das Aussehen zu ändern erfordert eine Aktion und einen Fokuswurf.", "Die Details sind so gut wie der Superheld sie beobachten kann, aber er kann keine Fingerabdrücke, Netzhautscans nachbilden oder elektronische Stimmscanner täuschen. Er kann die Stimme des Ziels mit Darbietung imitieren, wenn er sie gehört hat (oder den Modifikator Biometrie unten nehmen).", "Jemand, der mit dem Original-Ziel vertraut und dem Chamäleon gegenüber misstrauisch ist, erhält einmal pro Begegnung einen Wahrnehmungswurf, vergleichend mit der Darbietung des Supers, um den Schwindel zu entdecken. Ein misstrauischer Charakter kann weiterhin Fragen stellen oder den Betrüger anderweitig entlarven, aber der Wurf, es zu durchschauen, darf nur einmal pro Begegnung versucht werden.", "Chamäleons erhalten nicht die Fähigkeiten oder Eigenschaften eines Ziels – nur sein Aussehen. Ein Chamäleon mit Nachahmer kann aber auch die Superkräfte eines Ziels übernehmen, was es sehr überzeugend macht!", "Herunterfahren: Chamäleon endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42."], "m": [["LEBLOSES OBJEKT", "+2", "Der Charakter kann die Gestalt lebloser Objekte annehmen. Die angenommene Form darf nicht mehr als zwei von der Größe des Charakters abweichen. Gibt es Misstrauen gegenüber einem Objekt, gibt es keinen vergleichenden Wurf, nur einen einfachen Wahrnehmungswurf mit –2, einmal pro Begegnung, um die Fälschung zu erkennen."], ["BIOMETRIE", "+2", "Das Chamäleon kann Stimme, Fingerabdrücke, Netzhäute und andere Identifikationsmerkmale eines Ziels nachbilden. Wahrnehmungswürfe zum Entdecken der Täuschung werden mit –2 abgelegt."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss ein Ziel berühren, um es zu kopieren. Siehe S. 45 für weitere Informationen."]], "s": ["SUP"], "p": 55}, {"n": "Konstrukt", "r": 5, "mp": "8", "rw": "", "wd": "", "au": "Ein Roboter, Cyborg, eine Masse aus Drähten", "b": ["Der Charakter ist ein lebender Automat, Cyborg, Roboter, eine Statue oder ein Android. Die meisten sind Produkte außerirdischer Technologie, verrückter Wissenschaft oder des Übernatürlichen.", "Konstrukte addieren +2 beim Versuch, sich von Angeschlagen zu erholen, ignorieren einen Punkt Wundabzüge, atmen und essen nicht, sind immun gegen biologische Krankheiten und Gifte, verbluten nicht, und Wunden werden mit Reparieren statt mit Heilen entfernt. Jeder Reparierenwurf braucht eine Stunde Arbeit pro aktueller Wundstufe, ist aber nicht auf die übliche „Goldene Stunde“ für Heilung in Savage Worlds beschränkt.", "Nimmt ein Konstrukt die Kraft Regeneration, hat es Nanobots, Selbstreparatursysteme oder andere Systeme, die ihm natürliche Heilungswürfe mit seiner Konstitution erlauben. Er profitiert aber nicht von Erste-Hilfe-Kästen oder typischer medizinischer Versorgung.", "Konstrukte müssen einige Zeit im Ruhezustand, in Ruhe oder beim Zurücksetzen verbringen, es sei denn, sie nehmen die Kraft Schläft nicht."], "m": [["ABHÄNGIGKEIT", "–2", "Das Konstrukt muss jeden Tag eine Stunde an einem geeigneten Ort aufladen: eine Steckdose für einen Roboter, einen magischen Schrein für eine Statue, in Wasser und Sonnenlicht für eine Pflanze usw. Ohne die nötige Auffüllung erleidet das Konstrukt jeden Tag eine Stufe Erschöpfung. Wird es Kampfunfähig, bleibt es inert, bis es irgendwie aufgeladen wird."]], "s": ["SUP"], "p": 55}, {"n": "Nachahmer", "r": 5, "mp": "1/Stufe", "rw": "", "wd": "", "au": "Natürliche, anpassungsfähige Physiologie, schneller Lerner, Wunderkind", "b": ["Nachahmer erlaubt es dem Charakter, die Superkräfte anderer Helden und Schurken nachzuahmen. Kräfte zu kopieren ist eine Aktion. Ist das Ziel willig, ist kein Wurf nötig. Wenn nicht, lässt ein erfolgreicher Fokuswurf ein Ziel innerhalb von 6“ einen Willenskraftwurf ablegen (mit –2 bei einer Steigerung auf den Fokuswurf). Misslingt dem Opfer der Wurf, kann der Nachahmer seine Kräfte frei nachahmen.", "Der maximale Punktwert der Kräfte, die der Held kopieren kann, entspricht ihren Stufen in Nachahmer. Sie kann kopierte Kräfte innerhalb dieses Limits nach Belieben mischen, aus einer Quelle oder vielen.", "Alles oder nichts: Jede kopierte Kraft muss in allen Punkten identisch mit dem Original sein, einschließlich aller Modifikatoren und Ausprägungen. Das heißt, sie muss eine Kraft ganz nehmen können, nicht nur einen Teil, damit es gelingt.", "Wirkungsdauer: Kopierte Kräfte halten eine Stunde oder bis sie freigegeben werden (freie Aktion).", "Keine Geräte oder Magie: Nachahmer kann keine Kräfte mit dem Modifikator Gerät nachahmen – es repliziert keine Maschinen und Gizmos. Es kann auch keine Kräfte mit dem Machttyp Magie replizieren, da solche Macht typischerweise aus äußeren Quellen fließt, die sich weigern können, sie zu gewähren, wenn die Kraft gestohlen wird.", "Herunterfahren: Nachahmer endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42."], "m": [["ARKAN", "+2", "Der Nachahmer hat gelernt, magische Energien zu kanalisieren oder jeden Schiedsrichter zu überlisten, der sie der sterblichen Sphäre gewährt. Sie kann Kräfte mit dem Machttyp Magie kopieren."], ["GERÄTE", "+2", "Der Held hat ein konfigurierbares Gerät, kann eine Kopie eines mächtigen Gegenstands aus dünner Luft oder nahen Komponenten herbeirufen oder ist vielleicht selbst ein Konstrukt. Aus welchem Grund auch immer, sie kann Kräfte mit dem Modifikator Gerät kopieren."], ["WIRKUNGSDAUER", "+3", "Die Kraft bleibt erhalten, bis eine neue kopiert wird (statt der üblichen Wirkungsdauer von einer Stunde)."], ["ÜBERGENAU", "–2", "Zusätzlich zu kopierten Kräften erhält der Charakter auch die Handicaps Umweltschwäche, Machtneutralisierung oder Verwundbarkeit des Ziels, solange er seine Kräfte behält."], ["TEILKRAFT", "+2", "Der Nachahmer kann einige Stufen der Kraft eines Ziels nehmen, ohne alle nehmen zu müssen. Er könnte zum Beispiel fünf Punkte der Stärke eines Feindes kopieren, der tatsächlich 10 Stufen Superstärke hat."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit dem Modifikator Reichweite kombiniert werden (siehe S. 45)."]], "s": ["SUP"], "p": 56}, {"n": "Schadensfeld", "r": 5, "mp": "Speziell", "rw": "", "wd": "", "au": "Feuriger Schein, Strahlung, Kälte, Stacheln, Ranken aus Dunkelheit oder Chaos, Giftstoffe, ein wirbelnder Kreis aus Klingen", "b": ["Diese tödliche Kraft erzeugt eine gefährliche Aura oder ein Feld eines beliebigen Machttyps um den Charakter, um nahe Feinde zu verbrennen, zu sprengen oder mit einem Hagel zu überziehen.", "Das Feld zu aktivieren ist eine Aktion, und es bleibt an, bis der Superheld es beendet. Am Ende des Zugs des Supers muss jeder angrenzende Charakter einen Ausweichen-Wurf ablegen oder erleidet den unten genannten Schaden.", "Herunterfahren: Schadensfeld endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42."], "m": [["PANZERBRECHEND", "+1", "Jeder Punkt in diesem Modifikator gibt dem Schadensfeld +2 DB, bis zu einem Maximum von +10 DB."], ["FLÄCHENEFFEKT", "+2/+4", "Für 2 Punkte kann die Kraft auf eine Mittlere Flächenschablone ausgedehnt werden, oder für vier Punkte auf eine Große Flächenschablone."], ["TÖDLICH", "–1", "Der Angriff ist von Natur aus tödlich. Er kann diese Kraft nicht für Nicht-tödliche Angriffe nutzen (siehe Savage Worlds)."], ["DAUERHAFT", "–2", "Der Charakter kann sein Schadensfeld nicht abschalten, auch wenn er es will! Das verhindert, dass es heruntergefahren wird."]], "s": ["SUP"], "p": 56, "tab": {"c": ["Schaden", "Kosten"], "r": [["2W6", "3"], ["3W6", "5"], ["4W6", "10"]], "nach": 2}}, {"n": "Scharfschütze", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Extremes Training, geborener Schütze, integrierter Kampfcomputer, ehemaliger Olympionike, Gun-Fu", "b": ["Der Charakter verursacht +W6 Schaden mit Schusswaffen (einschließlich Pulswaffen und Ähnlichem), Bögen oder Armbrüsten.", "Scharfschütze ist nicht kumulativ mit Superkräften wie Fernkampfangriff (unabhängig von der Ausprägung) und gilt nicht für sie, ebenso wenig für Sprengstoffe wie Granaten, Flammenwerfer, Mannschafts- oder Fahrzeugwaffen oder jede Art von Flächenwaffe."], "m": [["TÖDLICH", "+1", "Der Schaden des Helden steigt auf W10."]], "s": ["SUP"], "p": 57}, {"n": "Verfall", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Rost, Korrosion, Fäulnis, Säure", "b": ["Diese hinterhältige Kraft lässt Objekte und Personen verrotten und zerstört sie, die den Zorn ihres Anwenders erregen. Ein erfolgreicher Fokuswurf lässt ein Ziel innerhalb von 6“ einen Konstitutionswurf ablegen (mit –2 bei einer Steigerung auf den Fokuswurf). Misslingt dem Opfer der Wurf, erleidet es eine Wunde.", "Verfall kann als Aktion auch ein Sehr Kleines Objekt mit Rüstung oder Härte 12 oder weniger zerstören, oder einen ähnlich großen Teil eines größeren Objekts. Er hat keine Wirkung auf Objekte mit Rüstung oder Härte 13 oder höher (aber siehe den Modifikator Stark unten)."], "m": [["FLÄCHENEFFEKT", "+2/+4", "Für 2 Punkte kann der Angriff alle und alles in einer Mittleren Flächenschablone betreffen. Für 4 Punkte kann der Held entweder eine Mittlere oder eine Große Flächenschablone verwenden. Ziele im Wirkungsgebiet widerstehen einzeln."], ["MIDAS-BERÜHRUNG", "–2", "Der Charakter kann seine Kraft nicht abschalten. Alles, was er (außer sich selbst) mit bloßen Händen berührt, beginnt zu verfallen."], ["STARK", "+2", "Konstitutionswürfe werden mit –2 abgelegt, und Verfall wirkt auf Objekte mit Rüstung oder Härte bis zu 20."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit den Modifikatoren Reichweite oder Flächeneffekt kombiniert werden. Siehe S. 45 für weitere Informationen."]], "s": ["SUP"], "p": 57}, {"n": "Ausweichen", "r": 5, "mp": "1–5", "rw": "", "wd": "", "au": "Akrobatik, wirbelnde Winde, mystische Schilde, schnelle Reaktionen, „sechster Sinn“", "b": ["Der Held ist beweglich, vorausahnend oder einfach sehr gut im Nutzen von Deckung. Direkte Fernkampfangriffe (Schießen und Athletik (Werfen)) ziehen für jeden Punkt in dieser Kraft 1 ab, bis zu einem Maximum von –5 für 5 Super-Machtpunkte.", "Ausweichen ist kumulativ mit allen anderen Fähigkeiten, die von Fernkampfangriffen abziehen, bis zu einer maximalen Strafe von –10. Es bietet keinen Schutz vor Flächenangriffen."], "m": [["VERTEIDIGER", "+2/+4", "Der Schutz des Helden erstreckt sich auf alle Verbündeten in einer Mittleren Flächenschablone, zentriert auf sie selbst, für +2 Punkte, oder in einer Großen Flächenschablone für +4 Punkte."], ["ABLENKEN", "+2", "Einmal pro Zug, wenn der Held von einem Fernkampfangriff verfehlt wird, kann er versuchen, ihn mit einem Fokuswurf abzulenken. Ziehe 2 vom Wurf gegen Schusswaffen ab und 4 gegen Energiewaffen. Bei Erfolg wird der Angriff auf den ursprünglichen Angreifer umgeleitet. Mit einer Steigerung kann der Held ihn auf ein beliebiges anderes verfügbares Ziel umleiten. In beiden Fällen trifft der Angriff automatisch, kann aber nie mit einer Steigerung treffen. Flächenangriffe können im Allgemeinen nicht abgelenkt werden, aber die SL kann es erlauben, wenn der Angriff eine Granate oder ein ähnliches Objekt ist, das umgeleitet werden könnte."], ["AKTIVIERUNG ERFORDERLICH", "–1", "Der Held muss als Aktion einen Fokuswurf ablegen, um diese Fähigkeit zu aktivieren. Verliert er die Konzentration, fährt sie herunter und muss neu aktiviert werden (siehe S. 42)."]], "s": ["SUP"], "p": 57}, {"n": "Atmet nicht", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Außerirdische Lebensformen, Elementare, Unsterbliche", "b": ["Der Superheld kann bis zu 15 Minuten die Luft anhalten."], "m": [["EXTREM", "+1", "Der Superheld atmet überhaupt nicht. Er ist von eingeatmeten Giftstoffen nicht betroffen, kann nicht ertrinken und erstickt nicht im Vakuum."]], "s": ["SUP"], "p": 58}, {"n": "Isst nicht", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Unsterbliche, dimensionale Wesen, Roboter", "b": ["Die Heldin kommt mit sehr wenig Nahrung aus. Sie kann doppelt so lange wie ein normaler Mensch ohne Nahrung auskommen (siehe Hunger unter Gefahren in Savage Worlds).", "Hunger bedeutet nicht unbedingt menschliche Nahrung. Ein Roboter, der gelegentlich Energie braucht, oder ein Zombie, der gelegentlich Fleisch braucht, „isst“ trotzdem."], "m": [["EXTREM", "+1", "Der Superheld braucht nie Nahrung oder Wasser und ist völlig immun gegen die Wirkungen von Hunger und Durst."]], "s": ["SUP"], "p": 58}, {"n": "Schläft nicht", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Raubtiersinne, fortgeschrittene Wesen, Roboter", "b": ["Das Wesen braucht nur die Hälfte des normalen Schlafs oder der „Aufladezeit“ eines Menschen."], "m": [["UNERMÜDLICH", "+1", "Der Charakter muss nie schlafen."]], "s": ["SUP"], "p": 58}, {"n": "Duplizierung", "r": 5, "mp": "4/Stufe", "rw": "", "wd": "", "au": "Dimensionaler Zwilling, Homunkulus, Illusionen, zukünftige Selbste", "b": ["Duplizierung erlaubt es einem Helden, mit einem Fokuswurf Kopien seiner selbst zu erschaffen. Jede Stufe in der Kraft erschafft einen „Klon“, der alle Kräfte des Erschaffers hat, außer Duplizierung und bestimmten anderen unten aufgeführten Kräften.", "Die erschaffenen Kopien sind Nebenfiguren und stehen vollständig unter der Kontrolle des Erschaffers.", "Duplikate entstehen im Abbild des Erschaffers und tragen, was er gerade anhat. Sie bringen keine andere Ausrüstung mit, außer mit dem Modifikator Ausgerüstet unten.", "Jedes oder alle Duplikate können vom Erschaffer als begrenzte freie Aktion aufgelöst werden. Das geschieht oft zu ihrem Schutz, wenn der Erschaffer weiß, dass sie in extremer Gefahr sind, angesichts der Regeln zur Kampfunfähigkeit unten.", "Kampfunfähigkeit: Wird ein Duplikat Kampfunfähig, kann es eine Stunde lang nicht neu beschworen werden. Alle Duplikate verschwinden sofort, wenn das Original Kampfunfähig wird.", "Erkennungszeichen: Duplikate sind immer leicht „daneben“. Vielleicht schwitzen sie nicht, werfen keine Schatten oder haben einen anderen „Defekt“. Gegner können einen Wahrnehmungswurf mit –2 gegen ein Ziel versuchen, um festzustellen, ob es das Original oder eine Kopie ist. Das ist eine freie Aktion, die jeder Feind einmal pro Zug versuchen kann (würfle einen Gruppenwurf für identische Nebenfiguren).", "Herunterfahren: Duplizierung endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42."], "m": [["AUSGERÜSTET", "+2", "Die Duplikate haben alle normalen Gegenstände (Entscheidung der SL), die das Original bei ihrer Erschaffung hat. Hat der Held eine Kraft als Gerät, eine Spezialwaffe oder einen seltenen oder einzigartigen Gegenstand, kann der Klon eine einfache Version davon haben. Hat der Held zum Beispiel ein verzaubertes Langschwert, kann der Klon ein normales Langschwert ohne die nicht standardmäßigen Eigenschaften der magischen Waffe haben."], ["AN DER LEINE", "–2", "Die Duplikate enden, wenn sie sich weiter als 12“ (24 Meter) vom Original entfernen."], ["KEIN ERKENNUNGSZEICHEN", "+1", "Duplikate sehen dem Original ähnlicher. Wahrnehmungswürfe, um ein Duplikat vom Original zu unterscheiden, werden mit –4 abgelegt."], ["BEFÖRDERUNG", "+2", "Wird der ursprüngliche Charakter Kampfunfähig, während ein Duplikat überlebt, wird ein Duplikat der neue Wildcard-„Elternteil“, statt zu verschwinden."]], "s": ["SUP"], "p": 58}, {"n": "Erdbeben", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Erschütterungen, Schallvibrationen, Hightech-„Stampfer“", "b": ["Der Charakter lässt die Erde beben und schütteln und wirft alle innerhalb der seismischen Welle aus dem Gleichgewicht. Ein Beben zu erzeugen ist eine Aktion, und seine Wirkungen halten bis zum Beginn des nächsten Zugs des Charakters.", "Der Erdschüttler darf die Form des Bebens wählen: eine Kegelschablone, die vom Helden ausgeht; eine Große Flächenschablone bis zu 24“ (48 Meter) entfernt; oder eine gerade Linie von 2“ (vier Metern) Breite und 12“ (24 Metern) Länge, die vom Superhelden ausgeht.", "Alle im Wirkungsgebiet oder die es betreten, bevor es abläuft, müssen Ausweichen oder werden Angeschlagen. Wer einen Kritischen Fehlschlag erleidet, nimmt 3W6 Schaden durch zerquetschenden Fels oder Erde, herabfallende Trümmer usw.", "Verwerfungslinien: Wird Erdbeben im Herzen einer bestehenden Verwerfungslinie oder tief in der Erde an einer tektonischen Platte eingesetzt, können die Ergebnisse katastrophal sein. Würfle dabei einen W6 (nicht öfter als einmal pro Spielwoche). Bei einer 6 wird ein echtes Erdbeben ausgelöst. Die Größe des Bebens und seine Auswirkungen hängen von der Verwerfungslinie ab und sollten erzählerisch behandelt werden, verursachen aber erhebliche bis massive Schäden in einem großen Gebiet.", "Vorbeugung: Ein Held mit dieser Kraft kann auch ein Erdbeben stoppen! Das ist ein einfacher Fokuswurf für ein kleines Beben oder eines, das durch diese Kraft verursacht wurde. Ein großes Erdbeben zu stoppen ist eine Herausfordernde Dramatische Aufgabe mit mindestens –2 für ein bedeutendes und –4 für ein großes Beben."], "m": [["STARK", "+2", "Wer versucht, einem Beben auszuweichen, muss 2 von seinen Würfen abziehen. Gebäude erleiden erheblichen Schaden und werden schließlich durchbrochen oder können sogar einstürzen, wenn der Superheld den Angriff aufrechterhält."]], "s": ["SUP"], "p": 59}, {"n": "Energiekontrolle", "r": 5, "mp": "5", "rw": "", "wd": "", "au": "Wesen aus reiner Energie, Elementarmanipulation, magische Bindung, wissenschaftliche Gadgets", "b": ["Energiekontrolle erlaubt es einem Superhelden, als Aktion einen Energie-Machttyp innerhalb eines einzelnen „Energiefelds“ zu manipulieren. Das Feld ist eine Kugel von der Größe einer Mittleren Flächenschablone, die bis zu 12“ (24 Meter) entfernt erscheint.", "Der Kontrolleur kann das Feld in ihrem Zug als begrenzte freie Aktion um bis zu 12“ (24 Meter) pro Zug bewegen, solange es in Sichtweite bleibt.", "Das Feld hält, solange der Superheld es aufrechterhält (d. h. nicht Kampfunfähig oder heruntergefahren ist). Sobald die Kugel erzeugt ist, kann sie als freie Aktion kleinere Effekte aktivieren, die zum Machttyp passen – eine kühle Brise heraufbeschwören, ein Feuer entzünden oder löschen, Licht erzeugen usw.", "Der Kontrolleur kann als begrenzte freie Aktion einen der folgenden Effekte aktivieren; einen Effekt zu beenden ist eine freie Aktion. Der Kontrolleur ist gegen seine eigenen Effekte immer immun.", "• Schaden: Jeder im Feld erleidet am Ende des Zugs des Supers 2W6 Schaden durch Flammen, Schallstöße, zeitliche Atrophie oder einen anderen schädlichen Effekt, der zum Machttyp passt.", "• Dämpfen: Der Kontrolleur bietet jedem im Feld Umweltresistenz (siehe S. 61) gegen ihren gewählten Machttyp.", "• Verdunkeln: Der Bereich in der Kugel wird durch Energie verdunkelt oder verschleiert und taucht alles darin in Dämmerlicht (siehe Beleuchtung in Savage Worlds).", "• Ablenken: Jeder in der Schablone ist am Ende des Zugs des Supers Abgelenkt. Entferne den Zustand am Ende ihres Zugs wie üblich, wenn sie nicht mehr in der Schablone sind.", "Andere Fähigkeiten: Andere „Energiekontroll“-Fähigkeiten wie Fernkampfangriffe, Verstricken, Schadensfeld, Kraftfeld, Verschleiern und Ähnliche können separat genommen werden und denselben Machttyp wie Energiekontrolle nutzen, um größere Meisterschaft darzustellen.", "Herunterfahren: Energiekontrolle endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42."], "m": [["ZUSÄTZLICHER MACHTTYP", "+1", "Der Held kann einen zusätzlichen Energie-Machttyp kontrollieren. Das kann mehr als einmal genommen werden, wobei jedes Mal ein anderer Energie-Machttyp gewählt wird."], ["FLÄCHENEFFEKT", "+2", "Der Kontrolleur kann ihr Energiefeld auf die Größe einer Großen Flächenschablone ausdehnen."], ["MACHT", "+5", "Die Energie des Charakters hat größere Wirkung. Der Schaden steigt auf 4W6, Dämpfen gibt Verbündeten Immunität gegen den Machttyp, solange sie im Feld sind, Verdunkeln erzeugt Dunkelheit, und Ablenken macht Feinde Abgelenkt und Verwundbar."], ["MATERIAL ERFORDERLICH", "–1/–2", "Der Charakter kann keine Energie erzeugen, sondern muss nutzen, was bereits vorhanden ist. Ohne solche Energie kann er seine Kraft nicht einsetzen. Das ist einen Punkt wert, wenn die Energie im Setting recht häufig ist (Licht, Hitze), oder 2 Punkte, wenn sie selten ist (Strahlung, Zeitliches)."]], "s": ["SUP"], "p": 59}, {"n": "Verstricken", "r": 5, "mp": "3", "rw": "", "wd": "", "au": "Klebebombe, Ranken, elektrisches Netz, Handschellen, Spinnennetze, zauberische Fesseln", "b": ["Verstricken verfängt Feinde in Bänder aus Energie, Seilen, Ranken, Netzen oder anderen Verwicklungen. Zur Aktivierung visiert der Held einen Feind innerhalb von 12“ (24 Metern) an und legt einen Fokuswurf ab, der vergleichend zur Athletik des Opfers ist. Gewinnt der Angreifer, ist das Opfer Verstrickt. Gewinnt der Angreifer mit einer Steigerung, ist das Opfer Gebunden.", "Die Fesseln haben Härte 8, und ein Gebundenes oder Verstricktes Opfer kann wie üblich in seinem nächsten Zug versuchen, sich zu befreien. Siehe Gebunden und Verstrickt in Savage Worlds für weitere Details."], "m": [["FLÄCHENEFFEKT", "+2/+4", "Für 2 Punkte kann der Angriff alle in einer Mittleren Flächenschablone betreffen. Für 4 Punkte kann der Held entweder eine Mittlere oder eine Große Flächenschablone verwenden."], ["TÖDLICH", "+2/+4", "Der Superheld kann seine Verstrickung zusammenziehen, brennen, schneiden oder anderweitig jene schädigen, die in ihrem Griff gefangen sind. Als Aktion kann der Superheld jedem, den er Gebunden oder Verstrickt hat, 2W6 Schaden zufügen. Für +4 Punkte verursacht sie 3W6 Schaden."], ["MATERIAL ERFORDERLICH", "–1/–2", "Der Charakter kann keine Materie erzeugen und braucht eine Quelle davon in Reichweite, um seine Kraft zu nutzen. Das ist ein Punkt Rabatt, wenn die Materie im Setting recht häufig ist (Ranken, Kabel), oder 2 Punkte, wenn sie selten ist (Ranken auf einem Raumschiff, Skeletthände von einem Friedhof)."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit den Modifikatoren Reichweite oder Flächeneffekt kombiniert werden. Siehe S. 45 für weitere Informationen."], ["STARK", "+2", "Das Fesselmaterial ist sehr stark. Würfe zum Befreien werden mit –2 abgelegt, und die Härte steigt auf 12."]], "s": ["SUP"], "p": 60}, {"n": "Umweltresistenz", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Energie- oder Materiekontrolleure, veränderte Formen, außerirdische Physiologie", "b": ["Dein Held ist gegen einen bestimmten Machttyp resistent. Sie ignoriert dessen Hintergrundeffekte, verringert Schaden dieses Machttyps um 4 und addiert +4, wenn sie Effekten mit der Ausprägung dieses Machttyps widersteht."], "m": [["ZUSÄTZLICHER MACHTTYP", "+1", "Die Umweltresistenz des Helden gilt für einen zusätzlichen Machttyp. Das kann mehr als einmal genommen werden, wobei jedes Mal ein neuer Machttyp gewählt wird."], ["FLÄCHENEFFEKT", "+2/+4", "Für 2 Punkte kann Umweltresistenz für alle in einer Mittleren Flächenschablone gelten, zentriert auf den Superhelden. Für 4 Punkte kann der Charakter seinen Schutz auf eine Große Flächenschablone ausdehnen."], ["IMMUNITÄT", "+2", "Der Held ist immun gegen Schaden und Wirkungen ihrer resistenten Machttypen. Nach Ermessen der SL kann selbst Immunität unter extremsten Umständen versagen. Mehr als einige Minuten in einem Atomreaktor für Strahlungsresistenz oder auf der Oberfläche der Sonne für Feuerresistenz zu verbringen, ist selbst für diesen Modifikator zu viel."], ["AKTIVIERUNG ERFORDERLICH", "–1", "Der Held muss als Aktion einen Fokuswurf ablegen, um diese Fähigkeit zu aktivieren. Verliert er die Konzentration, fährt sie herunter und muss neu aktiviert werden (siehe S. 42)."]], "s": ["SUP"], "p": 61}, {"n": "Explodieren", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Bomben, radioaktive Form, sich sammelnde Energie", "b": ["Der Superheld hat die ungewöhnliche Fähigkeit zu explodieren! Sein Körper überlebt die Detonation irgendwie unversehrt oder setzt sich danach neu zusammen.", "Explodieren ist eine begrenzte Aktion. Ein erfolgreicher Fokuswurf erzeugt eine Explosion von der Größe einer Großen Flächenschablone, zentriert auf den Helden. Jeder in der Schablone muss Ausweichen (mit –2 bei einer Steigerung auf den Fokuswurf) oder erleidet 3W10 Schaden (4W10 mit einer Steigerung).", "Ein Held ist nach dem Explodieren automatisch Angeschlagen."], "m": [["GROSSER KNALL", "+2", "Die Explosion kann 5W10 Schaden verursachen, aber der Held ist danach Betäubt."], ["SICHERUNG", "+1", "Der Charakter explodiert automatisch, wenn er Kampfunfähig wird."], ["VORÜBERGEHENDE AUFLÖSUNG", "–1", "Der Körper des Supers löst sich bei der Explosion auf! Sobald er sich von Angeschlagen (oder Betäubt mit Großem Knall) erholt, muss er einen Fokuswurf ablegen, um sich neu zu formen. Der Held kann während der Auflösung nicht anvisiert werden oder mit ihm kommuniziert werden."]], "s": ["SUP"], "p": 62}, {"n": "Zusätzliche Gliedmaßen", "r": 5, "mp": "2/Stufe", "rw": "", "wd": "", "au": "Tentakel, Schwanz, Roboterarm, außerdimensionale Manifestation", "b": ["Dein Charakter hat jedes Mal, wenn dies genommen wird, ein zusätzliches Greifglied oder Gliederpaar. Diese wirken wie Hände und können Waffen oder andere Ausrüstung halten.", "Zusätzliche Gliedmaßen gewähren dem Charakter keine zusätzlichen Aktionen – nutze dafür die Kraft Zusätzliche Aktionen. Die Gliedmaßen können aber für andauernde Aktionen genutzt werden, etwa eine Taschenlampe halten oder einen Feind packen, sodass andere Gliedmaßen für andere Dinge frei bleiben.", "Gang Up: Jedes Mal, wenn dies genommen wird, erhält der Besitzer auch einen +1-Gang-Up-Bonus auf seine Gegner, vorausgesetzt, die Gliedmaßen werden genutzt, um einen Gegner zu bekämpfen oder anderweitig zu verwirren. Das gilt auch für Ringkampfversuche (Angreifen, nicht Befreien)."], "m": [["REICHWEITE", "+1/Stufe", "Die zusätzlichen Gliedmaßen haben jedes Mal, wenn dies genommen wird, Reichweite +1."]], "s": ["SUP"], "p": 62}, {"n": "Furcht", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Kalter Blick, schreckliche Gestalt, dunkle Kapuze, Furchtgifte", "b": ["Durch ihr Aussehen oder eine verruchte Kraft lässt der Superheld Feinde in ihren Stiefeln zittern. Zur Aktivierung von Furcht legt der Held einen Fokuswurf ab, um zu brüllen, zu schreien, zu starren oder anderweitig die Aufmerksamkeit eines Feindes innerhalb von 6“ (12 Metern) zu erregen. Ein einzelner Feind darf nicht mehr als einmal pro Zug anvisiert werden. Bei Erfolg muss das Ziel eine Furchtprobe ablegen (mit –2 bei einer Steigerung auf den Fokuswurf).", "Kein Feind darf pro Begegnung mehr als einmal durch Furcht anvisiert werden, aber die Kraft kann danach für Tests genutzt werden. Der Superheld darf dabei alle seine üblichen Modifikatoren nutzen (Flächeneffekt, Stark usw.)."], "m": [["FLÄCHENEFFEKT", "+2/+4", "Für 2 Punkte kann der Angriff alle in einer Mittleren Flächenschablone betreffen. Für 4 Punkte kann der Held entweder eine Mittlere oder eine Große Flächenschablone verwenden. Ziele im Wirkungsgebiet widerstehen einzeln."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit den Modifikatoren Reichweite oder Flächeneffekt kombiniert werden. Siehe S. 45 für weitere Informationen."], ["STARK", "+2", "Die Furchtprobe wird mit einem zusätzlichen Abzug von –2 abgelegt."]], "s": ["SUP"], "p": 62}, {"n": "Furchtlos", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Konstrukte, horrorthematische Charaktere, Draufgänger", "b": ["Der Charakter ist völlig immun gegen Furchtproben, egal ob sie von Kräften, Sonderfähigkeiten oder Situationen stammen.", "Furchtlose Helden können weiterhin Phobien durch Handicaps oder andere Quellen haben, auf die sie in ihren Abenteuern stoßen. Sie haben nicht per se „Angst“ davor, erleiden aber trotzdem die üblichen Abzüge für ihr Unbehagen und ihre allgemeine Aufregung."], "m": [["STANDHAFT", "+2", "Die Tapferkeit des Supers hilft anderen. Charaktere innerhalb von 5“ (oder ihrer Befehlsreichweite, wenn sie größer ist) erhalten +2 auf Furchtproben."]], "s": ["SUP"], "p": 62}, {"n": "Flug", "r": 5, "mp": "2–18", "rw": "", "wd": "", "au": "Flügel, Düsenrucksäcke, außerirdische Fähigkeiten, Eisbrücken, schwebende Scheiben", "b": ["Wenige Kräfte sind so ikonisch für das Superhelden-Genre wie die Fähigkeit zu fliegen! Ob sie wirklich wie ein Vogel aufsteigt, auf Eisbrücken saust oder an Stromleitungen entlanggleitet, dein Held kann sich schnell und mühelos über die Erde bewegen.", "Angriffsabzug: Die unten aufgeführten Angriffsabzüge werden von allen Nah- oder Fernkampfangriffen gegen den Flieger abgezogen, vorausgesetzt, er kann sich mit dieser Geschwindigkeit bewegen. Ignoriere den Abzug, wenn der Charakter sich nicht bewegt oder auf einen kleinen Raum beschränkt ist.", "Der Abzug ist kumulativ mit allen anderen Angriffsabzügen außer denen aus Geschwindigkeit (natürlich oder durch die Kraft) bis zu einem Maximum von –10.", "Außer Kontrolle: Wird ein Held im Flug Angeschlagen, Betäubt oder Verwundet und befindet sich in einem engen Raum, in dem er ein Hindernis treffen könnte, muss er einen Athletikwurf mit –2 ablegen oder kollidiert mit einem Schaden von 2W6+XW6, wobei X sein unmodifizierter Angriffsabzug als positiver Wert ist."], "m": [["ÜBERLICHTGESCHWINDIGKEIT", "+1", "Der Charakter muss Flug mit Beinahe-Lichtgeschwindigkeit haben, um dies zu kaufen. Er kann schließlich Überlichtgeschwindigkeiten (FTL) erreichen, sei es durch Sprünge, das Krümmen der Raumzeit oder ständige Beschleunigung. FTL kann nur im Weltraum genutzt werden, außerhalb der Schwerkraft und Atmosphäre eines Planeten. Das erlaubt es einem Charakter, in Raumfahrt-Kampagnen zwischen Welten oder Sternsystemen zu reisen."], ["GLEITER", "–1", "Nur Bewegungsweite 180 mph oder weniger. Der Flieger fliegt nicht wirklich, kann aber mit seiner Bewegungsweite gleiten und sinkt ungefähr 10 Fuß senkrecht pro 100 Fuß horizontal zurückgelegter Strecke."], ["WENDIG", "+1", "Du würfelst 2W6 zum „Rennen“ in einer taktischen Umgebung statt 1W6."], ["UNBEHOLFEN", "–2", "Dieser Modifikator darf nur genommen werden, wenn der Flug des Supers Bewegungsweite 45 oder höher hat. Sie kann leicht geradeaus fliegen, hat aber Mühe beim Wenden und Manövrieren, was ihren Angriffsabzug um 2 verringert. Bewegt sie sich mit Überschallgeschwindigkeit, beträgt ihr Angriffsabzug zum Beispiel –6 statt der üblichen –8. Der Held legt außerdem seine Athletikwürfe zur Vermeidung von Kollisionen mit –4 ab. Du darfst den Modifikator Unbeholfen nicht nehmen, wenn du Wendig genommen hast."]], "s": ["SUP"], "p": 63, "tab": {"c": ["Punkte", "Geschwindigkeit", "Angriffsabzug"], "r": [["2", "Bewegungsweite 6 (4 mph)", "0"], ["4", "Bewegungsweite 12 (8 mph)", "0"], ["5", "Bewegungsweite 24 (16 mph)", "0"], ["6", "Bewegungsweite 45 (30 mph)", "0"], ["8", "Bewegungsweite 90 (60 mph)", "–1"], ["10", "Bewegungsweite 180 (120 mph)", "–2"], ["12", "Bewegungsweite 360 (240 mph)", "–4"], ["14", "Schallgeschwindigkeit (1.200 mph)", "–6"], ["16", "Überschallgeschwindigkeit (2.400 mph)", "–8"], ["18", "Beinahe-Lichtgeschwindigkeit (240 Mio. mph)", "–10"]], "nach": 2}}, {"n": "Kraftfeld", "r": 5, "mp": "1/Stufe", "rw": "", "wd": "", "au": "Energiebläschen, Kraftfeld-Gürtel, persönliche Energiefelder", "b": ["Der Verteidiger ist von Schutzenergie umgeben, die sie (und möglicherweise andere) vor Schaden schützt. Jede Stufe verringert eingehenden Schaden um 1 Punkt (bis zu einem Maximum von –10).", "Herunterfahren: Kraftfeld endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42."], "m": [["FLÄCHENEFFEKT", "+2/+4", "Der Schutz des Helden kann sich auf alle in einer Mittleren Flächenschablone erstrecken, zentriert auf ihn selbst, für +2 Punkte, oder auf eine Große Flächenschablone für +4 Punkte. (Nimm Selektiv, um Feinde auszuschließen!) Schaden, der innerhalb des Feldes verursacht wird, wird nicht negiert."], ["LEBENSERHALTUNG", "+2", "Der Held (und jeder, der mit dem obigen Modifikator Flächeneffekt geschützt ist) ist im Kraftfeld versiegelt und kann Umgebungsbedingungen, luftübertragene Giftstoffe, Gifte oder die Wirkungen des Weltraums ignorieren. Die „Blase“ bietet atembare Luft oder was auch immer die Wesen darin für das Grundleben brauchen. Lebenserhaltung zu starten ist eine Aktion und hält, solange der Superheld sie aufrechterhält (d. h. nicht Kampfunfähig oder heruntergefahren ist)."], ["MOBIL", "+1", "Hat der Held den Modifikator Flächeneffekt, kann sie ihr Kraftfeld bis zu 12“ (24 Meter) entfernt aktivieren und es jeden Zug als begrenzte freie Aktion um bis zu 12“ bewegen. Das Feld muss in Sichtweite bleiben."], ["AKTIVIERUNG ERFORDERLICH", "–1", "Der Held muss als Aktion einen Fokuswurf ablegen, um diese Fähigkeit zu aktivieren. Verliert er die Konzentration, fährt sie herunter und muss neu aktiviert werden (siehe S. 42)."]], "s": ["SUP"], "p": 64}, {"n": "Genie", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Belesen, robotisch, hochintelligent, fotografisches Gedächtnis oder Reflexe", "b": ["Der Charakter erhält einen kostenlosen Wiederholungswurf auf alle Verstand- und verstandbasierten Fertigkeitswürfe."], "m": [["SCHNELLER LERNER", "+1", "Der Held ignoriert den Abzug von –2 bei ungeübten verstandbasierten Würfen."]], "s": ["SUP"], "p": 64}, {"n": "Wachstum", "r": 5, "mp": "3/Stufe", "rw": "", "wd": "", "au": "Wachstumspillen, Machtworte, Magie, mutierter Stoffwechsel, bullige Muskelpakete, Außerirdische, Roboter", "b": ["Der Held kann seine Größe bis zu seiner Stufe in Wachstum erhöhen. Jede Stufe erhöht seine Größe und Robustheit um einen Punkt und seine Stärke um einen Würfeltyp.", "Siehe die Größentabelle in Savage Worlds für typische Höhe und Masse jeder Größe und für Größenmodifikatoren.", "Bewegungsweite: Addiere +2 auf die Bewegungsweite des Charakters bei Groß, +4 bei Riesig und +6 bei Gigantisch.", "Reichweite: Charaktere, die Groß werden, erhalten auch Reichweite +1. Riesige Charaktere erhalten Reichweite +2, und gigantische Wesen addieren Reichweite +3.", "Stampfen: Ein riesiger oder gigantischer Charakter kann Kreaturen in einer Kleinen Flächenschablone zerstampfen, solange die Ziele mindestens zwei Größenordnungen kleiner sind. Der Angriff ignoriert Größenmodifikatoren und ist ein vergleichender Wurf Athletik gegen Geschicklichkeit (Verteidiger würfeln einzeln). Wer nicht ausweichen kann, wird für Schaden in Höhe des Stärkeschadens des Riesen zerstampft (addiere keinen Schadensbonus aus Nahkampfangriff, dem Talent Raufbold oder Kampfsportler usw.).", "Wunden: Ab Großer Größenordnung gewährt Wachstum dem Helden zusätzliche Wunden. Verfolge Wunden, die bei Großer oder größerer Größenordnung erlitten werden, getrennt. Verringert ein Held seine Größe unter diese Größenordnung und hätte mehr als seine Kapazität, ist er Kampfunfähig. Kehrt er zu einer größeren Größenordnung zurück, bleiben seine Verletzungen bestehen (ebenso seine Kampfunfähigkeit, wenn das sein aktueller Zustand ist).", "Beispiel: Ein Held erleidet in gigantischer Form fünf Wunden. Er kehrt zu Normal zurück, wo er nur drei Wunden verkraften kann, also ist er Kampfunfähig. Wenn er geweckt wird und zur gigantischen Form zurückkehrt, hat er immer noch fünf Wunden. Könnte er vier Wunden verkraften (durch das Talent Zäh wie Nägel), würde er alle vier auch in seiner normalen Größe behalten.", "Herunterfahren: Wachstum endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42. Ignoriere das, wenn der Zustand den Modifikator Dauerhaft hat."], "m": [["DAUERHAFT", "–2", "Die größere Größe des Charakters ist dauerhaft. Er kann keine normale Kleidung tragen, keine normale Ausrüstung nutzen, Nahrung kostet mehr, und er passt vielleicht nicht in Fahrzeuge oder Aufzüge, durch Türen usw."], ["SCHLAGEN", "+1/+2", "Für +1 Punkt verringert der Charakter den Größenabzug beim Angriff auf kleinere Ziele um 2. Für +2 Punkte wird der Größenabzug um 4 verringert. (Der Bonus für Angriffe auf Ziele einer größeren Größenordnung bleibt.)"]], "s": ["SUP"], "p": 64}, {"n": "Zäh", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Große, kräftige Kerle und Mädels, außerirdische Physiologie, veränderte Formen, Magie, Absorption", "b": ["Der Held ist so hart im Nehmen, dass ihm nur der schwerste Schaden etwas anhaben kann. Ein zweites Angeschlagen-Ergebnis im Kampf verursacht keine Wunde."], "m": [], "s": ["SUP"], "p": 65}, {"n": "Heilung", "r": 5, "mp": "3", "rw": "", "wd": "", "au": "Mystisches Leuchten, wundertätige Berührung, göttlicher Segen, fortschrittliche Technologie", "b": ["Dein hilfsbereiter Held kann sich selbst oder einen anderen innerhalb von 6“ (12 Metern) heilen. Das erfordert einen Fokuswurf als Aktion und heilt bei Erfolg eine Wunde, oder zwei mit einer Steigerung.", "Ein Versuch: Die Kraft Heilung darf nur einmal pro „Satz“ Wunden (Wunden aus einem Angriff) versucht werden, und nur innerhalb der „Goldenen Stunde“ nach Erhalt der Wunden. Misslingt der Wurf, kann die Kraft diese speziellen Wunden nicht heilen. Die Heilerin kann aber versuchen, alle neuen Wunden zu behandeln, die ein Patient erhält.", "Derselbe Charakter kann auch die Fertigkeit Heilen getrennt nutzen, vor oder nach dem Versuch mit der Kraft, was ihr im Grunde zwei Chancen gibt, Wunden zu heilen, wenn sie sowohl Fertigkeit als auch Kraft hat. Das Talent Heiler gilt wie üblich für Kraft und Fertigkeit.", "Unterstützen: Heiler können die natürlichen Heilungswürfe ihrer Verbündeten Unterstützen, wenn sie jeden Tag einige Minuten Behandlung bieten können."], "m": [["HEILEN", "+2", "Der Charakter kann Gift oder Schwächende oder Tödliche Krankheiten durch einen Fokuswurf mit –2 neutralisieren, oder Chronische Krankheiten mit –4. Das unterliegt der obigen Regel Ein Versuch (ein Versuch innerhalb einer Stunde nach Ansteckung mit Gift oder Krankheit)."], ["ERSCHÖPFUNG", "+2", "Anstelle von Wunden kann der Heiler stattdessen Erschöpfung heilen. Erschöpfung unterliegt der obigen Regel Ein Versuch (ein Versuch innerhalb einer Stunde nach der Erschöpfung)."], ["ERFRISCHEN", "+2", "Bei einem erfolgreichen Fokuswurf erholt sich jeder Charakter in einer Großen Flächenschablone, zentriert auf sie selbst, sofort von Angeschlagen oder Betäubt."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit dem Modifikator Reichweite kombiniert werden. Siehe S. 45 für weitere Informationen."], ["WIEDERHERSTELLUNG", "+2", "Der Heiler kann dauerhafte lähmende Verletzungen mit einem Fokuswurf mit –4 reparieren. Wiederherstellung unterliegt der obigen Regel Ein Versuch (ein Versuch innerhalb einer Stunde nach der Verletzung)."], ["WIEDERAUFERSTEHUNG", "+2", "Die ultimative Heilfähigkeit ist die Macht, einen Charakter von den Toten zu erwecken. Das erfordert den Großteil der Überreste des Gefallenen (Entscheidung der SL) und einen Fokuswurf mit –4. Bei Erfolg erhebt sich der Held Erschöpft und mit drei Wunden. Wiederauferstehung unterliegt der obigen Regel Ein Versuch (ein Versuch innerhalb einer Stunde nach dem Tod)."]], "s": ["SUP"], "p": 65}, {"n": "Geschärfte Sinne", "r": 5, "mp": "Speziell", "rw": "", "wd": "", "au": "Tiersinne, Sensoren, Roboteraugen", "b": ["Der Charakter hat extrem mächtige Sinne. Wähle eine oder mehrere der folgenden Optionen; jede Option kostet einen Machtpunkt.", "• Adleraugen: Der Charakter kann Kleingedrucktes bis zu einer Meile Entfernung lesen. Das verringert Reichweitenabzüge um 1.", "• Gehör: Der Charakter kann ein Flüstern bis zu einer Meile weit hören, wenn er weiß, dass er darauf lauschen muss. Es gibt ihm außerdem +2 auf Wahrnehmungswürfe, die auf Hören beruhen.", "• Infrarotsicht: Der Charakter kann Wärmequellen sehen. Er halbiert Dunkelheitsabzüge gegen Ziele mit Wärmesignaturen (oder deren Fehlen in normalen Umgebungen). Hat er auch Restlichtsicht, ignoriert er alle Beleuchtungsabzüge.", "• Restlichtsicht: Restlichtsicht ignoriert Abzüge für Dämmerlicht und Dunkelheit (aber nicht für Finsternis). Hat er auch Infrarotsicht, ignoriert er alle Beleuchtungsabzüge.", "• Mikroskopische Sicht: Der Held kann bis auf die molekulare Ebene sehen. Das gibt einen Bonus von +1 auf jeden Wurf, bei dem das nützlich sein könnte, etwa Heilenwürfe zur Behandlung einer Krankheit, Wissenschaft zur Analyse der Zusammensetzung einer Substanz oder Überleben, um verräterische Partikel durch sonst nicht verfolgbares Gelände zu verfolgen.", "• Geruchssinn: Ein scharfer Geruchssinn gibt dem Helden +2 auf Überlebenwürfe zum Spurenlesen, wenn das Ziel einen Geruch hatte und die Spur nicht älter als einen Tag ist.", "• Röntgensicht: Der Held kann durch jede Substanz sehen, die Röntgenstrahlen durchdringen können (meist von dickem Metall oder besonders dichten Materialien blockiert). Er kann bis zu 2 Punkte Deckungsabzüge ignorieren, wenn er durch das dazwischenliegende Hindernis sehen kann."], "m": [], "s": ["SUP"], "p": 66}, {"n": "Illusion", "r": 5, "mp": "4", "rw": "", "wd": "", "au": "Zauberei, Gedankentricks, Hologramme", "b": ["Illusion erlaubt es einem Charakter, eingebildete Bilder und Geräusche zu erschaffen. Die Illusionen können die reale Welt nicht tatsächlich beeinflussen, aber ein kluger Manipulator kann sie so aussehen lassen, als täten sie es. Der Erschaffer kann eine Illusion bis zu 12“ (24 Meter) entfernt heraufbeschwören, die eine Kugel von der Größe einer Mittleren Flächenschablone mit jedem gewünschten Bild füllt. Solange der Wirker aufpasst, reagieren die Bilder auf die Welt um sie herum, als wären sie real – sie taumeln nach Angriffen zurück, erleiden „Schaden“ und so weiter.", "Die Kugel kann als begrenzte freie Aktion um bis zu 12“ pro Zug bewegt werden.", "Eine Illusion zu erschaffen erfordert einen Fokuswurf und eine Aktion, aber sie kann aufrechterhalten werden, solange der Erschaffer es wünscht und bei Bewusstsein bleibt. Sie kann als freie Aktion aufgelöst werden.", "Illusionen werden von elektronischen Geräten nicht erfasst (es sei denn, man nimmt den Modifikator Filmqualität unten).", "Anzweifeln: Illusionen sehen nie ganz richtig aus. Details sind etwas unscharf, Bewegungen leicht daneben, oder es gibt ein „Uncanny Valley“ bei Gesichtern und Effekten. Selbst wenn man sich unsichtbar macht, bleibt ein leichter Umriss der Gestalt.", "Beiläufige Beobachter bemerken diese Mängel normalerweise nicht, aber jene, die sich damit beschäftigen oder Grund haben, mit einem Bild zu interagieren oder es genau anzusehen, erhalten einen Verstandwurf mit –2 als freie Aktion (würfle einen Gruppenwurf für gleichartige Ziele); Supers mit Fähigkeiten wie Adleraugen, Mikroskopische Sicht oder Wachsamkeit können den Abzug ignorieren.", "Bei Erfolg durchschauen diese Personen das Trugbild. Sie sehen es weiterhin und können unter bestimmten Wirkungen leiden (siehe die Modifikatoren Ablenkung oder Verschleierung), wissen aber, dass es nicht real ist und dass ein Illusionist in der Nähe sein muss. Es liegt bei der SL, wann sie den Wurf zum Anzweifeln erlaubt, aber jede Art detaillierter Interaktion (etwa Kampf) sollte normalerweise einen Wurf erlauben.", "Sobald ein Charakter erkennt, dass ein Illusionist anwesend ist, ignoriert er den Verstandsabzug von –2 für den Rest der Begegnung.", "Verkleiden: Eine illusorische Verkleidung wirkt bei beiläufiger Beobachtung gut. Sie ist aber nicht annähernd so präzise wie die Kraft Chamäleon. Jeder, der genau hinsieht, sollte einen Wurf erhalten, sie wie oben beschrieben zu durchschauen.", "Furcht: Illusionen können nach Ermessen der SL in bestimmten Umständen eine Furchtprobe auslösen.", "Herunterfahren: Illusion endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42."], "m": [["NACHWIRKUNGEN", "+1", "Alle Nachwirkungen des Vergehens der Illusion bleiben bestehen, solange die Hauptillusion anhält. Wenn zum Beispiel ein illusorisches Monster eine Stadtstraße entlang tobt, bleiben die Trümmer, die es hinterlässt (außerhalb des Wirkungsgebiets), bestehen. Es hat keine andere Spielwirkung, als die Hauptillusion glaubwürdiger zu machen."], ["FLÄCHENEFFEKT", "+2", "Die Illusion kann eine Große Flächenschablone füllen."], ["ABLENKUNG", "+1", "Wenn der Erschaffer es wünscht, sind Feinde im Wirkungsgebiet Abgelenkt, bis sie die Schablone verlassen. Das setzt sich fort, auch wenn ein Feind die Illusion durchschaut hat."], ["FILMQUALITÄT", "+1", "Kameras und Mikrofone können die Illusionen erkennen und aufzeichnen. Der Erschaffer kann das nach Belieben an- oder ausschalten."], ["VERSCHLEIERUNG", "+2", "Die Illusion kann genutzt werden, um den Erschaffer und seine Verbündeten im Wirkungsgebiet zu verschleiern. Ein Schurke könnte sich zum Beispiel ein paar Fuß links von ihrer tatsächlichen Position erscheinen lassen oder einfach verschwinden. Angriffe gegen jene, die der Erschaffer verschleiern will, werden mit –2 abgelegt. Das hat keine Wirkung auf Flächenangriffe und setzt sich fort, auch wenn ein Feind den Trick durchschaut hat."], ["SYSTEMSCHOCK", "+2", "Die Illusion kann im Zug des Erschaffers einen Angriff ausführen. Sie „trifft“ automatisch alle oder einzelne Ziele im Wirkungsgebiet, die dann einen Verstandwurf ablegen müssen oder Angeschlagen sind. Ein zweites Angeschlagen-Ergebnis durch eine Illusion verursacht keine Wunde, es sei denn, das Opfer würfelt bei seinem Verstandwurf einen Kritischen Fehlschlag (dann ist es Kampfunfähig, kann aber nicht tatsächlich sterben). Systemschock hat keine Wirkung, sobald ein Charakter eine bestimmte Illusion anzweifelt."]], "s": ["SUP"], "p": 66}, {"n": "Immun gegen Gift/Krankheit", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Außerirdische, genetische Modifikationen, Filter", "b": ["Der Charakter ist vollständig immun entweder gegen Gift oder Krankheit – Wahl des Charakters. Es kann ein zweites Mal genommen werden, um gegen beides immun zu sein."], "m": [["KRANKHEIT HEILEN", "+2", "Muss Immun gegen Krankheit haben. Der Held kann einen Fokuswurf mit –2 ablegen, um eine Schwächende oder Tödliche Krankheit zu heilen. Sie kann einen Fokuswurf mit –4 ablegen, um eine Chronische Krankheit zu heilen. Dabei erleidet sie automatisch eine Stufe Erschöpfung. Solche Charaktere ziehen viel Aufmerksamkeit auf sich und verändern die Welten, in denen sie leben, drastisch, also bedenke diesen Modifikator sorgfältig!"], ["GIFT HEILEN", "+1", "Muss Immun gegen Gift haben. Der Charakter kann einen Fokuswurf ablegen, um einen Verbündeten von jedem Gift zu heilen."]], "s": ["SUP"], "p": 67}, {"n": "Infektion", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Ekelerregende Berührung, ein Fliegenschwarm, Aura der Verderbnis", "b": ["Der Charakter infiziert seinen Feind mit einer extrem schnell wirkenden Krankheit, die Krankheit und andere Leiden verursacht.", "Ein erfolgreicher Fokuswurf lässt ein Ziel innerhalb von 6“ (12 Metern) einen Konstitutionswurf ablegen (mit –2 bei einer Steigerung auf den Fokuswurf). Misslingt dem Opfer der Wurf, erleidet es eine Stufe Erschöpfung.", "Zu Beginn seines nächsten Zugs muss es einen weiteren Konstitutionswurf ablegen. Misslingen führt zu einer weiteren Stufe Erschöpfung. Erfolg wehrt weitere Wirkungen in dieser Runde ab, aber das Opfer muss in seinem nächsten Zug erneut würfeln. Mit einer Steigerung gibt es keine weitere Wirkung, und es wird für den Rest der Begegnung immun gegen alle weiteren Wirkungen der Infektionskraft dieses Angreifers.", "Erschöpfung wird normal erholt (siehe Savage Worlds) und kann Kampfunfähigkeit verursachen, aber nicht den Tod."], "m": [["LEIDEN", "+2", "Für +2 Punkte verursacht die Infektion eines der folgenden Schweren Handicaps zusätzlich zur Erschöpfung. Das hält an, bis alle Erschöpfung wiederhergestellt ist. Leiden: Blutarm, Schlechte Augen, Tollpatschig, Schwerhörig, Stumm, Langsam, Zungenbrecher, Hässlich."], ["FLÄCHENEFFEKT", "+2/+4", "Für 2 Punkte kann der Angriff alle in einer Mittleren Flächenschablone betreffen. Für 4 Punkte kann der Held entweder eine Mittlere oder eine Große Flächenschablone verwenden. Ziele im Wirkungsgebiet widerstehen einzeln."], ["ANSTECKEND", "+1", "Infizierte Personen können die Infektion an jeden weitergeben, der sie berührt! Jeder, der in körperlichen Kontakt mit dem Charakter kommt, muss einen Konstitutionswurf (ohne Abzüge) ablegen oder wird infiziert."], ["WIRKUNGSDAUER", "+1", "Die Krankheit hält viel länger an. Statt automatisch jede Stunde eine Stufe Erschöpfung zu entfernen, legt das Opfer alle 24 Stunden einen Konstitutionswurf ab. Erfolg entfernt eine Stufe Erschöpfung, eine Steigerung entfernt zwei."], ["TÖDLICH", "+1", "Erschöpfung durch Infektion kann zum Tod führen."], ["MUTATION", "+1", "Der Seuchenträger kann als begrenzte Aktion einen Fokuswurf ablegen, um die Infektion zu mutieren, sodass sie in dieser Begegnung als neue Art der Infektion zählt und damit die Immunität jener ignoriert, die zuvor mit einer Steigerung widerstanden haben."], ["VERVIELFÄLTIGUNG", "+1", "Jeder, der stirbt, während er an Infektion leidet, erhebt sich W6 Runden später als das, was ihn getötet hat (oder langsamer, wenn der Angreifer es bevorzugt)."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit den Modifikatoren Reichweite oder Flächeneffekt kombiniert werden. Siehe S. 45 für weitere Informationen."], ["STARK", "+2", "Konstitutionswürfe zum Widerstehen der Infektion werden mit einem zusätzlichen –2 abgelegt."]], "s": ["SUP"], "p": 67}, {"n": "Unberührbarkeit", "r": 5, "mp": "5", "rw": "", "wd": "", "au": "Nebel- oder Energieform, ein Geist, außer Phase, ein Insektenschwarm", "b": ["Unberührbarkeit macht einen Charakter unfähig, physische Angriffe zu beeinflussen oder von ihnen beeinflusst zu werden, wie ein Phantom oder Geist. Energie-Machttypen beeinflussen unberührbare Charaktere normal – nimm Resistenz für mehr Widerstandsfähigkeit gegen diese Machttypen.", "Die Kraft erlaubt es einem Superhelden, durch Wände oder andere Barrieren zu gehen, macht ihn aber nicht unsichtbar (nimm dafür Unsichtbarkeit).", "Unberührbar zu werden ist eine Aktion. Solange er unberührbar ist, werden auch alle Gegenstände, die der Charakter trägt, unberührbar und funktionieren nicht. Wesen, die der Charakter trägt, werden fallengelassen. Wieder berührbar zu werden ist eine freie Aktion.", "Phasen: Ein unberührbarer Charakter kann einen Angriff ausführen und dann wieder unberührbar werden. Gegner, die einen „Phaser“ angreifen wollen, können in Bereitschaft gehen und erfolgreich unterbrechen, um anzugreifen, wenn sie wollen.", "Verwunden: Ein unberührbarer Held kann einem Feind Schaden zufügen, indem er in die Gestalt des Feindes phast (meist eine Hand in die Brust). Das ist ein vergleichender Fokuswurf gegen die Athletik oder Konstitution des Ziels (Wahl des Verteidigers). Gewinnt der Angreifer, erleidet das Opfer eine Wunde (zwei mit einer Steigerung). Ist der Fokuswurf des Angreifers ein Kritischer Fehlschlag, erleidet er stattdessen eine Wunde!", "Herunterfahren: Unberührbarkeit endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42. Ignoriere das, wenn sie den Modifikator Dauerhaft nimmt."], "m": [["ANDERE BEEINFLUSSEN", "+2", "Der Held kann Individuen innerhalb von 6“ (12 Metern) mit einem Fokuswurf unberührbar machen. Das erfordert intensive Konzentration, daher kann sie nichts als freie Aktionen ausführen, solange sie die Unberührbarkeit eines anderen aufrechterhält. Unwillige Opfer widerstehen mit Willenskraft (mit –2 bei einer Steigerung auf den Fokuswurf). Misslingt es, werden sie unberührbar und können die physische Welt nicht beeinflussen. Sie können zu Beginn jedes Zugs als freie Aktion einen Willenskraftwurf mit –2 ablegen, um wieder stofflich zu werden."], ["DAUERHAFT", "–2", "Der Charakter ist dauerhaft unberührbar. Sie kann in ihrem Zug als freie Aktion einen Fokuswurf ablegen, um die physische Welt zu beeinflussen, und kehrt am Ende wieder in ihren unberührbaren Zustand zurück. Sie kann nur durch natürliche Heilung oder übernatürliche Mittel (etwa die Kraft Heilung) geheilt werden. Der Modifikator Dauerhaft erlaubt es dem Superhelden, die Regeln zum Herunterfahren zu ignorieren."], ["AKTIVIERUNG ERFORDERLICH", "–1", "Der Held muss als Aktion einen Fokuswurf ablegen, um diese Fähigkeit zu aktivieren. Verliert er die Konzentration, fährt sie herunter und muss neu aktiviert werden (siehe S. 42)."]], "s": ["SUP"], "p": 68}, {"n": "Schnittstelle", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Roboter, Cyborgs, Laptops, „Einstöpseln“", "b": ["Dein Held kann mit elektronischen Gadgets Schnittstellen bilden und erhält viel größeren Zugriff auf ihr Innenleben als andere. Er erhält +2 auf Elektronik- und Hackenwürfe."], "m": [["CODEKNACKER", "+1", "Der Superheld kann elektronische Schlösser öffnen, Sicherheitssysteme umgehen und andere ähnliche Schutzvorrichtungen ohne Werkzeuge überwinden. Diebeskunst erhält den +2-Bonus für Schnittstelle, solange irgendwie Elektronik beteiligt ist."], ["SCHNELL", "+2", "Versuche, eine von Schnittstelle betroffene Fertigkeit einzusetzen, die normalerweise 10 Minuten oder weniger dauern, können mit einer einzigen Aktion versucht werden."], ["REICHWEITE", "+1", "Der Charakter kann mit Geräten bis zu 12“ (24 Metern) Entfernung Schnittstellen bilden."]], "s": ["SUP"], "p": 69}, {"n": "Unsichtbarkeit", "r": 5, "mp": "8", "rw": "", "wd": "", "au": "Zellveränderung, Tarnanzug", "b": ["Unsichtbar zu werden ist eine Aktion, die den Charakter und seine gesamte Ausrüstung sofort schwer sichtbar macht. Versuche, sie wahrzunehmen, und direkte Angriffe gegen sie erleiden einen Abzug von –4.", "Tut der unsichtbare Charakter etwas Offensichtliches, wie im Regen zu stehen, wird der Angriffsabzug für diesen Zug halbiert und es ist kein Wahrnehmungswurf nötig, um ihre Anwesenheit zu entdecken. Wieder sichtbar zu werden ist eine freie Aktion.", "Herunterfahren: Unsichtbarkeit endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42. Ignoriere das, wenn sie den Modifikator Dauerhaft nimmt."], "m": [["MOBIL", "+1", "Der Held muss den Modifikator Projektion haben, um Mobil zu nehmen. Damit kann sie ihr Unsichtbarkeitsfeld bis zu 12“ (24 Meter) entfernt aktivieren und es um denselben Betrag als begrenzte freie Aktion bewegen."], ["DAUERHAFT", "–2", "Der Charakter ist immer unsichtbar. Neben den offensichtlichen Rollenspielproblemen, etwa einen Kampfunfähigen Helden zu finden oder die Schwierigkeit persönlicher Beziehungen, erleiden jene, die ihn heilen wollen, einen Abzug von –4, da seine Verletzungen nicht sichtbar sind. Der Modifikator Dauerhaft erlaubt es dem Superhelden, die Regeln zum Herunterfahren zu ignorieren."], ["PERSÖNLICH", "–2", "Die Unsichtbarkeit des Supers umfasst keine Ausrüstung oder Kleidung. Er muss nackt sein! Gegenstände zu tragen ist so offensichtlich wie im Regen zu stehen (kein Wahrnehmungswurf zum Entdecken und halbe Abzüge beim Angriff auf sie)."], ["PROJEKTION", "+3/+6", "Der Held kann sein Unsichtbarkeitsfeld in eine Mittlere Flächenschablone projizieren, zentriert auf ihn selbst, für +3 Punkte, oder in eine Große Flächenschablone für +6."], ["ECHTE UNSICHTBARKEIT", "+2", "Der Abzug, den Superhelden zu sehen oder anzugreifen, steigt auf –6."]], "s": ["SUP"], "p": 69}, {"n": "Pech bringen", "r": 5, "mp": "4", "rw": "", "wd": "", "au": "Böser Blick, Fluch, Superglück", "b": ["Feinde erleiden ständig kleine Ausrutscher, Fehlzündungen und andere Missgeschicke, wenn sie versuchen, diesem Superhelden zu schaden.", "Jeder, dem eine Aktion misslingt, die den Helden betrifft, einschließlich Flächenangriffe, Tests usw., wird Verwundbar. Bei einem Kritischen Fehlschlag sind sie zusätzlich Angeschlagen (zusätzlich zu allen anderen Wirkungen).", "Das könnte einen verwandten Vorfall darstellen – die Kugel eines Schlägers prallt von einer Wand ab und trifft einen anderen; oder ein völlig unabhängiges Ereignis tritt ein – ein Topf fällt von einem hohen Fenster und zerschellt auf dem Kopf eines Schlägers, gerade als er schießen will. Die SL darf kreativ werden, wenn sie das Pech beschreibt, das jene trifft, die sich mit dieser „schwarzen Katze“ anlegen."], "m": [["GRÖSSERES PECH", "+2", "Wer beim Angriff auf den Helden einen Kritischen Fehlschlag würfelt, ist Angeschlagen oder Betäubt, nach Wahl des Spielers."]], "s": ["SUP"], "p": 70}, {"n": "Springen", "r": 5, "mp": "1–8", "rw": "", "wd": "", "au": "Gewaltige Stärke, Sprungfedern, dicke Beine", "b": ["Dein Charakter kann tatsächlich hohe Gebäude mit einem einzigen Sprung überspringen. Die Zahl der Punkte in der Kraft bestimmt, wie weit er springen kann.", "Fallen: Der Springer ignoriert Sturzschaden bei Höhen bis zu seiner vertikalen Sprungweite, es sei denn, er ist verstrickt, gebunden oder anderweitig daran gehindert, auf den Füßen zu landen.", "Bewegung: Springen addiert sich nicht zur Geh- oder Laufbewegungsweite eines Charakters – nutze stattdessen den höchsten Bewegungswert. Kann sie zum Beispiel horizontal 4“ springen, ist sie mit Bewegungsweite 6 besser dran, wenn sie geht. Die Kraft ist weiterhin nützlich, um Schluchten, Dächer und Ähnliches zu überwinden, macht sie aber nicht schneller."], "m": [["ABPRALLEN", "+1", "Der Charakter hat gelernt, sich von senkrechten Flächen abzustoßen, um höher zu klettern, als er sonst könnte. Er kann jede Höhe erklimmen, solange es gegenüberliegende Wände oder andere Flächen zum Abstoßen gibt."], ["TOD VON OBEN", "+1", "Solange er nicht am Springen gehindert ist, verursachen die Wilden Angriffe des Charakters +4 Schaden statt +2."]], "s": ["SUP"], "p": 70, "tab": {"c": ["Kosten", "Vertikale Weite", "Horizontale Weite"], "r": [["1", "2“ (4 Meter)", "4“ (8 Meter)"], ["2", "4“ (8 Meter)", "8“ (16 Meter)"], ["3", "8“ (16 Meter)", "16“ (32 Meter)"], ["4", "16“ (32 Meter)", "32“ (64 Meter)"], ["5", "32“ (64 Meter)", "64“ (128 Meter)"], ["8", "Eine halbe Meile", "Eine Meile"]], "nach": 3}}, {"n": "Maschinenkontrolle", "r": 5, "mp": "Speziell", "rw": "", "wd": "", "au": "Technokinese, elektrische Kontrolle, elektronische Integration, Androiden", "b": ["Der Superheld kann elektrische und elektronische Maschinen bis zu 12“ (24 Metern) Entfernung mental kontrollieren. Kontrollierte Geräte können ihre üblichen Funktionen ausführen, sich mit ihrer üblichen Geschwindigkeit bewegen (falls überhaupt), angemessenen Schaden verursachen (Entscheidung der SL angesichts der vielen Möglichkeiten) und die Fertigkeit Fokus des Charakters für Angriffe, Manöver und Ähnliches nutzen.", "Die Größe einer Maschine entspricht den Punkten, die nötig sind, um sie zu kontrollieren (Mindestkosten 1). Ein Motorrad (Größe 1) braucht zum Beispiel 1 Punkt Maschinenkontrolle, ein Bulldozer der Größe 6 braucht 6 Punkte. Mit 7 Punkten in Maschinenkontrolle könnte sie sowohl ein Motorrad als auch einen Bulldozer gleichzeitig kontrollieren.", "Maschinenkontrolle erlaubt dem Superhelden nicht, ein normalerweise lebloses Gerät zu bewegen (nutze dafür Materiekontrolle oder Telekinese) – sie kann es nur so funktionieren lassen, als würde sie es selbst bedienen.", "Die Kontrolle über eine Maschine zu übernehmen ist eine Aktion und ein Fokuswurf (mit –2 oder mehr, wenn die Maschine besonders hochtechnisiert, abgeschirmt, außerirdischen Ursprungs usw. ist). Hat die Maschine eine KI, behandle dies wie Gedankenkontrolle (S. 74), wobei die KI mit Verstand oder Willenskraft (ihre Wahl) widersteht, wenn sie etwas gegen ihre Direktiven tun soll.", "Sobald sie kontrolliert wird, bleiben alle automatischen Funktionen so an, wie der Kontrolleur es wünscht. Das schließt die Bewegung mobiler Maschinen wie Fahrzeuge ein.", "Jede „aktive“ Funktion, wie jemanden zu rammen oder einen Angriff auszuführen, erfordert eine Aktion und einen Fokuswurf. Ein Motorrad und einen Bulldozer zu fahren erfordert zum Beispiel keine Aktionen oder Würfe. Zu versuchen, jemanden mit einem von beiden zu treffen, erfordert einen Fokuswurf (anstelle des üblichen Fahrenwurfs). Ebenso könnte ein Maschinenkontrolleur, der ein Raumschiff mit mehreren Waffen übernimmt, das Schiff umsonst fliegen und bis zu drei Waffen mit dem üblichen Mehrfachaktionsabzug abfeuern.", "Rivalisierende Kontrolleure: Wird ein Gerät bereits von einem anderen kontrolliert, ist der Fokuswurf des Supers vergleichend zum Fokus des Rivalen."], "m": [["MEHRFACH-AUFGABEN", "+2/+4", "Für +2 ignoriert der Charakter zwei Punkte Mehrfachaktionsabzug, wenn mindestens eine Aktion mit einer kontrollierten Maschine erfolgt. Für +4 ignoriert der Charakter vier Punkte Mehrfachaktionsabzug, solange zwei der Aktionen mit einer kontrollierten Maschine erfolgen."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss ein Gerät berühren, um es zu kontrollieren. Das darf nicht mit dem Modifikator Reichweite kombiniert werden. Siehe S. 45 für weitere Informationen."]], "s": ["SUP"], "p": 71}, {"n": "Fehlfunktion", "r": 5, "mp": "3", "rw": "", "wd": "", "au": "Elektromagnetischer Impuls, Verhexungen, Pech", "b": ["Der Charakter kann technische Geräte und Maschinen versagen lassen, indem er ein Ziel innerhalb von 12“ wählt und einen Fokuswurf ablegt, abzüglich der Modifikatoren unten. Bei Erfolg hat das Gerät irgendeine Fehlfunktion. Mit einer Steigerung ist jeder, der das Gerät benutzt, Abgelenkt.", "Die meisten Geräte hören einfach auf zu funktionieren, bis der Träger eine Aktion nutzt, um einen Reparierenwurf abzulegen. Große oder komplexe Geräte mit Wunden wie Fahrzeuge erleiden einen Kritischen Treffer (siehe Savage Worlds). Ein Superheld kann bestimmte Teile oder Subsysteme komplexer Geräte anvisieren, wenn er will, als Gezielter Angriff."], "m": [["FLÄCHENEFFEKT", "+2/+4", "Fehlfunktion kann alles in einer Mittleren Flächenschablone für 2 Punkte betreffen, oder in einer Großen Flächenschablone für 4 Punkte."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Ziel berühren, um es zu beeinflussen. Das darf nicht mit den Modifikatoren Reichweite oder Flächeneffekt kombiniert werden. Siehe S. 45 für weitere Informationen."]], "s": ["SUP"], "p": 71, "tab": {"c": ["Gerät", "Abzug"], "r": [["Einfach (Dosenöffner, Schusswaffe, Bogen)", "–0"], ["Mittel (Lasergewehr, ziviler Fahrzeugmotor, Mikrowellenherd)", "–2"], ["Komplex (Panzer, abgeschirmte Militärtechnik, außerirdische Technologie)", "–4"]], "nach": 1}}, {"n": "Materiekontrolle", "r": 5, "mp": "5", "rw": "", "wd": "", "au": "Mutantenkräfte, veränderte Form ähnlicher Materie, Elementarkontrolle", "b": ["Materiekontrolle erlaubt es einem Superhelden, als Aktion einen Materie-Machttyp innerhalb eines einzelnen „Energiefelds“ zu manipulieren. Das Feld ist eine Kugel von der Größe einer Mittleren Flächenschablone, die bis zu 12“ (24 Meter) entfernt erscheint.", "Der Kontrolleur kann das Feld in ihrem Zug als begrenzte freie Aktion um bis zu 12“ (24 Meter) pro Zug bewegen, solange es in Sichtweite bleibt.", "Das Feld hält, solange der Superheld es aufrechterhält (d. h. nicht Kampfunfähig oder heruntergefahren ist). Sobald es erzeugt ist, kann der Kontrolleur als begrenzte freie Aktion einen der folgenden Effekte in ihrem Materiefeld aktivieren oder deaktivieren:", "• Barriere: Feste Materie wie Erde, Metall oder Pflanzen kann in jede Form gebracht und an Ort und Stelle gelassen werden. Unabhängig von Größe oder Form hat sie Härte 10, und wenn sie zerschmettert wird, räumt sie das Gebiet effektiv frei, bis auf die Trümmer, die sie hinterlässt.", "• Schaden: Jeder im Feld erleidet am Ende des Zugs des Supers 2W6 Schaden durch wirbelnde Sande, Austrocknung, einen Steinhagel oder einen anderen schädlichen Effekt, der zum Machttyp passt.", "• Dämpfen: Der Kontrolleur bietet jedem im Feld Umweltresistenz (siehe S. 61) gegen ihren gewählten Machttyp.", "• Ablenken: Jeder in der Schablone ist am Ende des Zugs des Supers Abgelenkt. Entferne den Zustand am Ende ihres Zugs wie üblich, wenn sie nicht mehr in der Schablone sind.", "Andere Fähigkeiten: Andere „Materiekontroll“-Fähigkeiten wie Fernkampfangriffe, Verstricken, Schadensfeld, Kraftfeld und Ähnliche können separat genommen werden und denselben Machttyp wie Materiekontrolle nutzen, um größere Meisterschaft darzustellen.", "Herunterfahren: Materiekontrolle endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42."], "m": [["ZUSÄTZLICHER MACHTTYP", "+1", "Der Held kann einen zusätzlichen Materie-Machttyp kontrollieren. Das kann mehr als einmal genommen werden, wobei jedes Mal ein anderer Materie-Machttyp gewählt wird."], ["FLÄCHENEFFEKT", "+2", "Der Kontrolleur kann ihr Materiefeld auf die Größe einer Großen Flächenschablone ausdehnen."], ["MACHT", "+5", "Die Materie des Charakters hat größere Wirkung. Die Härte ihrer Barriere steigt auf 14, der Schaden steigt auf 4W6, Dämpfen gibt Verbündeten Immunität gegen den Machttyp, solange sie im Feld sind, und Ablenken macht Feinde Abgelenkt und Verwundbar."], ["MATERIAL ERFORDERLICH", "–1/–2", "Der Charakter kann keine Materie erzeugen. Sie muss eine Quelle davon innerhalb von 12“ haben, um ihre Kraft zu nutzen. Das ist ein Punkt Rabatt, wenn die Materie recht häufig ist (Steine, Wasser), oder 2 Punkte, wenn sie selten ist (Spezialmetalle)."]], "s": ["SUP"], "p": 72}, {"n": "Nahkampfangriff", "r": 5, "mp": "Speziell", "rw": "", "wd": "", "au": "Steinharte Fäuste, aufgebaute Energie, Druckpunkte, athletische Fähigkeiten, Kampfsport", "b": ["Alle Charaktere verursachen ihren Stärkeschaden, wenn sie jemanden mit einem unbewaffneten Angriff schlagen oder treten. Das ist kostenlos und steht nicht in ihrem Profil, es sei denn, sie haben es mit zusätzlichem Schaden verbessert (siehe Tabelle unten) oder haben natürliche oder besondere Waffen (siehe die Modifikatoren).", "Ein Charakter kann seinen Nahkampfschaden auch durch diese Kraft verbessern, die für alle bewaffneten und unbewaffneten Kämpfen-Angriffe gilt:", "Talente: Ein Schadenswürfel aus den Talenten Raufbold, Schläger, Kampfsportler oder Kampfkünstler wird zum Nahkampfangriff eines Charakters addiert. Ein Held mit dem Talent Kampfsport und 4 Punkten in dieser Kraft würfelt zum Beispiel Stä+W4+2W6.", "Waffen: Addiere jeden Waffenschaden zur Summe. Ein Held mit Nahkampfangriff +2W6 und einem Kurzschwert (+W6) verursacht zum Beispiel Stä+3W6 Schaden.", "Rassenfähigkeiten: Charaktere mit den Rassenfähigkeiten Biss, Klauen oder Hörner erhalten den entsprechenden Modifikator unten kostenlos.", "Alternative Eigenschaft: Der Zielwert, um einen Gegner mit Nahkampfangriff zu treffen, ist immer seine Parade, auch wenn die Fertigkeit von Kämpfen auf etwas anderes geändert wird.", "Zusätzliche Angriffsformen: Nahkampfangriff unterscheidet sich von den meisten Kräften dadurch, dass er vier verschiedene „Angriffsformen“ umfasst: Schläge und Tritte (die Kernkraft), Bisse, Klauen und Spezialwaffen. Modifikatoren wie Panzerbrechend, Wuchtig oder Schwere Waffe gelten für jede Angriffsform separat. Das erlaubt es dir, jede Form anzupassen, und gibt einem Helden vielleicht einen Biss mit DB 4, Klauen mit DB 6 und einen magischen Hammer, der eine Schwere Waffe ist.", "Nahkampfangriffe anpassen: Die Kraft Nahkampfangriff ist etwas anders als die meisten Kräfte, da du eine Stufe kostenlos nehmen kannst, sie mehr Modifikatoren hat und die Modifikatoren Panzerbrechend und Gerät separat anwendet. Das geschieht, damit du viele verschiedene Arten von Comic-Raufbolden erschaffen kannst. Konzentriere dich auf den Basis-Bonusnahkampfschaden für Helden, die sich auf ihre Fäuste, ihr Können oder rohe Kraft verlassen. Konzentriere dich auf integrierte Waffen wie Biss, Klauen oder Hörner, um einen tierischen oder wilden Kampfstil darzustellen. Stecke deine Punkte in Spezialwaffe, wenn dein Super ein magisches Schwert, einen göttlichen Hammer oder eine futuristische Vibroklinge führt. Ist sie eine unerfahrene Kämpferin mit einer fantastischen Waffe, stecke alle deine Punkte in den Schaden der Waffe statt in Bonus-Nahkampfschaden. Dasselbe gilt für alle Angriffsformen, die Geräte sind (S. 45). Der Rabatt für Gerät kann für jede Angriffsform, für die er gilt, separat genommen werden, kann die Kosten einer Form aber nie unter 1 senken."], "m": [["PANZERBRECHEND", "+1", "Jeder ausgegebene Punkt addiert +2 DB (maximal DB 20) auf eine beliebige Angriffsform."], ["AUFLADEN", "+1", "Der Held kann seine Angriffsform als begrenzte Aktion „aufladen“ und +1W6 auf den ersten Schadenswurf in seiner nächsten Aktion addieren (oder +1W10, wenn mit Alles auf eine Karte (S. 30) kombiniert)."], ["ZERSCHMETTERN", "+3", "Der Superheld kann für einen Angriff in diesem Zug die Rüstung lebloser Objekte und Fahrzeuge (nicht von Personen oder der Rüstung, die sie tragen) ignorieren. Sobald Zerschmettern angesagt ist, ist der Held bis zum Ende seines nächsten Zugs Verwundbar."], ["WURFWAFFEN", "+2", "Der Nahkampfschadensbonus des Helden gilt für Wurfwaffen."], ["KLAUEN", "+2", "Der Charakter hat Klauen, die seinen Nahkampfangriffen +W4 Schaden und +2 auf Athletik (Klettern) geben. Der Schaden der Klauen kann für +1 Punkt auf W6 oder für +3 Punkte auf 2W6 erhöht werden."], ["BISS", "+1", "Der Held hat Reißzähne. Beißt sie, addiert sie +W4 Schaden auf ihren Nahkampfangriff. Sie kann auch einen Feind beißen, den sie im Ringkampf festhält. (Die meisten Angreifer können ihre Beute nur mit roher Stärke zerquetschen, siehe Ringkampf in Savage Worlds.) Der Schaden kann für +1 Punkt auf W6 oder für +3 Punkte auf 2W6 erhöht werden."], ["HÖRNER", "+1", "Der Held hat Hörner, die beim Einsatz +W4 Schaden auf ihren Nahkampfangriff addieren. Sie addieren auch +4 Schaden am Ende eines Kämpfen-Angriffs, wenn sie mindestens 5“ (10 Meter) rennt und einen Feind damit trifft. Der Schaden kann für +1 Punkt auf W6 oder für +3 Punkte auf 2W6 erhöht werden."], ["SPEZIALWAFFE", "+2", "Der Held hat eine einzigartige Handwaffe, die +W6 Schaden auf seinen Nahkampfangriff zusätzlich zum üblichen Schadenswürfel der Waffe addiert. Ein Langschwert (Stä+W8) und die Kraft Nahkampfangriff bei +3W6 verursachen als Spezialwaffe zum Beispiel Stä+W8+4W6. Erhöhe den zusätzlichen Schaden auf +2W6 für +2 Punkte, +3W6 für +4 Punkte, +4W6 für +6 Punkte oder +5W6 für +8 Punkte. Spezialwaffe ist kumulativ mit Nahkampfangriff, aber der maximale Schaden beträgt +5W6. Die Waffe hat alle üblichen Werte dieser Handwaffe, etwa Schaden, Boni oder Abzüge auf Parade usw. Verlorene Waffen: Wird eine Spezialwaffe verloren oder weggenommen, verliert der Held ihren Bonus. Ist sie dauerhaft verloren oder zerstört, kläre mit der SL, wie ein Ersatz durch ein kurzes Abenteuer oder eine Aufgabe erlangt werden könnte. Passendes Paar: Für +1 Punkt gilt die Kraft für zwei Waffen, meist ein passendes Paar Dolche, Schwerter, Tonfas usw. Rückkehrend: Für +1 Punkt kehrt die Waffe in die Hand des Anwenders zurück, nachdem sie geworfen wurde."]], "s": ["SUP"], "p": 73, "k": [{"h": "Warum nutzen nicht alle Supers Waffen?", "b": ["Supers können Waffen nutzen, um mehr Schaden zu verursachen, da sie mit Nahkampfangriff kumulativ sind, aber die meisten tun es aus verschiedenen Gründen nicht.", "Zuallererst, um sich aus Ärger mit den Behörden herauszuhalten und eine geheime Identität zu schützen. Es ist schwer, ein Langschwert in lässiger Businesskleidung zu verbergen, und Schusswaffen sind in den meisten städtischen Gebieten illegal. Mit einer Pistole in einem New Yorker Diner gesehen zu werden, führt zu Verhaftung, Geldstrafen und Behörden, die in der eigenen Vergangenheit graben.", "Zweitens Vertrauen und öffentliche Wahrnehmung. Ein Charakter namens „Der Schwarze Ritter“ kommt wahrscheinlich mit Schwert und Schild davon – das erwarten die Leute als Teil des Kostüms. Ein schwertschwingender Selbstjustizler ohne mittelalterliches Thema wirkt dagegen wahrscheinlich nur blutrünstig, besonders in einem Setting mit irgendeinem Zugeständnis an Realismus. Schwerter hinterlassen grauenhafte Schnitte, abgetrennte Gliedmaßen und blutige Enthauptungen. Faustkämpfe verursachen, zumindest in einer filmischen Welt, viel weniger Blutvergießen und sind für die Öffentlichkeit weit weniger verstörend.", "Das Vertrauen in Helden, die Schusswaffen nutzen, ist noch schlechter. Solange eine Waffe nicht auf irgendeine Weise modifiziert ist, sind Schusswaffen immer tödliche Waffen. In Settings, in denen von Helden nicht erwartet wird, dass sie ihre Feinde töten, stehen jene, die Schusswaffen nutzen, selten gut mit den Behörden oder anderen Helden.", "Schurken nutzen weit eher Waffen. Sie wollen ihre Feinde und die Öffentlichkeit einschüchtern und kümmern sich meist nicht darum, ob ihre Angriffe schockierend tödlich sind. Natürlich beschränken sich manche aus Bequemlichkeit, wegen eines besonderen Angriffs oder meistens, um zu zeigen, dass sie keine Waffe brauchen, um ihre Feinde zu dominieren, auf Fäuste."]}], "tab": {"c": ["Schaden", "Kosten"], "r": [["Stä", "—"], ["Stä+W6", "2"], ["Stä+2W6", "4"], ["Stä+3W6", "6"]], "nach": 2}}, {"n": "Gedankenkontrolle", "r": 5, "mp": "5", "rw": "", "wd": "", "au": "Konzentrische Energieringe, Mesmerismus, Voodoo-Puppen", "b": ["Eine der nützlichsten und hinterhältigsten Fähigkeiten ist die Macht, den Geist und Körper einer anderen Person zu kontrollieren.", "Der Superheld kann ein Ziel innerhalb von 12“ (24 Metern) kontrollieren, indem er einen Fokuswurf ablegt. Misslingt dem Kontrolleur der Fokuswurf, weiß das Subjekt, dass etwas geschieht – weitere Versuche, ihren Geist zu übernehmen, werden für den Rest dieser Begegnung mit –2 abgelegt. Ein Kritischer Fehlschlag bedeutet, dass der Kontrolleur in dieser Begegnung nicht mehr versuchen kann, das Subjekt zu kontrollieren.", "Bei Erfolg muss das Ziel einen Willenskraftwurf zum Widerstehen ablegen (mit –2 bei einer Steigerung auf den Fokuswurf), oder sie wird kontrolliert, solange der Angreifer die Kraft aufrechterhalten will oder bis sie sich befreit (siehe unten).", "Widersteht das Ziel, gibt es keine weitere Wirkung, und der Kontrolleur kann es erneut versuchen, wenn er kann. Widersteht das Ziel mit einer Steigerung, stählt sie ihren Geist und addiert +2 auf weitere Widerstandsversuche für den Rest der Begegnung.", "Ist der Kontrolleur erfolgreich und das Ziel widersteht nicht, muss das Opfer den Befehlen des Supers nach besten Kräften gehorchen, bis es sich befreit (siehe unten) oder freigelassen wird. Das Opfer muss die Befehle ihres „Meisters“ hören oder anderweitig empfangen können – der Kontrolleur hat keine mentale Verbindung zum Opfer, es sei denn, er hat Telepathie oder eine ähnliche Fähigkeit als separate Kraft.", "Ein Geist: Ein Gedankenkontrolleur kann nur ein Opfer gleichzeitig kontrollieren (es sei denn, er hat den Modifikator Mehrere Geister unten).", "Befreien: Erhält sie einen Befehl, der dem Subjekt oder Menschen, die ihr wichtig sind, direkt schaden könnte oder ihre Kernethik oder primären Pflichten verletzt, erhält das Ziel einen Verstandwurf als freie Aktion (mit –2, wenn der anfängliche Fokuswurf des Supers mit einer Steigerung gelang). Gelingt er, befolgt sie den Befehl nicht, bleibt aber kontrolliert. Mit einer Steigerung befreit sie sich und addiert +2 auf den Widerstand gegen die Gedankenkontrolle des Supers für den Rest dieser Begegnung.", "Herunterfahren: Gedankenkontrolle endet, wenn der Superheld die Konzentration verliert. Siehe Herunterfahren auf S. 42."], "m": [["VERGESSLICH", "+2", "Das Opfer erinnert sich nicht, was geschah, als es gedankenkontrolliert war."], ["AN DER LEINE", "–2", "Der Kontrolleur muss innerhalb von 12“ (24 Metern) von seinem Subjekt bleiben, sonst endet die Kraft sofort."], ["MEHRERE GEISTER", "+2", "Der Superheld kann jedes Mal, wenn dieser Modifikator genommen wird, die Kontrolle über einen zusätzlichen Geist aufrechterhalten. Jeder muss wie üblich separat kontrolliert werden."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit dem Modifikator Reichweite kombiniert werden. Siehe S. 45 für weitere Informationen."], ["VERSTAND", "+1", "Wenn der Kontrolleur es wählt, muss das Opfer mit Verstand statt mit Willenskraft widerstehen."], ["STARK", "+2", "Der Verstandwurf zum Widerstehen oder Befreien von der Gedankenkontrolle wird mit einem zusätzlichen Abzug von –2 abgelegt."]], "s": ["SUP"], "p": 74}, {"n": "Gedankenlesen", "r": 5, "mp": "3", "rw": "", "wd": "", "au": "Konzentration, mystisches Leuchten, Swamis, Hypnose", "b": ["Gedankenlesen erlaubt es einem Charakter, die oberflächlichen Gedanken eines anderen zu lesen und vielleicht sogar in ihre vergangenen Erinnerungen zu blicken.", "Um jemandes Gedanken zu lesen, wählt der Superheld ein Ziel innerhalb von 6“ (12 Metern) und legt einen Fokuswurf ab. Ist er erfolgreich, legt das Ziel einen Verstandwurf zum Widerstehen ab (mit –2 bei einer Steigerung auf den Fokuswurf).", "Misslingt dem Gedankenleser sein Fokuswurf, weiß das Subjekt, dass etwas vor sich geht – weitere Versuche, ihre Gedanken zu lesen, werden für den Rest dieser Begegnung mit –2 abgelegt. Ein Kritischer Fehlschlag bedeutet, dass der Psioniker die Gedanken dieses Subjekts in dieser Begegnung nicht mehr lesen kann.", "Widersteht das Ziel erfolgreich, gibt es keine weitere Wirkung, und der Gedankenleser kann es erneut versuchen, wenn er will. Widersteht das Ziel mit einer Steigerung, spürt sie, dass etwas geschieht, und addiert +2 auf weitere Widerstandsversuche für den Rest der Begegnung.", "Ist der Gedankenleser erfolgreich und das Ziel widersteht nicht, kann der Psioniker ihre oberflächlichen Gedanken und Gefühle erkennen. Eine Steigerung enthüllt mehr Informationen. Erfolg gegen jemanden, der den Superhelden anlügt, bedeutet zum Beispiel, dass er weiß, dass sie lügt. Eine Steigerung könnte ihr eine bessere Vorstellung davon geben, über welches allgemeine Thema sie lügt. Die Lüge selbst enthüllt sie nicht – das erfordert einen Tieftauchgang, siehe unten.", "Tieftauchgang: Es ist viel leichter, den komplexen menschlichen Geist zu durchsuchen, wenn das Ziel sediert, bewusstlos oder schlafend ist. Jeder Versuch gegen ein solches Opfer dauert 10 Minuten, steigert aber die gewonnenen Informationen stark. Erfolg gilt als Steigerung, und eine Steigerung bringt im Allgemeinen alles ans Licht, was der Psioniker wissen will. Misslingen verschwendet nur die Zeit des Psionikers – er kann es erneut versuchen. Ein Kritischer Fehlschlag schaltet den Geist des Opfers ab, und in dieser Begegnung ist kein weiterer Fortschritt möglich."], "m": [["GEDÄCHTNISMEISTERSCHAFT", "+3/+5", "Der Gedankenleser kann Erinnerungen verändern und reparieren. Der Superheld muss zunächst die Gedanken des Ziels mit einer Steigerung erfolgreich lesen. Wenn ja, kann er als Aktion eine kurze Erinnerung entfernen. Er könnte ein Ziel eine Begegnung vergessen lassen, dass sie je einen Bekannten getroffen hat und so weiter. Mit längerer Zeit (Entscheidung der SL, aber mindestens zehn Minuten) kann sie beliebig viele Erinnerungen entfernen. Mit 5 Punkten in der Kraft und dem oben beschriebenen Vorgehen kann sie neue Erinnerungen einpflanzen oder jene wiederherstellen, die durch diese Kraft, ein traumatisches Ereignis oder andere Mittel verändert wurden."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit dem Modifikator Reichweite kombiniert werden. Siehe S. 45 für weitere Informationen."], ["STARK", "+2", "Der Verstandwurf zum Widerstehen von Gedankenlesen wird mit einem zusätzlichen Abzug von –2 abgelegt."]], "s": ["SUP"], "p": 75, "k": [{"h": "Rätsel kurzschließen", "b": ["Gedankenkontrolle, Gedankenlesen und Objekt auslesen können schnell Informationen offenbaren, für die deine Spieler vielleicht etwas härter arbeiten sollen. Deshalb ist jede sorgfältig so gestaltet, dass sie nur begrenzte oder obskure Hinweise offenbart.", "Gedankenkontrolle lässt ein Opfer Befehlen widerstehen, die ihm oder seinen Verbündeten schaden – etwa zuzugeben, dass es ein Verbrechen begangen hat!", "Gedankenlesen erfordert Gefangennahme oder Sedierung, um mehr als oberflächliche Gedanken und Gefühle zu erlangen.", "Objekt auslesen gibt dem Superhelden vage Details, abhängig von verschiedenen Faktoren wie der Einzigartigkeit des Gegenstands oder seines früheren Trägers oder der Ereignisse, an denen er beteiligt war.", "Behalte das im Hinterkopf, wenn Charaktere ihre Fähigkeiten einsetzen. Erstick sie aber nicht völlig. Sie haben für die Kraft bezahlt und wollen diese Art Charakter spielen, und das sollte gefördert werden.", "Denke nur ein wenig nach, bevor du antwortest, wenn sie einen Geist oder ein Objekt untersuchen. Wenn du willst, dass sie die Informationen haben, um zur nächsten Szene zu gelangen, spiele es aus, lass sie ihre Kraft einsetzen und enthülle die Informationen. Wenn die Fähigkeit eines Ermittlers das Abenteuer verderben könnte, gib ihm Hinweise, die er mit etwas Nachdenken oder weiteren Ermittlungen zusammensetzen kann.", "Beispiel: Eine Super-Spürnase nutzt Objekt auslesen auf einem Messer, das im Rücken eines Mordopfers steckt. Die SL will, dass das Abenteuer sich darum dreht, die Identität des Mörders durch das Zusammensetzen von Hinweisen, die Interaktion mit Verdächtigen und gute altmodische Detektivarbeit herauszufinden. Sie gibt dem Helden mit Objekt auslesen einen vagen Eindruck von Vertrautheit, als das Messer in den Rücken des Opfers ging – der Tote kannte seinen Mörder! Das gibt dem Spieler einen wichtigen Hinweis, damit er sich belohnt fühlt, liefert weitere Beweise für den Fall und verrät das Rätsel nicht."]}]}, {"n": "Gedankenschild", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Konzentration, Training, Wahnsinn, Zen, starker Wille", "b": ["Der Geist der Heldin ist aus irgendeinem Grund besonders schwer zu manipulieren. Versuche, ihre Gedanken zu lesen oder zu kontrollieren, werden mit –2 abgelegt. Das ist kumulativ mit Umweltresistenz gegen den Machttyp Mental!", "Widersteht der Superheld außerdem erfolgreich einem Versuch, ihre Gedanken zu lesen oder zu kontrollieren, erleidet der feindliche Psioniker Erschöpfung. Mit einer Steigerung beim Widerstandswurf ist der Feind zusätzlich Betäubt."], "m": [["FLÄCHENEFFEKT", "+2/+4", "Für 2 Punkte kann Gedankenschild für alle in einer Mittleren Flächenschablone gelten, zentriert auf den Superhelden. Für 4 Punkte kann die Heldin ihren Schutz auf eine Große Flächenschablone ausdehnen."], ["STARK", "+2", "Versuche, die Gedanken des Supers zu lesen oder zu kontrollieren, werden mit –4 abgelegt."]], "s": ["SUP"], "p": 76}, {"n": "Handlanger", "r": 5, "mp": "2 pro Handlanger", "rw": "", "wd": "", "au": "Uniformierte Schläger, eine Bande, animierte Statuen, Roboter", "b": ["Jeder gute Schurke hat treue Handlanger, und die größten Helden scharen manchmal tapfere Gefolgsleute um sich. Manche Supers können sogar ihre eigenen Gefolgsleute erschaffen!", "Mehrere Handlanger: Diese Kraft kann mehr als einmal genommen werden. Jede Verwendung erschafft eine andere Gruppe Handlanger.", "Jede Stufe in Handlanger gibt eine treue Nebenfigur unter der Kontrolle des Spielers mit folgendem Grundprofil. Arbeite mit der SL zusammen, wenn du Eigenschaften anpassen willst.", "Attribute: Geschicklichkeit W6, Verstand W4, Willenskraft W6, Stärke W6, Konstitution W6", "Fertigkeiten: Athletik W6, Allgemeinwissen W6, Kämpfen W6, Fokus W6, Wahrnehmung W6, Überreden W4, Schießen W6, Heimlichkeit W6", "Handicaps: Loyal", "Talente: Superkräfte (5).", "Bewegungsweite: 6; Parade: 5; Robustheit: 5", "Ausrüstung: Handlanger können mit jeder Ausrüstung ausgestattet werden, die der Superheld für sie kaufen will. Beschworene Handlanger müssen Kräfte nutzen, um Ausrüstung nachzuahmen (Rüstung für Rüstung, Fernkampfangriff für Schusswaffen usw.).", "Ersatz: Wird ein Handlanger getötet, kann ein anderer angeheuert, gebaut, erschaffen usw. werden, um seinen Platz einzunehmen, wie es zur Ausprägung und Kampagne passt (meist innerhalb von 24 Stunden, vorausgesetzt, der Held kann Rekruten erreichen, bauen oder beschwören). (Herbeirufbare Handlanger werden anders ersetzt, siehe unten.)"], "m": [["ROBUST", "+1", "Die Handlanger sind Robust (siehe Sonderfähigkeiten in Savage Worlds)."], ["HERBEIRUFBAR", "+2", "Die Handlanger können aus dünner Luft herbeigerufen oder beschworen werden. Es könnten magische Wesen, Konstrukte oder Zombies sein, die aus der Erde kriechen. Das Herbeirufen von Handlangern erfordert einen Fokuswurf. Bei Erfolg erscheinen sie innerhalb von 6“ und können im nächsten Zug des Supers handeln. Eine Steigerung bedeutet, dass sie sofort handeln können. Ein Kritischer Fehlschlag bedeutet, dass diese Handlanger in dieser Begegnung nicht herbeigerufen werden können. (Jede Gruppe Handlanger muss separat herbeigerufen werden, wenn du diese Kraft mehr als einmal nimmst.) Die Handlanger können vom Erschaffer als freie Aktion aufgelöst werden. Kampfunfähigkeit: Wird ein herbeigerufener Handlanger Kampfunfähig oder getötet, verschwindet er, kann aber nach einer Stunde neu herbeigerufen werden. Alle herbeigerufenen Handlanger verschwinden sofort, wenn ihr Beschwörer Kampfunfähig wird."], ["SUPERKRÄFTE", "+3", "Für +3 Punkte haben alle Handlanger so viele Super-Machtpunkte wie das Machtlimit ihres Meisters (haben selbst aber kein Limit). Alle Handlanger einer Gruppe müssen dieselben Kräfte haben und können nie die Kräfte Duplizierung oder Handlanger nehmen."]], "s": ["SUP"], "p": 77}, {"n": "Negation", "r": 5, "mp": "3", "rw": "", "wd": "", "au": "Geräte, Magie, parasitäre Berührung", "b": ["Diese praktische und oft verheerende Fähigkeit erlaubt es deinem Helden, die Superkräfte eines Feindes zu negieren!", "Ein erfolgreicher Fokuswurf lässt ein Ziel innerhalb von 6“ (12 Metern) einen Willenskraftwurf ablegen (mit –2 bei einer Steigerung auf den Fokuswurf). Misslingt dem Opfer der Wurf, wählt der Angreifer eine Kraft zum Negieren. (Negation hat keine Wirkung auf Sonderfähigkeiten, die keine Superkräfte sind!)", "Das Opfer erhält zu Beginn jedes Zugs einen Willenskraftwurf mit –2 als freie Aktion, um die Negation abzuschütteln. Jeder Erfolg und jede Steigerung stellt eine Kraft zu ihrer vollen Fähigkeit wieder her."], "m": [["FLÄCHENEFFEKT", "+2/+4", "Für 2 Punkte kann der Angriff alle in einer Mittleren Flächenschablone betreffen. Für 4 Punkte kann der Held entweder eine Mittlere oder eine Große Flächenschablone verwenden. Ziele im Wirkungsgebiet widerstehen einzeln."], ["VOLLES SPEKTRUM", "+3", "Der Charakter schaltet für jeden Erfolg und jede Steigerung auf seinem Fokuswurf eine Kraft aus."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit den Modifikatoren Reichweite oder Flächeneffekt kombiniert werden. Siehe S. 45 für weitere Informationen."], ["STARK", "+2", "Die Willenskraftwürfe des Ziels werden mit einem zusätzlichen –2 abgelegt."]], "s": ["SUP"], "p": 77}, {"n": "Keine lebenswichtigen Organe", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Untote, außerirdische Physiologie, veränderte Form, Pflanzenmensch", "b": ["Der Held hat keine erkennbaren oder erreichbaren lebenswichtigen Organe wie Herz oder Gehirn. Gezielte Angriffe verursachen keinen zusätzlichen Schaden gegen sie."], "m": [], "s": ["SUP"], "p": 78}, {"n": "Objekt auslesen", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Psychische Abdrücke, mit Geistern sprechen, durch die Zeit blicken", "b": ["Der Held hat die Fähigkeit, ein Objekt zu „lesen“ und bestimmte Details über seine frühere Nutzung oder wichtige Ereignisse zu spüren, die in seiner Gegenwart geschahen.", "Um ein Objekt zu lesen, wählt der Superheld ein Ziel innerhalb von 6“ (12 Metern) und legt einen Fokuswurf ab. Ist er erfolgreich, erhält er einen vagen Eindruck der gesuchten Informationen. Mit einer Steigerung sind die Informationen klarer.", "Ein Objektleser kann nur versuchen, ein wichtiges Objekt oder die allgemeinen weltlichen Objekte in einem Gebiet einmal zu lesen. Misslingt es, kann er sich nicht auf diese Gegenstände einstimmen.", "Objekte tragen verschwommene und obskure Eindrücke. Sie vermitteln selten Details oder die genaue Identität ihrer Nutzer. Die Kraft liefert Hinweise, verdirbt aber selten das Rätsel. Eine bedeutende Reliquie wie Cortez’ Schwert oder der Mantel, den Lincoln beim Tod trug, kann weit lebhaftere Eindrücke haben – vielleicht wegen der psychischen Energie, die ein bedeutendes Ereignis darauf hinterlassen hat.", "Beispiel: Gabe findet einen Diamanten, den ein Juwelendieb bei einem Coup fallen ließ. Er nutzt Objekt auslesen darauf und erzielt eine Steigerung. Die SL sagt Gabe, dass der Dieb ein Kostüm trug und mit griechischem Akzent sprach. Gabe hat die Ahnung, dass der Dieb niemand anderes als die berühmte Medusa (S. 152) ist."], "m": [["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Objekt berühren, um es zu lesen. Das darf nicht mit dem Modifikator Reichweite kombiniert werden. Siehe S. 45 für weitere Informationen."]], "s": ["SUP"], "p": 78}, {"n": "Verschleiern", "r": 5, "mp": "4", "rw": "", "wd": "", "au": "Dunkelheit, Nebel, Dunst, Schneeblindheit, weißes Rauschen", "b": ["Der Held kann eine Kugel aus Dunkelheit, Licht, Dunst, Nebel, Rauch oder einem anderen immateriellen Feld erzeugen, das die Sicht verschleiert.", "Das Gebiet darin ist Dämmerlicht oder Dunkel (Wahl des Supers). Ziehe den Beleuchtungsmodifikator (–2 für Dämmerlicht, –4 für Dunkel) von Eigenschaftswürfen ab, die in der Kugel gemacht werden und auf Sicht beruhen (Entscheidung der SL); oder von Angriffen in die Kugel hinein, die von außen ausgehen.", "Die Kugel hat die Größe einer Großen Flächenschablone und kann bis zu 12“ (24 Meter) entfernt beschworen werden. Der Kontrolleur kann die Kugel als begrenzte freie Aktion um bis zu 12“ (24 Meter) pro Zug bewegen, solange ein Teil davon in Sichtweite bleibt."], "m": [["ZUSÄTZLICHER SINN", "+1", "Die Verschleierung kann jedes Mal, wenn dies genommen wird, einen zusätzlichen Sinn blockieren, gewählt aus: Hören, Riechen, Schmecken oder Fühlen. Der Held kann wählen, welche Sinne er aus all seinen möglichen Optionen verschleiert."], ["FLÄCHENEFFEKT", "+2", "Der Superheld kann das Wirkungsgebiet auf bis zu 25“ (50 Meter) Durchmesser vergrößern."], ["SELBST", "–1", "Der Effekt ist auf den Helden zentriert und bewegt sich mit ihr."], ["STARK", "+2", "Der Charakter kann die Verschleierung auf Finsternis (–6) steigern."]], "s": ["SUP"], "p": 78}, {"n": "Bewegungsweite", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Lange Beine", "b": ["Für echte Sprinter siehe Geschwindigkeit, S. 84. Für jene, die einfach schneller als die meisten sein wollen, nutze diese Fähigkeit. Sie erhöht die Grundbewegungsweite um +2 und den Laufwürfel eines Helden um einen Würfeltyp. Das ist kumulativ mit dem Talent Flinke Füße."], "m": [["SCHRITTMACHER", "+1", "Der Held ignoriert Schwieriges Gelände."]], "s": ["SUP"], "p": 78}, {"n": "Parade", "r": 5, "mp": "1–5", "rw": "", "wd": "", "au": "Klauen, mystische Schilde, schnelle Reaktionen, „sechster Sinn“", "b": ["Die Parade deines Charakters steigt jedes Mal, wenn diese Kraft genommen wird, um +1, bis zu einem Maximum von +5. Das ist kumulativ mit allen anderen Paradeboni von Waffen oder Fähigkeiten."], "m": [["ABLENKEN", "+2", "Einmal pro Zug, wenn der Held von einem Fernkampfangriff verfehlt wird, kann er versuchen, ihn mit einem Fokuswurf abzulenken. Ziehe 2 vom Wurf gegen Schusswaffen ab und 4 gegen Energiewaffen. Bei Erfolg wird der Angriff auf den ursprünglichen Angreifer umgeleitet. Mit einer Steigerung kann der Held ihn auf ein beliebiges anderes verfügbares Ziel nach Wahl des Charakters umleiten. In beiden Fällen trifft der Angriff automatisch, kann aber nie mit einer Steigerung treffen. Flächenangriffe können im Allgemeinen nicht abgelenkt werden, aber die SL kann es erlauben, wenn der Angriff eine Granate, Rakete oder ein ähnliches Objekt ist, das umgeleitet werden könnte."], ["BESCHÜTZER", "+2", "Der Charakter kann einen beliebigen Teil oder alles seines Paradekraft-Bonus (aber nicht anderer Paradeboni) an angrenzende Verbündete geben. Das ist eine freie Aktion."]], "s": ["SUP"], "p": 78}, {"n": "Gift", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Gift, bestrichene Klingen, Schmutz", "b": ["Gift ist normalerweise die Domäne von Schurken, aber manche Helden nutzen es, um ihre Feinde zu schwächen und kampfunfähig zu machen.", "Ein erfolgreicher Fokuswurf lässt ein Ziel innerhalb von 6“ einen Konstitutionswurf ablegen (mit –2 bei einer Steigerung auf den Fokuswurf). Misslingt dem Opfer der Wurf, erleidet es eine Stufe Erschöpfung.", "Zu Beginn seines nächsten Zugs muss es einen weiteren Konstitutionswurf ablegen. Misslingen führt zu einer weiteren Stufe Erschöpfung. Erfolg wehrt weitere Wirkungen in dieser Runde ab, aber das Opfer muss in seinem nächsten Zug erneut würfeln. Mit einer Steigerung gibt es keine weitere Wirkung, und das Opfer wird für den Rest der Begegnung immun gegen alle weiteren Wirkungen dieses Angreifers.", "Erschöpfung wird normal erholt (siehe Savage Worlds). Erschöpfung durch Gift kann Kampfunfähigkeit verursachen, aber nicht den Tod."], "m": [["FLÄCHENEFFEKT", "+2/+4", "Für 2 Punkte kann der Angriff alle in einer Mittleren Flächenschablone betreffen. Für 4 Punkte kann der Held entweder eine Mittlere oder eine Große Flächenschablone verwenden. Ziele im Wirkungsgebiet widerstehen einzeln."], ["TÖDLICH", "+1", "Erschöpfung durch Gift kann zum Tod führen."], ["STARK", "+2", "Die Konstitutionswürfe des Ziels werden mit einem zusätzlichen –2 abgelegt."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit den Modifikatoren Reichweite oder Flächeneffekt kombiniert werden. Siehe S. 45 für weitere Informationen."]], "s": ["SUP"], "p": 79}, {"n": "Besessenheit", "r": 5, "mp": "5", "rw": "", "wd": "", "au": "Geister, Seelentausch", "b": ["Diese Fähigkeit erlaubt es einem superbegabten Wesen, den Körper eines anderen zu besetzen und zu kontrollieren.", "Ein erfolgreicher Fokuswurf lässt ein Ziel innerhalb von 6“ (12 Metern) einen Willenskraftwurf ablegen (mit –2 bei einer Steigerung auf den Fokuswurf). Misslingt dem Opfer der Wurf, ist es besessen, und der Kontrolleur kann seinen Körper wie seinen eigenen nutzen.", "Zu Beginn jedes folgenden Zugs legt das Opfer einen Willenskraftwurf ab (mit –2 bei einer Steigerung auf den ursprünglichen Fokuswurf), um sich zu erholen. Bei Erfolg erholt es sich, ist aber Betäubt. Mit einer Steigerung erholt es sich und ist Angeschlagen.", "Der Körper des Kontrolleurs sackt zusammen, wenn er einen anderen übernimmt, daher sollte man sicherstellen, dass er von einem Freund geschützt wird. Der Kontrolleur behält die Fähigkeit, Besessenheit zu nutzen, verliert aber den Zugriff auf alle seine anderen Kräfte, während er einen anderen besitzt.", "Opfer von Besessenheit sind sich ihrer Handlungen unter Kontrolle voll bewusst (es sei denn, der Superheld nimmt den Modifikator Vergesslich unten).", "Wird das Opfer Kampfunfähig, kehrt die Seele des Supers in ihrem nächsten Zug in ihren eigenen Körper zurück, und er kann normal handeln. Wird das Opfer getötet, kehrt er zurück, ist aber Betäubt."], "m": [["VERGESSLICH", "+2", "Das Opfer erinnert sich nicht, was geschah, als es besessen war."], ["ERINNERUNGEN", "+2", "Der Besessene hat Zugriff auf alle Erinnerungen des Opfers."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Superheld muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit dem Modifikator Reichweite kombiniert werden (siehe S. 45)."], ["STARK", "+2", "Die Willenskraftwürfe des Ziels werden mit einem zusätzlichen –2 abgelegt."]], "s": ["SUP"], "p": 79}, {"n": "Stoßen", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Ein Windstoß, telekinetische Kraft, ein Energiestoß, eine riesige Hand", "b": ["Manchmal will ein Held einfach seine Feinde wegräumen, Formationen stören oder einen Weg für seine Verbündeten zu einer Sicherheit oder einem kritischen Ziel schaffen.", "Mit einem Fokuswurf beschwört der Superheld eine mächtige Kraft in Form der Kegelschablone. Die Spitze des Kegels kann irgendwo innerhalb einer Reichweite von Verstand platziert werden, sodass der Superheld Feinde in jede Richtung zum großen Ende des Kegels schieben kann.", "Jeder in der Schablone ist Abgelenkt (nimm den Modifikator Selektiv, um Verbündete nicht zu beeinflussen) und muss einen Stärkewurf ablegen oder wird W6“ zurückgeschleudert. Mit einer Steigerung wird der Stärkewurf mit –2 abgelegt, und wer misslingt, wird 2W6“ zurückgeschleudert. Siehe Rückstoß auf S. 30."], "m": [["STARK", "+2", "Die Stärkewürfe des Ziels werden mit –2 abgelegt (kumulativ mit Abgelenkt), und die Rückstoßweite steigt auf 2W6."]], "s": ["SUP"], "p": 80}, {"n": "Fernkampfangriff", "r": 5, "mp": "Speziell", "rw": "", "wd": "", "au": "Blitze, Explosionen, Feuer, Wasser, Hightech-Waffen", "b": ["Der Superheld hat einen Fernkampfangriff mit einer Reichweite von 12/24/48. Siehe die Tabelle unten für Kosten und Schaden.", "Der Held entscheidet beim Kauf, welche Eigenschaft sein Angriff nutzt, typischerweise Athletik für Wurfwaffen, Fokus für Energieblitze, Schießen für Geräte oder Zaubern für magische Angriffe.", "Fernkampfangriff-Modifikatoren: Welche Fertigkeit auch immer für diese Kraft genutzt wird, unterliegt allen üblichen Regeln für Fernkampfangriffe, einschließlich Reichweite, Deckung, Beleuchtung usw."], "m": [["PANZERBRECHEND", "+1", "Jeder Punkt in diesem Modifikator gibt dem Angriff zwei Punkte DB, bis zu einem Maximum von 10."], ["FLÄCHENEFFEKT", "+2/+4", "Für 2 Punkte kann der Angriff ein Gebiet von der Größe einer Mittleren Flächenschablone betreffen. Für 4 Punkte kann der Held entweder eine Mittlere oder eine Große Flächenschablone verwenden. Ziele im Wirkungsgebiet dürfen ausweichen (mit einem zusätzlichen –2 bei einer Steigerung auf den Angriffswurf)."], ["AUFLADEN", "+1", "Der Held kann seinen Angriff als begrenzte Aktion „aufladen“ und +1W6 auf den ersten Schadenswurf in seiner nächsten Aktion addieren (oder +1W10, wenn mit Alles auf eine Karte (S. 30) kombiniert)."], ["KEGEL", "+0/+1", "Für keine Punkte muss der Angriff die Kegelschablone nutzen, die vom Superhelden ausgeht. Für 1 Punkt kann der Angriff wie üblich zwischen der Kegelschablone und anderen Verwendungen wechseln."], ["TÖDLICH", "–1", "Der Angriff ist von Natur aus tödlich. Er kann diese Kraft nicht für Nicht-tödliche Angriffe nutzen (siehe Savage Worlds)."], ["FEUERRATE", "+3/+6", "Der Angriff des Helden hat Feuerrate 2 für 3 Punkte oder Feuerrate 3 für sechs. Diese Angriffe haben keinen Rückstoßabzug."], ["MATERIAL ERFORDERLICH", "–2", "Der Charakter greift an, indem er Materie schleudert oder manipuliert. Ist keine in der Nähe, kann er seinen Fernkampfangriff nicht nutzen."], ["STREUUNG", "+1", "Der Angriff ist breit oder ein Strom, der es leichter macht, Freunde und Feinde gleichermaßen zu treffen. Der Angriffswurf erhält +2, trifft aber bei einer 1 oder 2 Unbeteiligte, wenn der Angriff verfehlt."]], "s": ["SUP"], "p": 80, "tab": {"c": ["Schaden", "Kosten"], "r": [["2W6", "3"], ["3W6", "6"], ["4W6", "9"], ["5W6", "12"], ["6W6", "15"]], "nach": 3}}, {"n": "Reichweite (Nahkampf)", "r": 5, "mp": "1–3", "rw": "", "wd": "", "au": "Lange Glieder, Dehnbarkeit, Tentakel, außerirdische Physiologie", "b": ["Die natürlichen Glieder des Helden haben eine Reichweite von +1 bis +3. Das wird oft mit Veränderte Form (S. 49) für dehnbare Charaktere kombiniert."], "m": [], "s": ["SUP"], "p": 81}, {"n": "Regeneration", "r": 5, "mp": "2/5/10", "rw": "", "wd": "", "au": "Mächtige Untote, mutierter Heilfaktor, Magie", "b": ["Ob die Heldin selbstheilendes Fleisch und Blut oder fortschrittliche Technik hat, sie heilt in erstaunlich kurzer Zeit.", "Für 2 Punkte legt sie alle 24 Stunden als begrenzte freie Aktion einen Fokuswurf ab. Erfolg heilt eine Wunde, eine Steigerung heilt zwei. Für 5 Punkte darf sie jede Stunde versuchen zu heilen. Für 10 Punkte darf sie in jeder Runde versuchen zu heilen (eine freie Aktion)!", "Charaktere können keine Wunden regenerieren, die durch einen Machttyp verursacht wurden, der ihrer Umweltschwäche, Kraftnegation oder ihrem Handicap Verwundbar entspricht. Diese Wunden können aber natürlich oder durch Kräfte wie Heilung heilen.", "Ausgeschaltet: Kampfunfähige Helden mit Regeneration heilen weiter, bleiben aber eine Stunde bewusstlos (oder bis ihnen ein Joker ausgeteilt wird, wenn sie noch im Kampf sind).", "Wiederbelebung: Siehe Heilung, S. 65."], "m": [["ZERSTÖRUNG", "–1", "Wunden durch Säure, Feuer oder Desintegration können nicht regeneriert werden."], ["LINDERUNG", "+2", "Der Held ignoriert einen Punkt Erschöpfungsabzüge. Er kann immer noch Kampfunfähig werden, wenn er über Ausgezehrt hinaus getrieben wird – er ignoriert nur den Abzug."], ["NACHWACHSEN", "+2", "Der Charakter kann sich von schwerem traumatischem Schaden erholen. Behandle alle bleibenden Verletzungen als vorübergehend, es sei denn, sie wurden durch Säure, Feuer oder einen Machttyp verursacht, der seiner Umweltschwäche, Kraftnegation oder seinem Handicap Verwundbar entspricht."]], "s": ["SUP"], "p": 81, "k": [{"h": "„Schreiben“ der Regeln", "b": ["Hier ist ein kleines Geheimnis. Comicautoren schummeln. Batman würde Superman „im echten Leben“ nie konsequent besiegen. Der Dunkle Ritter könnte den Mann aus Stahl einmal überrumpeln, vielleicht sogar zweimal. Aber sobald Supes weiß, dass er kommt, wäre der Rächer im Umhang erledigt. Superman kann je nach Ära und Autor mit oder jenseits der Lichtgeschwindigkeit fliegen, also hat kein Mensch, egal wie gut trainiert, eine Chance dagegen.", "Deshalb ist jeder Versuch, die bekannten Superhelden und Schurken der Comics systematisch zu bewerten, grundsätzlich fehlerhaft. Die Kräfte der Helden hängen vom Autor ab, von den Bedürfnissen der Handlung und davon, wer der Protagonist ist – nicht von einer Tabelle, wer am stärksten und schnellsten ist. Was ist der Punktwert von „Batman steckt bis zum Ende der Geschichte Prügel ein, gewinnt dann aber immer“? Oder „Wenn Batman und Superman kämpfen, gewinnt immer Batman“?", "Das ist in Ordnung, und das solltest du im Spiel annehmen. Tatsächlich haben wir deshalb explodierende Würfel – weil alles passieren kann – und Kraftstunts. Das große Geheimnis der Comics ist dasselbe wie in guten Rollenspielkampagnen. Clevere Aktionen, die gute Geschichten ergeben, sollten belohnt werden. Das heißt nicht, dass sie immer funktionieren, aber sie sollten eine Chance haben.", "Die besten Comics sind die, in denen die Helden ihre Kräfte oder ihren Verstand einsetzen müssen, um ihre Feinde zu überlisten, etwa wenn der Unbesiegbare Iron Man seinen Blaster auf genau die Energieart „kalibriert“, gegen die sein Gegner am schwächsten ist. Oder wenn Spider-Man Juggernaut in eine riesige Betongrube lockt – die einzige Chance, die der Wandkrabbler gegen einen Feind hatte, der für seine Fäuste viel zu mächtig war.", "Versuche als Spielleiter, deine Spieler zu ermutigen, in diesen Begriffen zu denken und Neues auszuprobieren, statt nur Angriffe zu würfeln und auf einen hohen Schadenswurf zu hoffen. Das ist auch cool, aber ein „Schreiben“ der Geschichte kann einen denkwürdigen Moment schaffen, der für immer bleibt."]}]}, {"n": "Scan", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Tiersinne, Hightech-Sensoren, mentale Scans", "b": ["Der Super kann Ziele, Objekte oder Phänomene wahrnehmen, die aus einem bestimmten Machttyp bestehen oder ihn nutzen.", "Ein Scanner, der den Machttyp Biologisch wählt, kann zum Beispiel die Anwesenheit von Menschen, Tieren, Untoten und so weiter erkennen. Hätte er auch Elektrizität gewählt, könnte er Stürme, Stromleitungen oder einen Schurken spüren, der Blitze aus seinen Händen schießt.", "Als Aktion gibt die Kraft die allgemeine Richtung jeder bedeutenden Quelle dieses Machttyps innerhalb einer Meile an. Verbringt der Scanner eine ganze Minute mit einem „Tiefenscan“, erhöht er seine Reichweite um das 10-Fache. Das sagt dem Scanner nicht, welche dieser Quellen die gesuchte ist – dafür dient Kalibrierung."], "m": [["ZUSÄTZLICHER MACHTTYP", "+1", "Der Held kann nach einem zusätzlichen Machttyp scannen. Das kann mehrfach genommen werden, jedes Mal mit einem anderen Machttyp."], ["KALIBRIERUNG", "+2", "Hat der Super etwas, das einem Ziel gehörte oder in irgendeiner Weise Teil davon war, oder hatte er zuvor persönlichen Kontakt mit diesem Wesen oder Objekt, kann er es beim Scannen aus allen anderen dieses Machttyps herausfinden."], ["DISTANZ", "+1/+2", "Für +1 Punkt steigt die Scanreichweite von 1 Meile auf 10 Meilen. Für +2 Punkte steigt die Grundreichweite auf 100 Meilen."], ["SPURENSUCHER", "+1", "Der Spurensucher kann Anzeichen des Vorbeikommens des Ziels wahrnehmen, wenn es in der letzten Woche in Reichweite war."]], "s": ["SUP"], "p": 82}, {"n": "Gestaltwandeln", "r": 5, "mp": "2 pro Stufe", "rw": "", "wd": "", "au": "Tiertotems oder Tätowierungen, Halskette mit Klauen oder Zähnen, wildes Aussehen, Schamanen", "b": ["Diese Kraft erlaubt es einem Helden, sich in verschiedene natürliche Tiere zu verwandeln. Wer exotischere Verwandlungen will, sollte jede Gestalt als Kraftset erschaffen (siehe S. 47).", "Die Grundkosten der Kraft betragen 2 pro Stufe. Jede Stufe erlaubt es einem Super, sich in ein natürliches Geschöpf zu verwandeln, das einen Punkt größer oder kleiner ist. Ein Held der Größe 0 mit vier Stufen in Gestaltwandeln könnte sich zum Beispiel in ein Geschöpf von Größe –4 bis Größe +4 verwandeln.", "Die Gestalt zu wechseln ist eine Aktion und erfordert einen Fokuswurf. Gelingt er, erhält der Gestaltwandler die körperlichen Attribute und Fertigkeiten des Tiers und alle Sonderfähigkeiten (ob höher oder niedriger). Sie kann nicht sprechen, keine Gegenstände nutzen, die menschliche Gestalt oder Finger erfordern, und ihre eigenen Kräfte nicht aktivieren (es sei denn, sie nimmt den Modifikator Kräfte unten).", "Wunden: Ab Großem Maßstab und darüber gewährt Gestaltwandeln dem Helden zusätzliche Wunden. Wunden, die in Großem Maßstab oder darüber genommen wurden, werden getrennt verfolgt. Verringert ein Held seine Größe unter diesen Maßstab und hätte mehr als seine Kapazität, ist er Kampfunfähig. Kehrt er in einen größeren Maßstab zurück, bleiben seine Verletzungen.", "Beispiel: Ein Held erleidet vier Wunden in der Gestalt eines Großen Weißen Hais. Später kehrt er in seine menschliche Gestalt (Normaler Maßstab) zurück, wo er nur drei Wunden verkraften kann, also hat er drei Wunden und ist Kampfunfähig. Wird er geweckt und kehrt ungeheilt in die große Gestalt zurück, hat er immer noch vier Wunden. Könnte er vier Wunden verkraften (durch das Talent Zäh wie Leder), behielte er alle vier auch in seiner menschlichen Gestalt.", "Herunterfahren: Gestaltwandeln endet, wenn der Super die Konzentration verliert. Siehe Herunterfahren auf S. 42."], "m": [["KRÄFTE", "+4", "Sofern die Gestalt des Charakters es nicht irgendwie verhindert (ein Nilpferd kann keinen Bogen abfeuern), kann er seine Kräfte in seiner Tiergestalt nutzen."], ["URTÜMLICH", "–4", "Der Charakter übernimmt alle Eigenschaften des Tiers, einschließlich geistiger und seelischer Attribute und Fertigkeiten. Er behält nur seinen Fokus und genug Bewusstsein, um zu wissen, dass er in seine menschliche Gestalt zurückwechseln kann, wer seine Freunde und Feinde sind usw."], ["BEIBEHALTUNG", "+4", "Der Charakter behält bei der Verwandlung die jeweils höhere körperliche Eigenschaft – seine oder die des Tiers."], ["SPRECHEN", "+1", "Der Charakter kann in Tiergestalt sprechen."]], "s": ["SUP"], "p": 82}, {"n": "Schrumpfen", "r": 5, "mp": "4", "rw": "", "wd": "", "au": "Schrumpfpillen, magische Worte, mutierter Stoffwechsel", "b": ["Diese Kraft erlaubt es dem Helden, kleiner zu werden. Er kann seine Größe um bis zu zwei Punkte verringern (auf Klein). Siehe die Größentabelle in Savage Worlds für Körpergrößen und Gewichte und Maßstab für Angriffsmodifikatoren. Der Charakter behält seinen normalen Stärkewürfel, erleidet aber –1 auf Stärkewürfe (einschließlich Nahkampfschaden) pro verringertem Größenpunkt. Die Größe zu ändern (in beide Richtungen) ist eine begrenzte Aktion."], "m": [["DICHTE", "+5", "Die Robustheit des Charakters sinkt nicht, wenn er kleiner ist, und er erleidet keinen Abzug auf Stärkewürfe wegen der Größe."], ["MIKROSKOPISCH", "+3", "Der Charakter muss den Modifikator Kleiner +16 haben, um diesen zu nehmen. Dann kann er die Größe eines Keims annehmen. In dieser Gestalt kann er die normale Welt im Allgemeinen nicht beeinflussen und wird nicht von ihr beeinflusst. Nicht einmal Giftgas wirkt in dieser Größe auf ihn. Er kann fast jeden Ort völlig unbemerkt betreten (selbst die meisten „luftdichten“ Anlagen bieten kein Hindernis), durch den menschlichen Körper reisen und so weiter. Geschöpfe in diesem „Mikrouniversum“ haben verhältnismäßig gleichwertige Stärke, Robustheit und andere Kräfte, wie es sich für eine Comicwelt gehört."], ["SCHNELLWECHSEL", "+1", "Der Charakter kann als begrenzte freie Aktion schrumpfen (oder wieder wachsen)."], ["KLEINER", "+8/+16", "Für +8 Punkte kann der Charakter seine Größe um drei Punkte verringern (auf Sehr Klein). Für +16 Punkte kann er seine Größe um vier Punkte verringern (auf Winzig)."]], "s": ["SUP"], "p": 83}, {"n": "Fertigkeitsbonus", "r": 5, "mp": "2/4", "rw": "", "wd": "", "au": "Extremes Training, chemische Pheromone, frühere Leben", "b": ["Mit dieser Kraft ist der Held in etwas besonders gut. Er könnte ein Meisterschütze sein, ein hervorragender Schwertkämpfer, ein berühmter Zauberer oder der größte Detektiv der Welt.", "Wähle jedes Mal, wenn diese Kraft genommen wird, eine Fertigkeit. Der Spieler addiert +1 auf sein Gesamtergebnis, wann immer diese Fertigkeit aus irgendeinem Grund gewürfelt wird (oder +2 für +4 Punkte).", "Fertigkeitsbonus zählt als eine einzige Kraft, egal wie oft er genommen wird. Das heißt, ein Held der Stufe II mit einem Machtlimit von 10 kann zum Beispiel insgesamt nicht mehr als 10 Punkte für alle seine Fertigkeitsboni ausgeben."], "m": [], "s": ["SUP"], "p": 83}, {"n": "Verlangsamen", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Zeitverlangsamung, verschwommene Bewegung, eine rutschige Öl- oder Eisfläche", "b": ["Verlangsamen erlaubt es einem Helden, einen Fokuswurf gegen ein Ziel innerhalb von 12“ (24 Metern) abzulegen. Bei Erfolg halbiert sie die Bewegungsweite des Ziels. Mit einer Steigerung macht sie Bewegung zu einer Aktion. Das hält bis zum Ende des nächsten Zugs des Ziels an."], "m": [["ZUSÄTZLICHE ZIELE", "+1", "Die Kraft kann für je 1 zusätzlichen Super-Machtpunkt mehr als ein Ziel betreffen."]], "s": ["SUP"], "p": 83}, {"n": "Raumfahrer", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Raumanzug, kosmische Anpassung, Gadgets", "b": ["Der Charakter kann im Weltraum und unter Wasser überleben. Raumfahrer gewährt nicht die Kraft Umweltresistenz oder irgendeinen anderen Spieleffekt – es erlaubt dem Helden nur, irgendwie zu überleben.", "Raumfahrer können einen Mangel an Sauerstoff in diesen beiden Umgebungen irgendwie ignorieren, atmen aber, wo möglich, weiterhin und werden daher von giftigen Gasen oder anderen Gefahren betroffen. (Nimm die Kraft Atmet nicht, S. 58, um das Atmen tatsächlich zu ignorieren.)", "Schwerelosigkeit: Charaktere erleiden in Schwerelosigkeit einen Abzug von –2 auf Geschicklichkeit und darauf basierende Fertigkeiten. Wenn die Kampagne je in den Weltraum führt, ignoriert dieser Held den Abzug."], "m": [["AKTIVIERUNG ERFORDERLICH", "–1", "Der Held muss einen Fokuswurf als Aktion ablegen, um diese Fähigkeit zu aktivieren. Verliert er die Konzentration, fährt sie herunter und muss neu aktiviert werden (siehe S. 42)."], ["ÜBERTRAGBAR", "+1", "Jedes Mal, wenn dieser Modifikator genommen wird, kann der Charakter die Raumfahrer-Kraft einer anderen Person gewähren. Die Verbündeten müssen innerhalb von 12“ (24 Metern) bleiben. Entfernen sie sich, oder wird der ursprüngliche Raumfahrer Kampfunfähig, endet der Schutz sofort."]], "s": ["SUP"], "p": 83}, {"n": "Sprachen sprechen", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Geräte, oberflächliches Gedankenlesen, schlummernde Fertigkeiten", "b": ["Der Held kann jede Sprache sprechen. Ist es eine, die er nie zuvor gehört hat, wird er in Minuten gesprächsfähig und in wenigen Stunden fließend."], "m": [["SCHRIFTSPRACHE", "+1", "Er kann auch jede Sprache lesen und schreiben, mit ein paar Minuten und einigen Beispielen."]], "s": ["SUP"], "p": 84}, {"n": "Geschwindigkeit", "r": 5, "mp": "3–17", "rw": "", "wd": "", "au": "Ein verschwommener Schemen, kräftige Beine", "b": ["Dieser Sprinter kann mit unglaublicher Geschwindigkeit laufen und über das Schlachtfeld oder vielleicht sogar den Globus rasen, im Nu!", "Angriffsabzug: Der Angriffsabzug wird von allen Nah- oder Fernkampfangriffen gegen den Helden abgezogen, solange er sich relativ frei bewegen kann (nicht Gefesselt, Verstrickt oder in einem engen Raum). Das ist kumulativ mit allen anderen Angriffsabzügen durch Kräfte oder Talente, außer Flug, bis zu einem Maximum von –10.", "Außer Kontrolle: Wird ein Sprinter beim Laufen Angeschlagen, Betäubt oder Verwundet und befindet er sich in einer Umgebung, in der er ein Hindernis treffen könnte, muss er einen Athletikwurf mit –2 ablegen oder kollidiert mit einem Schaden von 2W6+XW6, wobei X sein unmodifizierter Angriffsabzug als positiver Wert ist."], "m": [["WENDIG", "+1", "Du würfelst 2W6, um in einer taktischen Umgebung zu „laufen“, statt 1W6."], ["TRAKTIEREN", "+4", "Der Super kann einen Gegner mit einer Vielzahl schneller Schläge traktieren und +4 auf einen Kämpfenangriff pro Zug addieren."], ["OBERFLÄCHENSPANNUNG", "+1", "Dieser Modifikator erfordert mindestens Schallgeschwindigkeit. Damit kann der Charakter über Wasser oder sogar an den Seiten von Gebäuden auf und ab laufen. Der Sprinter darf nicht aufhören, sich zu bewegen, sonst sinkt er oder fällt."], ["VIBRIEREN", "+5", "Dieser Modifikator erfordert die Stufe Beinahe-Lichtgeschwindigkeit. Der Sprinter kann seine Moleküle so schnell vibrieren lassen, dass er tatsächlich durch feste Objekte hindurchgehen kann. Das erfordert einen Fokuswurf mit –2. Gelingt er, geht er durch das Hindernis, hält aber auf der anderen Seite an und bewegt sich nicht mehr (Gegner ignorieren seinen Angriffsabzug). Mit einer Steigerung bewegt er sich weiter, aber die verbleibende Bewegungsweite wird halbiert. Der Charakter darf nie in einem Objekt anhalten."], ["UNGELENK", "–2", "Dieser Modifikator darf nur genommen werden, wenn die Geschwindigkeit des Supers Bewegungsweite 45 oder höher beträgt. Sie kann in gerader Linie leicht laufen, hat aber Probleme mit Wendungen und Manövrieren, was ihren Angriffsabzug um 2 verringert. Bewegt sie sich zum Beispiel mit Überschallgeschwindigkeit, beträgt ihr Angriffsabzug –6 statt der üblichen –8. Die Heldin legt außerdem ihre Athletikwürfe zur Vermeidung von Kollisionen mit –4 ab. Du darfst Ungelenk nicht nehmen, wenn du Wendig genommen hast."]], "s": ["SUP"], "p": 84, "tab": {"c": ["Punkte", "Geschwindigkeit", "Angriffsabzug"], "r": [["3", "Bewegungsweite 12 (8 mph)", "0"], ["4", "Bewegungsweite 24 (16 mph)", "0"], ["5", "Bewegungsweite 45 (30 mph)", "0"], ["7", "Bewegungsweite 90 (60 mph)", "–1"], ["9", "Bewegungsweite 180 (120 mph)", "–2"], ["11", "Bewegungsweite 360 (240 mph)", "–4"], ["13", "Schallgeschwindigkeit (1.200 mph)", "–6"], ["15", "Überschallgeschwindigkeit (2.400 mph)", "–8"], ["17", "Beinahe-Lichtgeschwindigkeit (240 Mio. mph)", "–10"]], "nach": 2}}, {"n": "Betäuben", "r": 5, "mp": "3", "rw": "", "wd": "", "au": "Elektrischer Angriff, mildes Toxin, mentale Peitsche, ohrenbetäubende Sirene", "b": ["Verkleidete Gutmenschen, die niemanden verletzen wollen, können ihre Ziele stattdessen betäuben. Ein erfolgreicher Fokuswurf lässt ein Ziel innerhalb von 6“ (12 Metern) einen Konstitutionswurf ablegen (mit –2 bei einer Steigerung auf den Fokuswurf). Misslingt er dem Opfer, ist es Betäubt (siehe Savage Worlds)."], "m": [["FLÄCHENEFFEKT", "+2/+4", "Für +2 Punkte kann die Kraft ein Gebiet von der Größe einer Mittleren Flächenschablone betreffen. Für +4 Punkte kann der Held entweder eine Kegel-, Mittlere oder Große Flächenschablone verwenden. Ziele im Wirkungsgebiet widerstehen einzeln."], ["BERÜHRUNG ERFORDERLICH", "–2", "Der Super muss das Opfer berühren, um es zu beeinflussen. Das darf nicht mit den Modifikatoren Reichweite oder Flächeneffekt kombiniert werden. Siehe S. 45 für weitere Informationen."], ["STARK", "+2", "Die Konstitutionswürfe des Ziels werden mit einem zusätzlichen –2 abgelegt."]], "s": ["SUP"], "p": 85}, {"n": "Superattribut", "r": 5, "mp": "2 pro Stufe", "rw": "", "wd": "", "au": "Übernatürliche Reflexe (Geschicklichkeit), massives Gehirn (Verstand), Powerrüstung (Stärke), religiöse Überzeugung (Willenskraft), unglaubliche Konstitution (Konstitution)", "b": ["Diese Kraft erhöht ein gewähltes Attribut pro Stufe um einen Würfeltyp. Das wirkt sich auch auf abgeleitete Werte wie Robustheit aus. Runde ab, wenn der Wert W12 übersteigt (W12+1 Konstitution ist Robustheit 8). Jede Stufe in Superattribut hebt auch das Maximum des Attributs um denselben Betrag.", "Jedes betroffene Attribut ist eine eigene Kraft und unterliegt daher einzeln dem Machtlimit der Kampagne."], "m": [["NICHT HEUTE", "+2", "Einmal pro Sitzung kann der Charakter eines ihrer Superattribute für einen beliebigen anderen Attributswurf einsetzen (nicht für Fertigkeitswürfe). Ein superstarker Charakter könnte Stärke nutzen, um Schaden aufzufangen (indem er die Faust des Angreifers packt, wenn sie ankommt), oder ein superintelligenter Schurke könnte Verstand nutzen, um sich aus Verstricken zu befreien (indem er den Faden findet, der das Ganze auflöst)."]], "s": ["SUP"], "p": 85}, {"n": "Supertalent", "r": 5, "mp": "2 pro Stufe", "rw": "", "wd": "", "au": "Außergewöhnliches Training oder Hintergrund, Erweiterung der Superkräfte", "b": ["Jedes Mal, wenn diese Kraft genommen wird, erhält der Charakter ein nicht-legendäres Talent (unabhängig vom Rang des Helden). Er muss die Voraussetzungen des Talents wie üblich erfüllen."], "m": [], "s": ["SUP"], "p": 85}, {"n": "Superfertigkeit", "r": 5, "mp": "1 pro Stufe", "rw": "", "wd": "", "au": "Natürliches Genie, Softwareprogramme, intensives Training", "b": ["Superfertigkeit kauft oder erhöht eine Fertigkeit (und ihr Maximum) pro Stufe um einen Würfeltyp. Das spiegelt extremes Training, Talent oder übernatürliche Verstärkung irgendeiner Art wider.", "Superfertigkeit zählt als eine einzige Kraft, egal wie viele Fertigkeiten betroffen sind. Das heißt, ein Held der Stufe I mit einem Machtlimit von 5 kann zum Beispiel nicht mehr als 5 Punkte für alle seine Superfertigkeiten ausgeben.", "Jede Stufe kostet einen Punkt, unabhängig vom verknüpften Attribut, und erhöht alle abgeleiteten Werte wie Parade."], "m": [], "s": ["SUP"], "p": 86}, {"n": "Superwissenschaft", "r": 5, "mp": "4", "rw": "", "wd": "", "au": "Superhirn, fortgeschrittene Ausbildung, technologisches Können", "b": ["Superwissenschaftler erschaffen spontan fantastische Technologie und basteln Gizmos und Gadgets zusammen, die weit über dem Techniklevel der gewöhnlichen Welt liegen, in der sie leben!", "Gibt eine Superwissenschaftlerin einen Bennie für einen Kraftstunt aus (S. 30), muss sie die neue Kraft nicht auf einer ihrer bestehenden Kräfte aufbauen wie andere Helden – sie kann ein Gerät „erfinden“, das auf jeder Kraft im Buch basiert.", "Die Kosten der Erfindung in Super-Machtpunkten dürfen wie üblich das Machtlimit der Kampagne nicht übersteigen. Sie kann außerdem aktive Kräfte zwei Runden statt einer und passive Kräfte fünf Runden statt drei nutzen.", "Voraussetzung: Ein Charakter muss Wissenschaft W10 oder höher haben, um diese Kraft zu nehmen."], "m": [["ÜBERLAST", "–1", "Würfelt der Super mit der gestuntenen Kraft (nicht der ursprünglichen) einen Kritischen Fehlschlag, explodiert ihr Gerät spektakulär und verursacht 3W6 Schaden in einer Mittleren Flächenschablone. Unabhängig von der verbleibenden Dauer endet der Kraftstunt sofort. Sie kann als Aktion ein neues „erschaffen“."]], "s": ["SUP"], "p": 86}, {"n": "Superzauberei", "r": 5, "mp": "4", "rw": "", "wd": "", "au": "Magier- oder Priesterroben, Zauberstäbe, Hexen, Hexenmeister, Halbgötter, Avatare uralter Götter", "b": ["Superzauberer kanalisieren übernatürliche Energien, um beliebig viele arkane oder göttliche Zauber zu wirken. Sie könnten ihre Kräfte angeboren haben, aus alten Büchern beziehen oder von mächtigeren Wesen kanalisieren.", "Gibt ein Superzauberer einen Bennie für einen Kraftstunt aus (S. 30), muss er die neue Kraft nicht auf einer seiner bestehenden Kräfte aufbauen wie andere Helden – er kann einen „Zauber“ wirken, der auf jeder Kraft im Buch basiert!", "Die Kosten des Zaubers in Super-Machtpunkten dürfen wie üblich das Machtlimit der Kampagne nicht übersteigen. Er kann außerdem aktive Kräfte zwei Runden statt einer und passive Kräfte fünf Runden statt drei nutzen.", "Voraussetzung: Ein Charakter muss Okkultismus W10 oder höher haben, um diese Kraft zu nehmen."], "m": [["RÜCKSCHLAG", "–1", "Würfelt der Super mit der gestuntenen Kraft (nicht der ursprünglichen) einen Kritischen Fehlschlag, fluten übernatürliche Energien die Welt und verursachen 3W6 Schaden in einer Mittleren Flächenschablone. Unabhängig von der verbleibenden Dauer endet der Kraftstunt sofort."]], "s": ["SUP"], "p": 86}, {"n": "Schwingen", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Netzleinen, Seilwerfer", "b": ["Charaktere mit irgendeiner Art von Schnur, Seil, Gespinst oder anderen Enterleinen können sich mühelos durch bestimmte Umgebungen bewegen – etwa die hohen Gebäude großer Städte oder Dschungelbäume. Der Held kann solche Umgebungen mit Bewegungsweite 12 durchqueren, vertikal oder horizontal.", "Schwinger, die aus gefährlichen Höhen fallen, erhalten einen Athletikwurf, um sich irgendwo auf dem Weg nach unten abzufangen (Entscheidung der SL).", "Die Leine des Charakters kann sicher bis zu 500 Pfund tragen."], "m": [["STARKE LEINE", "+1/1000 Pfund", "Die Leine kann für jeden Punkt in diesem Modifikator sicher 1000 Pfund mehr tragen."]], "s": ["SUP"], "p": 87}, {"n": "Telekinese", "r": 5, "mp": "3", "rw": "", "wd": "", "au": "Geist über Materie, mentale Kraft, magische Belebung", "b": ["Telekinese ist die Fähigkeit, Objekte oder Kreaturen mit reinem Gedanken oder Willen zu bewegen. Die Kraft hat eine Reichweite von 12“ (24 Metern), eine Stärke von W6, und von ihr gehaltene Objekte können als begrenzte freie Aktion bis zu 6“ pro Zug bewegt werden.", "Ein Telekinet kann mehrere Gegenstände handhaben (abhängig von der Stärke der Kraft), aber jede Verwendung von Telekinese ist eine Aktion. Während ein Schurke also mehrere Pistolen mit Telekinese in der Luft schwenken könnte, kann er immer noch nur drei Aktionen ausführen (mit den üblichen Mehrfachaktionsabzügen).", "Telekinese erlaubt es einem Helden nicht, sich selbst anzuheben, es sei denn, er nimmt den Modifikator Flug unten.", "Telekinese kann anstelle jeder körperlichen Fertigkeit wie Kämpfen, Ringen, Schießen, Fahren und so weiter genutzt werden, aber der Charakter muss den niedrigeren Wert aus der üblichen Fertigkeit oder seinem Fokus verwenden. Ein hervorragender Telekinet muss immer noch wissen, wie man ein Flugzeug fliegt, um es zu steuern; er würfelt zum Beispiel den niedrigeren Wert aus Fokus oder Steuern, wenn er seine Kraft zum Fliegen nutzt.", "Nahkampfwaffen nutzen die Stärke der Telekinese statt ihrer eigenen, ebenso Quetschangriffe beim Ringen.", "Einen Gegner aufzuheben erfordert einen Ringen-Wurf (der Telekinet nutzt Fokus statt Athletik)."], "m": [["FEINKONTROLLE", "+3", "Der Charakter kann seine Fertigkeit Fokus bei körperlichen Handlungen nutzen (nicht den niedrigeren Wert aus Fokus oder der relevanten Fertigkeit)."], ["FLUG", "+2", "Der Held kann Telekinese auf sich selbst anwenden und erhält Flug mit Bewegungsweite 6."], ["KRAFT", "Variabel", "Alle zwei Super-Machtpunkte, die in diesen Modifikator gesteckt werden, erhöhen die Stärke der Kraft um eine Stufe."]], "s": ["SUP"], "p": 87}, {"n": "Telepathie", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Kommunikatoren, psychische Verbindung, Telefonkonferenz", "b": ["Der Charakter kann mit allen oder beliebigen intelligenten Geistern seiner Wahl innerhalb von 24“ (48 Metern) kommunizieren."], "m": [["REICHWEITE", "+2", "Der Telepath kann alle intelligenten Geister innerhalb einer Meile kontaktieren."], ["GEISTREITER", "+3", "Der Telepath kann durch die Sinne jedes willigen Geistes in Reichweite sehen, hören, schmecken, tasten und fühlen. Sobald die Kraft aktiviert ist, ist der Telepath Abgelenkt, bis er Geistreiter beendet. Einen unwilligen Geist zu „reiten“ ist ein Vergleichender Wurf aus Fokus des Telepathen gegen Verstand des Ziels. Bei Erfolg kann der Telepath das Ziel eine Stunde lang reiten. Mit einer Steigerung bemerkt das Ziel den Eingriff nicht."], ["SCHALTTAFEL", "+2", "Der Telepath kann alle freundlichen, intelligenten Geister in Reichweite verbinden. Alles, was die Einzelnen bewusst „sagen“, wird der gesamten Gruppe mitgeteilt."]], "s": ["SUP"], "p": 87}, {"n": "Teleportation", "r": 5, "mp": "2", "rw": "", "wd": "", "au": "Eine Rauchwolke, Magie, „Ausphasen“, Teleportationsscheiben", "b": ["Teleportation erlaubt es einem Charakter, zu verschwinden und augenblicklich bis zu 12“ (24 Meter) entfernt wieder zu erscheinen. Das ist eine Aktion und kann beliebig mit normaler Bewegung kombiniert werden. Er könnte zum Beispiel seine halbe Bewegungsweite zurücklegen, teleportieren und dann den Rest seiner Bewegungsweite (plus einen Laufwürfel, wenn er gerannt ist) zurücklegen.", "Angrenzende Gegner erhalten keinen Gratisangriff gegen den teleportierenden Charakter, wenn er verschwindet, wohl aber jene mit Erstschlag, wenn der Teleporter neben ihnen erscheint.", "Der Teleporter muss sein Ziel sehen können, um ohne Wurf zu teleportieren. Teleportiert er an einen Ort, den er zuvor gesehen hat, kann er das mit einem Fokuswurf sicher tun. Will er an einen zuvor ungesehenen Ort teleportieren, würfelt er mit –4. Misslingen bedeutet, dass der Charakter nicht teleportiert und Angeschlagen ist, bei einem Kritischen Fehlschlag Betäubt.", "Der Teleporter kann nie einen festen Raum betreten, selbst wenn er es versucht. Die Kraft bringt ihn wie oben sofort zu seinem Ausgangsort zurück.", "Andere mitnehmen: Der Teleporter kann willige Verbündete mitnehmen, aber er kann sie nicht unabhängig teleportieren, ohne den Modifikator Andere teleportieren (siehe unten). Der Teleporter muss die berühren, die er mitnehmen will, und einen Fokuswurf ablegen, auch wenn er das Zielgebiet sehen kann. Jede weitere Person zieht 1 von seinem Fokuswurf ab, und alle Wirkungen, die der Teleporter erleidet, werden von allen geteilt (Angeschlagen oder Betäubt durch Misslingen)."], "m": [["PORTAL", "+2", "Der Held kann innerhalb seiner Teleportationsreichweite ein Eingangs- und ein Ausgangsportal öffnen, sodass jeder, der an das Eingangsportal angrenzt, handeln kann, als wäre er an das Ausgangsportal angrenzend. Das erlaubt ihnen, Nahkampfangriffe auszuführen, Fernkampfangriffe aus verschiedenen Richtungen zu führen, Gegenstände zu übergeben usw. Es gewährt allerdings keinen Bonus für Gemeinsamer Angriff bei Nahkampfangriffen."], ["REICHWEITE", "+1/+2", "Für +1 Punkt steigt die Reichweite des Teleporters auf 24“, für +2 Punkte auf 48“."], ["SCHNELLE TELEPORTATION", "+1", "Der Charakter teleportiert sich sehr schnell um einen Gegner herum, um ihn in schneller Folge aus mehreren Winkeln anzugreifen. Wenn er diesen Modifikator nutzt, erhalten seine Nahkampfangriffe gegen ein Ziel einen Bonus von +2 für Gemeinsamer Angriff."], ["UMLEITEN", "+4", "Der Held muss die Modifikation Portal haben, um diese Fähigkeit zu nehmen. Wird der Held angegriffen, während er auf Halten ist, kann er einen Vergleichenden Wurf aus Fokus mit –2 gegen Verstand des Gegners ablegen. Bei Erfolg wird der Angriff des Feindes durch das Portal auf ihn selbst umgeleitet. Bei Erfolg auf den Fokuswurf nutze den Angriffswurf des Feindes gegen dessen normale Verteidigung."], ["ANDERE TELEPORTIEREN", "+5", "Der Teleporter kann Verbündete und Feinde in seiner Reichweite an jeden anderen Ort in seiner Reichweite teleportieren. Das ist eine Aktion und erfordert einen Fokuswurf mit –1 für jedes Ziel, das er teleportieren will. Feindliche Gegner dürfen einen Willenskraftwurf ablegen (mit –2 bei einer Steigerung auf den Fokuswurf), um zu widerstehen. Teleportiert der Super einen Feind hoch in die Luft, erleidet er wie üblich Sturzschaden (siehe Savage Worlds)."], ["DURCHQUEREN", "+3", "Mit einem Fokuswurf mit –2 kann sie bis zu 1.000 Meilen teleportieren. Mit einem Fokuswurf mit –4 kann sie überallhin auf dem Planeten teleportieren. Mit Erlaubnis der Spielleitung, und im Allgemeinen nur in Kampagnen mit hohem Machtniveau und unter besonderen Umständen, erlaubt ein Fokuswurf mit –8 dem Charakter, überallhin im Multiversum zu teleportieren. In jedem Fall kann der Charakter, wenn der Wurf misslingt, für den Rest der Begegnung nicht teleportieren!"]], "s": ["SUP"], "p": 88}, {"n": "Zähigkeit", "r": 5, "mp": "1 pro Stufe", "rw": "", "wd": "", "au": "Hünenhafte Brocken, dichte Haut, verstärkte Knochen, Kraftfelder, Widerstandsfähigkeit, Willenskraft", "b": ["Die Robustheit deines Charakters steigt um +1. Sie könnte besonders widerstandsfähig sein, mystischen Schutz haben, unzerbrechliche Haut, dichte Knochen usw.", "Robustheit wird nicht durch Panzerbrechende Angriffe negiert.", "Maximale Robustheit: Der kombinierte Bonus aus den Kräften Zähigkeit und Rüstung darf das Machtlimit der Kampagne nicht übersteigen. Die gesamte Robustheit ist unbegrenzt (durch erhöhte Konstitution, Größe usw.).", "Ein Super der Stufe V hat zum Beispiel ein Machtlimit von 25. Sie könnte 20 Punkte Rüstung (S. 52) und +5 Zähigkeit haben, oder jede andere Kombination von insgesamt 25 oder weniger Punkten, die zu ihrer abgeleiteten Robustheit addiert werden.", "Das Talent Der Beste hat keinen Einfluss auf dieses Limit."], "m": [["AKTIVIERUNG ERFORDERLICH", "–1", "Der Held muss einen Fokuswurf als Aktion ablegen, um diese Fähigkeit zu aktivieren. Verliert er die Konzentration, fährt sie herunter und muss neu aktiviert werden (siehe S. 42)."]], "s": ["SUP"], "p": 88}, {"n": "Übernatürliche Reflexe", "r": 5, "mp": "3", "rw": "", "wd": "", "au": "Erstaunliche Reflexe, außersinnliche Wahrnehmung, berechnete Flugbahnen, gesteigerter Gefahrensinn", "b": ["Der Held kann Flächenangriffen und -effekten möglicherweise ausweichen. Sie ignoriert den üblichen Abzug von –2 auf Geschicklichkeit bei Ausweichversuchen (siehe Savage Worlds) und erhält einen regulären Ausweichversuch gegen Flächenangriffe, die normalerweise keinen erlauben (mit dem Abzug von –2).", "Der Abzug auf den Athletikwurf des Helden, Granaten (oder ähnliche Waffen) zurückzuwerfen, wird ebenfalls um 2 verringert (siehe Mehr zu Granaten in Savage Worlds)."], "m": [["AKTIVIERUNG ERFORDERLICH", "–1", "Der Held muss einen Fokuswurf als Aktion ablegen, um diese Fähigkeit zu aktivieren. Verliert er die Konzentration, fährt sie herunter und muss neu aktiviert werden (siehe S. 42)."]], "s": ["SUP"], "p": 89}, {"n": "Untot", "r": 5, "mp": "8", "rw": "", "wd": "", "au": "Vampire, Lichs, Zombies, Wiedergänger", "b": ["Selbst die kalte Hand des Todes hält manche verzweifelte Seelen nicht auf. Das sind Untote – meist Vampire, Zombies, Lichs oder andere rachsüchtige Wiedergänger aus dem Grab. Manche mögen auf weniger finstere Weise zurückgekehrt sein, etwa als Cyborgs oder durch eine außergewöhnliche Reise zu und von einer der vielen Dimensionen des Todes.", "Die Einzelheiten der Fähigkeiten deiner Leichen hängen von seiner Herkunft ab, aber alle Untoten haben ein paar Dinge gemeinsam.", "Untote erhalten +2 auf ihre Robustheit, addieren +2 auf Würfe, um sich von Angeschlagen zu erholen, atmen und essen nicht, sind immun gegen Krankheit und Gift und erleiden keinen zusätzlichen Schaden durch Gezielte Angriffe. Untote Wildcards ignorieren einen Punkt Wundabzüge und verbluten nicht.", "Untote profitieren nicht von der Fertigkeit Heilung, natürlicher Heilung oder auch nur der Kraft Heilung (ohne den Modifikator Funke des Lebens, siehe unten). Sie sollten besser Regeneration nehmen, wenn sie nicht zu einem Haufen Knochen verfallen wollen."], "m": [["FUNKE DES LEBENS", "+2", "Die Wunden des Geschöpfs können durch magische Heilung wiederhergestellt werden (die Superkraft oder die Kraft Heilung in Savage Worlds)."]], "s": ["SUP"], "p": 89}, {"n": "Fahrzeug", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Thematische Motorräder, Autos, Flugzeuge, Jets und andere Fahrzeuge", "b": ["Der Held hat ein besonderes Fahrzeug, angepasst mit Spezialgadgets und vielleicht sogar Waffen.", "Normale Fahrzeuge können gekauft werden (siehe S. 18), aber solche, die mit Super-Machtpunkten entworfen werden, lassen sich leichter anpassen und werden irgendwie ersetzt, wenn sie zerstört werden (siehe unten).", "Superfahrzeuge sind als Kräfte relativ billig, aber nimm an, dass sie in den meisten Abenteuern und Kampagnen nur in sehr bestimmten Situationen genutzt werden können, etwa bei Verfolgungsjagden oder Kämpfen im Freien.", "Diese Kraft profitiert nie vom Modifikator Gerät.", "Ein Fahrzeug erschaffen: Das Grundfahrzeug ist ein einsitziges, landgestütztes Gefährt mit folgenden Werten: Größe 0, Handhabung 0, Höchstgeschwindigkeit 60 mph, Robustheit 9 (2), Besatzung 1. Addiere Modifikationen aus der Liste unten, um es weiter anzupassen.", "Wrack: Fahrzeuge müssen in einer Werkstatt repariert werden, entweder in der eigenen Basis des Helden (siehe S. 21) oder bei einem verbündeten Mechaniker, der ein Geheimnis zu wahren weiß.", "Wird ein Fahrzeug zerstört, erhält der Held irgendwie in der nächsten Sitzung ein neues, oder indem er einen Punkt Überzeugung ausgibt. Spieler und Spielleitung sollten zusammen herausfinden, wie genau das geschieht.", "Ist es ein Wrack, gehen die Reparaturen vielleicht schneller als gedacht. Ist es verloren, hat ein Reicher Charakter vielleicht ein Ersatzfahrzeug, oder ein wohlhabender Gönner bietet einen Ersatz an.", "In jedem Fall darf der Charakter das Fahrzeug umkonfigurieren, wenn sie will. Ein Jet, der im Ozean abgestürzt ist, könnte zum Beispiel durch ein gepanzertes Geländefahrzeug ersetzt werden. Der Punktwert sollte gleich bleiben, aber das Design kann sich ändern, wie es in der Geschichte sinnvoll ist und angesichts der verfügbaren Zeit und Ressourcen."], "m": [["GEPANZERT", "+2/+4", "Für +2 Punkte hat das Fahrzeug 4 Punkte Panzerung statt 2. Für +4 Punkte hat das Fahrzeug Schwere Panzerung. Für mehr Panzerung nimm die Kraft Rüstung mit dem unten aufgeführten Modifikator Superkräfte."], ["PANZERGLAS", "+1", "Das Fahrzeug hat kugelsicheres Glas an allen Fenstern (Härte 12)."], ["GESCHLOSSEN", "+1", "Das Fahrzeug ist geschlossen, und seine Panzerung schützt die Insassen. Der Besitzer muss entscheiden, ob es Fenster hat oder nicht. Wenn ja, können Insassen wie üblich anvisiert werden (siehe Savage Worlds). Wenn nicht, können Insassen nicht durch sie anvisiert werden, aber der Fahrer muss sich auf Elektronik verlassen, um nach draußen zu sehen."], ["SCHLEUDERSITZE", "+1", "Als freie Aktion kann der Fahrer alle oder einige Passagiere des Fahrzeugs sicher ausschleudern. Wie das funktioniert, hängt vom Fahrzeug ab, aber Schleudersitze haben typischerweise Fallschirme. Im Weltraum oder unter Wasser könnte der Sitz sich in einer kleinen Kapsel mit ein paar Tagen grundlegender Lebenserhaltung versiegeln."], ["FLUG", "+1", "Das Fahrzeug fliegt mit 60 mph und hat Senkrechtstart- und Landefähigkeit. (Nimm eine Einschränkung von 1 Punkt, wenn nicht.)"], ["HANDHABUNG", "+1/+2", "Addiere +1 auf die Handhabung des Fahrzeugs für einen Punkt, oder +2 für zwei Punkte."], ["PASSAGIERE", "+1/+2/+4", "Addiere +1 für ein Fahrzeug, das einen zusätzlichen Passagier fassen kann (das Maximum für ein Fahrzeug der Größe 0). Für +2 fasst das Fahrzeug zwei Passagiere pro Größenpunkt, und für +4 fasst es bis zu vier zusätzliche Personen pro Größenpunkt."], ["GRÖSSE", "+1/Größe", "Erhöhe Größe und Robustheit des Fahrzeugs für jeden zusätzlich ausgegebenen Machtpunkt um 1, bis zu einem Maximum von Größe 11 (Riesig). Große und Riesige Fahrzeuge erhalten zusätzlich Wunden (siehe Fahrzeuge in Savage Worlds). Fahrzeuge im Normalen Maßstab können das Doppelte ihrer Größe an zusätzlichen Passagieren fassen (zusätzlich zu den mit der Option „Passagiere“ gekauften). Große Fahrzeuge fassen das Dreifache ihrer Größe an Passagieren. Riesige Fahrzeuge fassen bis zum Vierfachen ihrer Größe an Passagieren."], ["SUPERKRÄFTE", "+2/+5", "Nutze diesen Modifikator, um dem Fahrzeug Rüstung, Graben und andere Kräfte zu geben. Für +2 Punkte hat es so viele Super-Machtpunkte wie das Machtlimit der Machtkategorie (hat selbst aber kein Limit). Für +5 Punkte hat das Fahrzeug so viele Punkte wie das Machtniveau der Kampagne selbst. Es muss sich wie üblich an das Machtlimit halten, nimm also Supertalent, um bei Bedarf das Talent „Der Beste“ zu nehmen. Auf diese Weise gekaufte Fahrzeuge haben bereits 7 Punkte in Geschwindigkeit, oder 8 Punkte in Flug, wenn sie den Modifikator Flug haben. Super-Machtpunkte aus diesem Modifikator dürfen genutzt werden, um sie über die Grundgeschwindigkeit von 60 mph hinaus zu steigern. Superfahrzeuge haben einen Fokus von W8 + Wildcard-Würfel für alle Kräfte, die ihn erfordern, oder der Besitzer kann seinen eigenen Fokuswurf nutzen, wenn er am Steuer sitzt. Er kann auch den Kraftmodifikator Alternatives Attribut (S. 44) nehmen, um die Eigenschaft auf Fahren, Elektronik usw. zu ändern."], ["WAFFEN", "Speziell", "Addiere +2 Punkte, um eine Impuls-Gatling einzubauen (+1, wenn sie nur nach vorn feuern kann), oder +4 Punkte für jede Impulskanone (+3, wenn sie nur nach vorn feuern kann). Diese können nach Wahl des Helden Verbunden sein oder nicht. Nutze Fernkampfangriff mit der Superkräfte-Modifikation für andere Angriffsarten. Fahrzeuge normaler Größe dürfen nicht mehr als zwei Fernkampfwaffen aus dieser Modifikation haben. Große Fahrzeuge nicht mehr als vier, Riesige nicht mehr als 6 und Gigantische nicht mehr als 8."]], "s": ["SUP"], "p": 89}, {"n": "Wandkrabbler", "r": 5, "mp": "1", "rw": "", "wd": "", "au": "Haftporen, Supergriff, zusätzliche Gliedmaßen", "b": ["Menschen schauen nie nach oben. Deshalb werden jene, die an Wänden oder Decken gehen können, selten bemerkt – bis es zu spät ist!", "Wandkrabbler können auf waagerechten Flächen mit ihrer normalen Bewegungsweite gehen (und rennen), auf umgekehrten Flächen mit halber Bewegungsweite."], "m": [["FESTER GRIFF", "+1", "Wandkrabbler sind notorisch schwer von der Stelle zu bewegen, wenn sie nicht wollen. Wenn sie sich entscheiden, standzuhalten, halbieren sie die Weite jedes Rückstoßes, den sie erleiden."]], "s": ["SUP"], "p": 91}, {"n": "Wetterkontrolle", "r": 5, "mp": "7", "rw": "", "wd": "", "au": "Wind und Starkregen", "b": ["Diese beeindruckende Fähigkeit erlaubt es einem Charakter, Stürme herbeizurufen oder aufzulösen, kühlenden Regen zu bringen, die Erde mit einer plötzlichen Hitzewelle zu versengen oder sogar Schnee in die heißesten Gegenden zu bringen. Sie kann sogar das Wetter der nächsten 24 Stunden in einem Umkreis von 50 Meilen mit vernünftiger Genauigkeit vorhersagen.", "Widerstand: Wetterkontrolleure haben eine Stufe Umweltresistenz (S. 61) gegen die Machttypen Luft, Elektrizität, Feuer und Wasser.", "Wetter beeinflussen: Außerhalb des Kampfes kann der Held die örtlichen Wetterbedingungen beeinflussen, um Regen, Schnee, Sonne und Wind in einem Umkreis von etwa fünf Meilen zu bringen oder zu zerstreuen. Die Stärke hängt von der örtlichen Umgebung ab – eine raue Wüste erhält vielleicht sanften Regen, während eine feuchte Umgebung einen peitschenden Wolkenbruch oder Blizzard bekommt. Diese Art von Effekten hält so lange an, wie die Kontrolleurin es will. Sobald sie sich nicht mehr darauf konzentriert, klingen sie je nach Größe des Gebiets und Umgebung in einigen Minuten oder Stunden ab. Die genauen Effekte liegen bei der SL, umfassen aber eingeschränkte Sicht, rutschigen Boden, extreme Hitze oder Kälte usw.", "Kampfeffekte: Wetterkontrolle kann gebündelt werden, um Feinde zu bedrängen und zu schikanieren. Die Kraft auf diese Weise zu aktivieren ist ein Fokuswurf, der eine „Sturmfront“ beschwört. Die Front ist eine Kugel von der Größe einer Großen Flächenschablone, die bis zu 12“ (24 Meter) entfernt erscheint. Der Kontrolleur kann die Front als begrenzte freie Aktion um bis zu 6“ (12 Meter) pro Zug bewegen, solange sie in Sichtweite bleibt.", "Als begrenzte freie Aktion kann der Kontrolleur einen der folgenden Effekte innerhalb der Sturmfront aktivieren oder deaktivieren:", "Dämpfen: Der Wetterkontrolleur gewährt allen in der Schablone Umweltresistenz gegen wetterbezogene Machttypen: Luft, Kälte, Elektrizität, Feuer und Wasser.", "Ablenken: Alle in der Schablone sind durch eisigen Wind, sengende Hitze, Starkregen oder Gewitter Abgelenkt. Entferne den Zustand am Ende ihres Zugs wie üblich, wenn sie nicht mehr in der Schablone sind.", "Andere Fähigkeiten: Mächtigere Fähigkeiten müssen als andere Kräfte gekauft werden – Fernkampfangriff für Blitzschläge, Stoßen für Windböen, Wirbelwind für Wirbelstürme und dergleichen.", "Herunterfahren: Wetterkontrolle endet, wenn der Super die Konzentration verliert. Siehe Herunterfahren auf S. 42."], "m": [["NUR IM FREIEN", "–2", "Der Held kann Kampfeffekte nur im Freien herbeirufen, und nur in geeigneten Geländearten, wenn es für die Situation wichtig ist. Sie kann zum Beispiel in der Arktis keine Hitzewelle verursachen oder in der Wüste keine Sintflut herbeirufen."]], "s": ["SUP"], "p": 91}, {"n": "Wirbelwind", "r": 5, "mp": "3", "rw": "", "wd": "", "au": "Ein wirbelnder Strudel aus Luft, Feuer, Trümmern usw.", "b": ["Der Super erschafft einen wirbelnden Zyklon aus Luft, Energie oder Materie, der seine Feinde zerstreuen und durcheinanderbringen kann.", "Den Wirbelwind zu erheben erfordert einen Fokuswurf. Bei Erfolg platziert der Super eine Mittlere Flächenschablone irgendwo innerhalb von 12“ (24 Metern). Sie kann die Schablone als begrenzte freie Aktion um bis zu 6“ (12 Meter) pro Zug bewegen, solange sie in Sichtweite bleibt.", "Jeder in der Schablone am Ende des Zugs des Supers ist Abgelenkt und muss einen Stärkewurf ablegen (mit –2 bei einer Steigerung auf den Fokuswurf). Wer misslingt, erleidet 2W6“ Rückstoß in eine zufällige Richtung (3W6“ bei einer Steigerung). Das kann zusätzlichen Schaden verursachen, wenn sie ein festes Objekt treffen (siehe S. 29).", "Der Super kann den Wirbelwind als freie Aktion auflösen."], "m": [["FLÄCHENEFFEKT", "+2", "Der Super kann die Mittlere Flächenschablone zu einer Großen Flächenschablone erweitern."], ["SCHADEN", "+2", "Jeder, der nach Abhandlung seines Stärkewurfs noch in der Schablone ist, erleidet 2W6 Schaden."], ["KEGEL", "+0/+1", "Für 0 Punkte nutzt der Wirbelwind die Kegelschablone, die vom Super ausgeht. Für 1 Punkt kann der Angriff nach Wunsch zwischen Kegel- und Flächenschablone wechseln."], ["STARK", "+2", "Die Stärkewürfe des Ziels werden mit einem zusätzlichen –2 abgelegt."]], "s": ["SUP"], "p": 92}]);
H.reg([{"id": "sup_regeln", "t": "Superkräfte-Regeln", "p": 41, "s": ["SUP"], "bl": [{"b": ["Auf den folgenden Seiten findest du Dutzende Kräfte für tollkühne Helden und finstere Schurken, dazu Modifikatoren, mit denen du Tausende Superfähigkeiten erschaffen kannst – oder unendlich viele, wenn man ihre Ausprägungen und Machttypen bedenkt! So liest und nutzt du die Beschreibung jeder Kraft:"]}, {"h": "Kosten", "b": ["Der Preis jeder Kraft steht in Klammern hinter ihrem Namen in Super-Machtpunkten. Beachte, dass Super-Machtpunkte nicht zum Aktivieren von Kräften genutzt werden wie bei den Arkanen Hintergründen in Savage Worlds. Einmal gekauft, funktionieren Superkräfte einfach, wenn sie aktiviert werden.", "Keine Kraft darf mehr als einmal genommen werden, sofern nichts anderes dabeisteht, und jede gilt für Talente wie Der Beste und für Machtlimits als eigene Kraft."]}, {"h": "Stufen", "b": ["Manche Kräfte sprechen von „Stufen“. Das bezeichnet, wie oft eine Kraft genommen wurde (sofern sie mehr als einmal genommen werden kann). Wird Superattribut zum Beispiel fünfmal genommen, hat der Held fünf Stufen darin."]}, {"h": "Ausprägungen", "b": ["Das sind Ideen dafür, wie eine Kraft aussehen könnte oder woher sie kommt. Ausprägungen sind im Allgemeinen erzählerisch und beschreibend, spielen aber eine Rolle bei der Bestimmung von Machttypen (siehe S. 43)."]}, {"h": "Kraftmodifikatoren", "b": ["Bei jeder Kraft sind bestimmte Modifikatoren aufgeführt, mit denen du eine Fähigkeit anpassen kannst, samt den Punkten, die sie kosten oder dir sparen. Nach allen Modifikatoren betragen die Mindestkosten einer Kraft 1."]}, {"h": "Ausprägungen im Kraftsystem", "b": ["Ausprägungen sind die „Geheimzutat“ des Savage-Worlds-Kraftsystems. Sie lassen dich schnell und einfach unendlich viele Kräfte mit ähnlichen Wirkungen erschaffen, sodass du nicht ständig nachschlagen musst, was eine bestimmte Version bewirkt.", "Auf den ersten Blick wirkt das vielleicht nach weniger als in anderen Spielen, weil es keine einzelnen Kräfte für Eisstrahlen, Feuerstrahlen usw. gibt. Aber all das und mehr ist hier enthalten – wie es sich zeigt, liegt nur an dir und deiner Fantasie, statt an eigenen Regeln für jeden Aspekt einer ähnlichen Kraft.", "In diesem Buch kann eine einzelne Fernkampfangriff-Kraft alles darstellen, von Feuerstößen über Salven dunkler Energie bis zu Wellen beißender Insekten. Die Kraft Rüstung kann einen vollen Körperpanzer darstellen oder den dicken Chitinpanzer eines Insektoiden. Übernatürliche Reflexe können alles sein, von außersinnlichen Warnungen über schnelle Reflexe bis zu reinem Glück.", "Alles, was Spielleiter und Spieler tun müssen, ist sie zu beschreiben und alle besonderen Modifikatoren nachzuschlagen, die die Kraft eines Einzelnen haben könnte."]}, {"h": "Kraftaktivierung", "b": ["Passive Kräfte wie Rüstung oder Zähigkeit erfordern keinen Fertigkeitswurf zur Aktivierung – sie sind immer an, sofern ein Charakter nicht den Modifikator Aktivierung erforderlich genommen hat (verfügbar für bestimmte Kräfte und in ihrer Beschreibung aufgeführt).", "Aktive Kräfte nennen den Fertigkeitswurf, der zur Aktivierung nötig ist, etwa Fokus zur Aktivierung der Kraft Furcht. Das ist immer eine Aktion, sofern die Kraft nichts anderes sagt.", "Kräfte, die eine Aktivierung erfordern, enden, wenn ein Held Kampfunfähig wird, bewusstlos geschlagen wird oder schläft. Er kann sie auch selbst als freie Aktion beenden.", "Kritischer Fehlschlag: Sofern eine Kraft keinen eigenen Effekt nennt, macht ein Kritischer Fehlschlag bei ihrer Aktivierung den Super Abgelenkt und Verwundbar. Das ist schnell überwunden, kann aber im falschen Moment verheerend sein!", "Sichtlinie: Die Reichweite jeder Kraft steht in ihrer Beschreibung, aber die Zielperson oder der Einschlagspunkt muss immer in Sichtweite sein, sofern nichts anderes dasteht. Sicht kann „Fernsicht“ durch magische, psychische oder technische Mittel einschließen, wenn die Spielleitung es für den Machttyp angemessen hält. Schablonen müssen so platziert werden, dass ihre Mitte in Sichtlinie liegt."]}, {"h": "Reichweite von Flächeneffekten", "b": ["Sagt eine Kraft, dass eine Schablone irgendwo innerhalb von 12“ (24 Metern) um den Charakter platziert wird, miss bis zum Mittelpunkt der Schablone. Alles, was auch nur teilweise von der Schablone berührt wird, ist betroffen (das macht das Wirkungsgebiet größer als dargestellt, hält aber unsere Schablonen in vernünftiger Größe).", "Schablonen, die bewegt werden können, wie die bewegliche Version der Kraft Kraftfeld, dürfen so weit bewegt werden, wie die Kontrolleurin will – solange sie sie noch sehen kann. Miss die Bewegung vom Mittelpunkt aus."]}, {"h": "Herunterfahren", "b": ["Manche Kräfte „fahren herunter“, wenn der Super die Konzentration verliert. Wird ein Charakter mit einer solchen Kraft Angeschlagen oder Betäubt, muss er einen Willenskraftwurf schaffen, sonst fahren alle diese Kräfte nach Abhandlung der Aktion, die den Effekt verursacht, sofort herunter. Ein Charakter, der einen Angeschlagen-Effekt sofort mit einem Bennie aufhebt (oder alle Wunden eines Angriffs auffängt), muss nicht würfeln. Solche Kräfte enden automatisch, wenn der Held Kampfunfähig wird."]}, {"h": "Machttypen", "b": ["Kräfte wie Energiekontrolle verlangen, dass der Spieler eine bestimmte Art von Energie oder Materie wählt, die die Kraft nutzt oder beeinflusst. Diese heißen „Machttypen“, und die üblichen Kategorien, aus denen du wählen kannst, werden unten beschrieben.", "Machttypen beruhen auf Comic-Klischees, nicht auf der harten Wissenschaft der echten Welt. Stolpere nicht darüber, dass Dunkelheit in der echten Welt keine Energieart ist oder warum Eis unter Kälte statt unter Wasser steht. Wichtig ist ihr Thema. Ein „Eismann“ sollte zum Beispiel eisige Böen erzeugen, Eissplitter schleudern oder es schneien lassen können. Zusammen sind das Funktionen von „Kälte“-Kräften in Comics, und so kategorisieren wir sie hier."]}, {"h": "Machttypen: Energie und Materie", "k": 1, "s": ["SUP"], "b": [], "tab": {"c": ["Energie", "Materie"], "r": [["Kälte (Frost, Eis)", "Luft"], ["Dunkelheit", "Biologisch (Tiere, Menschen, Schläge, Tritte)"], ["Elektrizität (Blitze)", "Erde (Glas, Sand, Stein)"], ["Feuer (Hitze)", "Metall (Kugeln, Messer)"], ["Kraft (Kraftfelder, Kraftprojektionen, Schwerkraft, Magnetismus)", "Pflanze (meiste Stoffe, Seil)"], ["Licht (Laser)", "Synthetisch (Plastik)"], ["Magie (spirituell, übernatürlich)", "Wasser (Flüssigkeiten)"], ["Mental (Hypnose, Psionik)", ""], ["Strahlung", ""], ["Schall", ""], ["Zeitlich (Zeitkräfte)", ""]]}}, {"h": "Mehrere Machttypen", "b": ["Besteht eine Kraft oder ein Gegenstand aus mehreren Machttypen, besteht sie für die Zwecke des Spiels aus allen. Das heißt: Wirkt eine Verteidigung gegen irgendeinen Teil einer kombinierten Kraft oder eines Gegenstands, wirkt sie gegen alles davon. Der Superschurke Boomer (S. 110) hat zum Beispiel einen verfluchten Bumerang. Sein Machttyp ist also Magie (für den Fluch) und Pflanze (für den hölzernen Bumerang).", "Beispiel: Ein flammendes magisches Schwert besteht aus Feuer-Energie, Magie-Energie und Metall-Materie. Ein Gegner mit Resistenz gegen irgendeinen davon hat Resistenz gegen den vom Schwert verursachten Schaden."]}, {"h": "Ausprägungen als Machttypen", "b": ["Wird eine Kraft in Begriffen beschrieben, die einem Machttyp entsprechen, ist sie dieser Machttyp. Illusion, die mit Zauberei gewirkt wird, ist zum Beispiel Magie. Illusionen aus gebrochenem Licht sind der Machttyp Licht. Ebenso ist Furcht, die als Wirkung einer übel riechenden Blume beschrieben wird, der Materietyp Pflanze, oder Mental, wenn sie dem Opfer seine schlimmsten Ängste zeigt."]}, {"h": "Kraftmodifikatoren (allgemein)", "b": ["Die meisten Kräfte haben spezifische Modifikatoren, die ihre Nutzung gegen höhere oder niedrigere Kosten erweitern oder einschränken, aber ein paar Modifikatoren gelten für viele Fähigkeiten.", "Modifikatoren dürfen kombiniert werden. Betäuben könnte zum Beispiel Bedingt auf einen Fernkampfangriff mit den Modifikatoren Reichweite und Gerät sein.", "Modifikatoren dürfen die Kosten einer Kraft nie unter 1 senken."]}, {"h": "Alternatives Attribut (+1)", "b": ["Manche Kräfte erfordern zur Aktivierung einen Eigenschaftswurf, etwa Fokus, aber du kannst eine andere Fertigkeit bestimmen, solange es Sinn ergibt und die SL zustimmt.", "Das wird meist genutzt, um die Kraft eines Charakters in einer Fertigkeit zu „zentralisieren“, etwa bei einem Magier, der Zaubern statt Fokus nutzen will, um einen Gegner zu verstricken. Es kann auch genutzt werden, um die Ausprägung einer Kraft genauer abzubilden, etwa Athletik, um eine Verstrick-Granate zu werfen, statt Fokus (die Standardfertigkeit für Verstricken).", "Die genutzte Eigenschaft sollte auch widerspiegeln, wie die Kraft übermittelt wird. Fokus bei Heilung könnte ein Lichtstrahl sein, der aus den Augen des Supers strahlt. Der Wechsel auf die Fertigkeit Heilen bedeutet, dass der Held nah herangehen und mit den Händen arbeiten muss (und den Modifikator Berührung erforderlich nutzen sollte). Denk daran, dass Kräfte, egal wie sie konfiguriert sind, auch erzählerisch Sinn ergeben müssen!", "Talente: Alternative Eigenschaften beeinflussen keine Talente, die bestimmte Attribute oder Fertigkeiten für ihre Voraussetzungen oder Nutzung erfordern. Das Talent Scharfschütze gilt zum Beispiel nur für Athletik und Schießen, selbst wenn ein Charakter Fokus oder Zaubern für den Fernkampfangriff nutzt."]}, {"h": "Bedingt/Verbunden (0/+2)", "b": ["Bedingte Kräfte aktivieren nur, wenn eine andere Aktion erfolgreich ist – sie können nicht für sich genutzt werden.", "Verbundene Kräfte können aktivieren, wenn eine andere Aktion erfolgreich ist, und auch für sich genutzt werden. Das erhöht die Kosten der Verbundenen Kraft um +2 Punkte.", "Aktivierung: Bedingte und Verbundene Kräfte werden aktiviert, wenn ein Eigenschaftswurf für eine „primäre“ Aktion gelingt – etwa einen Angriff oder die Aktivierung einer anderen Kraft. Die Kraft Verfall, Verbunden mit einem Fernkampfangriff, könnte zum Beispiel einen „nekrotischen Strahl“ erzeugen. Die primäre Aktion muss dafür einen erfolgreichen Eigenschaftswurf erfordern, entweder von Natur aus oder mit dem Modifikator Aktivierung erforderlich, den manche passiven Kräfte haben. Fähigkeiten, die „immer an“ sind, können keine Bedingten oder Verbundenen Kräfte auslösen.", "Es spielt keine Rolle, ob der erfolgreiche Eigenschaftswurf tatsächlich Schaden verursacht oder Wirkung hat; er muss nur das Ziel treffen, einen Gegner zum Widerstehen zwingen oder das Ziel in einem Vergleichenden Wurf schlagen. Ein erfolgreicher Schadensangriff, der vom Feind aufgefangen wird, ist zum Beispiel für Kräfte, die mit ihm Verbunden oder Bedingt darauf sind, immer noch erfolgreich.", "Nutze den Eigenschaftswurf der Primärkraft für beide Ergebnisse. Ist Nahkampfangriff mit Betäuben Verbunden, nutze zum Beispiel den Kämpfenwurf für beide Ergebnisse.", "Beispiel: Arrowhead (S. 103) hat einen Fesselpfeil (Verstricken, Bedingt auf einen Fernkampfangriff). Sie muss ihr Ziel zuerst mit einem Schießenwurf treffen. Ihr Schießenergebnis wird auch zur Aktivierung von Verstricken genutzt.", "Einmal pro Aktion: Bedingte und Verbundene Kräfte sind auf einmal pro Aktion beschränkt. Ist Verstricken zum Beispiel mit einem Fernkampfangriff mit Feuerrate 3 Verbunden, wird es nur einmal ausgelöst (der Spieler entscheidet vor dem Würfeln, welcher Schuss betroffen ist). Ebenso aktiviert Verfall, wenn es mit Kämpfen Verbunden ist und der Angreifer Raserei hat, nur bei einem der Kämpfenwürfel (Wahl des Spielers).", "Reichweite: Bedingte und Verbundene Kräfte nutzen bei dieser Aktivierung die Reichweite der Primärkraft oder -waffe. Beispiel: Verstricken hat normalerweise Reichweite 12“, aber wenn es mit einem Fernkampfangriff Verbunden ist, löst es bei der Reichweite dieser Kraft aus (typischerweise 12/24/48).", "Widerstand: Wird eine Kraft oder Eigenschaft widerstanden, widersteht das Ziel zuerst der Primärkraft. Gelingt das, widersteht es automatisch auch der Sekundärkraft. Misslingt es, muss es dann wie üblich der Bedingten oder Verbundenen Kraft widerstehen. Beispiel: Verfall ist mit Gedankenkontrolle Verbunden. Widersteht das Ziel der Gedankenkontrolle, widersteht es automatisch auch Verfall. Misslingt es, muss es Verfall separat widerstehen.", "Berührung erforderlich: Der Modifikator Berührung erforderlich, den manche Kräfte haben, darf genommen werden, wenn die Kraft mit einem Nahkampfangriff oder einer anderen Kraft, die ebenfalls Körperkontakt erfordert, Verbunden oder darauf Bedingt ist. „Berührung“ schließt freundlichen oder verstohlenen Kontakt außerhalb des Kampfes ein, etwa eine flüchtige Berührung, einen freundlichen Händedruck oder eine Hand auf der Schulter. Im Kampf schließt sie Ringen und alle Kämpfenangriffe ein – auch mit Waffen. Es spielt keine Rolle, ob der Super, der die Kraft nutzt, Handschuhe trägt oder der Verteidiger eine Metallrüstung – „Berührung“ umfasst jeden körperlichen Kontakt zwischen dem Super und seinem Ziel. Will ein Ziel nicht berührt werden, muss der Angreifer einen Nahkampf- oder Berührungsangriff ausführen, um seine Kraft zu aktivieren. Gelingt er, darf er dann als freie Aktion würfeln, um seine Kraft zu aktivieren. Beispiel: Ratkins Infektion ist Bedingt auf seinen Kämpfenangriff (Klauen), also kann er den Modifikator Berührung erforderlich nehmen. Er würfelt und handelt seinen Kämpfenwurf ab, und bei Erfolg handelt er den Schaden ab und würfelt dann als freie Aktion Fokus für seine Infektion."]}, {"h": "Gerät (–1/–2)", "b": ["Da sie weggenommen werden können, sind Kräfte leicht verbilligt, wenn sie von einem Gerät statt von einer angeborenen Fähigkeit des Supers stammen. Der Nachlass hängt davon ab, wie leicht der Besitzer sein Gerät verlieren kann:", "Ist das Gerät ein tragbarer Gegenstand oder für einen Feind relativ schwer zu entfernen, etwa eine Rüstung, Maske, Helm oder Gürtel, senke die Kosten um 1.", "Ist der Gegenstand leicht zu entfernen – etwa ein Amulett oder Stirnband – oder handgehalten und somit fallen zu lassen oder zu entwaffnen – etwa ein magischer Stab oder eine Schusswaffe – senke die Kosten um 2.", "Eine Kraft, die als Gerät gekauft wurde, funktioniert nie für andere Charaktere, gleich welche Form sie annimmt.", "Verlorene Geräte: Geht ein Gerät verloren, muss der Held versuchen, es wiederzubeschaffen, um seine Kraft zurückzuerhalten. Wird es zerstört, sollte die Spielleitung ein schwieriges Abenteuer oder eine schwierige Aufgabe erschaffen, mit der er schließlich Ersatz erlangt und seine Fähigkeiten zurückgewinnt.", "Verliert ein Held ein Gerät mit Superattribut oder Superfertigkeit, gehen alle Talente oder andere Fähigkeiten verloren, die diese als Voraussetzung nutzten, bis das Gerät wiedererlangt ist."]}, {"h": "„Geräte“ anderer Charaktere nutzen", "k": 1, "s": ["SUP"], "b": ["Charaktere können keine Geräte anderer Helden nutzen, die als Geräte beschrieben sind. Warum nicht?", "Erst das Offensichtliche. Erzählerisch sind es Geräte, aber in Spielbegriffen sind es die Kräfte dieses Charakters, und es würde Probleme machen, wenn eine Gruppe von Helden oder Schurken ihre Fähigkeiten frei tauschen könnte.", "Zweitens können sie es tatsächlich, wenn sie einen Kraftstunt nutzen. Sagen wir, ein Selbstjustiz-Held hat eine mächtige futuristische Waffe, die er als Fernkampfangriff nutzt. Ein anderer Super könnte den Stunt Nachahmen nutzen, um zu sagen, dass er sie sich für einen Schuss leiht. Sicher, das ist teuer (ein Kraftstunt kostet einen Bennie), aber es erlaubt jene gelegentlichen Szenen in einem Comic oder Film, in denen ein Held die Spezialwaffe eines anderen aufhebt. Das verhindert auch, dass es zu oft geschieht und das Markenzeichen des anderen Charakters stiehlt, oder dass ein Held herumsitzt und nur „Waffen“ an die anderen verteilt. So müssen alle mitmachen und Teil der Geschichte werden wie ein echtes Superteam."]}, {"h": "Wuchtig (+1)", "b": ["Jedes Mal, wenn der Held mit dieser Kraft Rückstoß (S. 30) verursacht, addiere +1W6 auf die Gesamtweite, die ein Feind zurückgeschleudert wird."]}, {"h": "Schwere Waffe (+1)", "b": ["Der Angriff ist eine Schwere Waffe. Panzerung mit dem Merkmal Schwere Panzerung ignoriert Schaden durch alle Angriffe, die nicht als Schwere Waffen vermerkt sind, daher ist das ein entscheidender Modifikator, um jene besonders schwierigen und hochgepanzerten Schurken und Monster zu knacken!"]}, {"h": "Einschränkung (–1/–2)", "b": ["Manche Kräfte funktionieren nur in bestimmten Situationen oder gegen bestimmte Ziele. Ist das Verbot selten, kommt aber gelegentlich ins Spiel, ist es einen Punkt Nachlass wert. Beispiele sind Energiekontrolle, die einen bestimmten Machttyp oder die Farbe Rot nicht beeinflussen kann, oder ein Fernkampfangriff, der nicht gegen Untote wirkt.", "Alles, was die Kraft etwa die Hälfte der Zeit am Funktionieren hindert, ist 2 Punkte Nachlass wert. Sie könnte nur nachts wirken, nur in Gebäuden, nur gegen Männer oder nur gegen Außerirdische in einem galaktischen Spiel.", "Auch die Natur der Kampagne sollte berücksichtigt werden. Eine Betäubungswaffe, die nur unter Wasser funktioniert, könnte in den meisten Spielen eine seltene Einschränkung sein, in einer Geschichte in Atlantis aber sehr häufig!"]}, {"h": "Reichweite (+2/+4)", "b": ["Du kannst alle angegebenen Reichweiten einer Kraft für 2 Punkte verdoppeln oder für 4 verdreifachen. Das gilt für Kräfte mit Reichweitenabstufungen wie 12/24/48 und für solche mit fester Reichweite, etwa 6“ oder Verstand (um sie auf das 2- oder 3-Fache von Verstand zu bringen).", "Der Modifikator Reichweite gilt nicht bei Nutzung einer Kegelschablone und darf nicht mit dem Modifikator Berührung erforderlich genommen werden."]}, {"h": "Selektiv (+1)", "b": ["Der Super kann wählen, einzelne oder alle Ziele innerhalb der Flächenschablone einer Kraft nicht zu beeinflussen, etwa alle Feinde statt der Verbündeten bei einer Flächenversion von Furcht."]}, {"h": "Speziell (?)", "b": ["Diese Kategorie ist ein Sammelbecken für sehr spezifische Modifikatoren, die ein Charakter haben könnte und die nicht sauber in eine der anderen Kategorien passen. Die meisten Modifikatoren sollten im Bereich von +/–2 Punkten liegen, aber das ist ein Vorschlag und keine harte Regel.", "Vielleicht ermüdet die Nutzung einer bestimmten Kraft den Charakter. Das ist ein Nachlass von zwei Punkten, wenn die Kraft etwa einmal pro Begegnung genutzt wird. Wird sie selten genutzt, vielleicht nur ein Punkt Nachlass. Arbeite mit der SL einen Preis aus und probiere ihn aus. Du kannst später immer daran feilen, wenn ihr beide findet, dass er zu niedrig oder zu hoch angesetzt ist."]}, {"h": "Umschaltbar (+1)", "b": ["Die meisten Kräfte können nicht mehr als einmal genommen werden, aber Umschaltbar erlaubt einem Charakter mehrere Versionen derselben Kraft.", "Jede Variante kostet +1 Machtpunkt und muss gleich oder niedriger sein als die ursprünglichen Kosten der Originalkraft (ohne den Modifikator Umschaltbar).", "Eine Umschaltbare Kraft könnte sich nur in Ausprägung (und Machttyp) unterscheiden oder eine völlig andere Konfiguration sein. Ein Elementarheld könnte zum Beispiel einen 10-Punkte-Fernkampfangriff auf Wasserbasis nehmen und dann Umschaltbar +3 addieren, um Luft-, Feuer- und Erdversionen zu erhalten, zwischen denen sie nach Belieben wechseln kann. Jede davon könnte andere Kombinationen aus Schaden und Modifikatoren nutzen, solange alle kleiner oder gleich den ursprünglichen 10 Punkten sind."]}, {"h": "Zusammenfassung der allgemeinen Kraftmodifikatoren", "k": 1, "s": ["SUP"], "b": [], "tab": {"c": ["Modifikator", "Wirkung"], "r": [["Alternatives Attribut (+1)", "Die Kraft nutzt eine andere Eigenschaft als die in ihrer Beschreibung genannte."], ["Bedingt/Verbunden (0/+2)", "Bedingte und Verbundene Kräfte werden durch eine Primärkraft ausgelöst. Bedingte Kräfte können nur mit einer Primärkraft genutzt werden; Verbundene Kräfte können bei Bedarf auch einzeln genutzt werden."], ["Gerät (–1/–2)", "Die Kraft ist ein Gerät, das entfernt oder verloren werden kann, etwa eine Rüstung oder ein Helm, für 1 Punkt. Für 2 Punkte ist der Gegenstand ein Handgerät, das leichter fallen gelassen oder dem Helden abgenommen werden kann."], ["Wuchtig (+1/+2)", "Die Rückstoßweite wird um +1W6 erhöht."], ["Schwere Waffe (+1)", "Der Angriff kann jene verletzen, die durch Schwere Panzerung geschützt sind."], ["Einschränkung (–1/–2)", "Eine seltene Einschränkung, die die Nutzung der Kraft verhindert, senkt die Kosten um 1 Punkt. Eine häufige Einschränkung (wirkt etwa die Hälfte der Zeit) senkt die Kosten um 2."], ["Reichweite (+2/+4)", "Verdopple die Reichweite einer Kraft für 2 Punkte oder verdreifache sie für +4."], ["Selektiv (+1)", "Der Super kann wählen, welche Ziele in ihrer Flächenkraft davon betroffen sind."], ["Speziell (?)", "Jeder Modifikator, den Spieler und SL für angemessen halten und der nicht von anderen Modifikatoren abgedeckt wird."], ["Umschaltbar (+1)", "Der Held hat eine oder mehrere andere Versionen einer Kraft (zu denselben Grundkosten in Super-Machtpunkten)."]]}}, {"h": "Kraftsets", "b": ["Wenn du einen Charakter erschaffen willst, der in verschiedenen Gestalten verschiedene Kräfte hat, und deine Spielleitung es erlaubt, nutze diese Option. Sie ist etwas aufwendiger, erlaubt aber seltsame Charaktere wie einen verbrechenlösenden Okkult-Detektiv, der sich in einen wütenden Werwolf verwandeln kann. Oder ein Alienwesen aus reiner Energie, das in einer Gestalt Plasmablitze feuert und in einer anderen zu einem kristallinen Nahkämpfer wird. (Du solltest vielleicht auch das Handicap Verwandlung auf S. 9 in Betracht ziehen.)", "Die Kosten jedes Sets in Super-Machtpunkten stehen in der Tabelle unten. Jedes Kraftset hat dann gleich viele Punkte (wie viele auch immer übrig sind). Jedes hat außerdem ein verringertes Machtlimit.", "Der Wechsel zwischen Kraftsets erfordert einen Fokuswurf als Aktion (würfle nur einmal, wenn der Charakter das Handicap Verwandlung hat). Ein Kritischer Fehlschlag bedeutet, dass der Held für den Rest dieser Begegnung nicht auf das gewünschte Kraftset zugreifen kann!"]}, {"h": "Kraftset-Kosten und Machtlimits", "k": 1, "s": ["SUP"], "b": ["Beispiel: Gabe spielt einen Charakter namens Cybertooth. Wenn er einen Knopf an seinem Handgelenkcomputer drückt (und einen Fokuswurf ablegt), verwandelt er sich von einem Cyborg in einen Werwolf. Er hat zwei Kraftsets – eines für seine Technikfähigkeiten und eines für seine wilde Werwolfgestalt. Das Machtniveau ist III, also muss er 8 Super-Machtpunkte zahlen, um ein zweites Kraftset zu haben. Jedes Set hat 22 Super-Machtpunkte statt der üblichen 30 und ein Machtlimit von 12 statt der üblichen 15."], "tab": {"c": ["Machtniveau", "Kosten", "Limit"], "r": [["I", "3 SMP", "4 SMP"], ["II", "5 SMP", "8 SMP"], ["III", "8 SMP", "12 SMP"], ["IV", "10 SMP", "16 SMP"], ["V", "12 SMP", "20 SMP"]]}}]}]);
})();
